<?php
#----------------[  admin section  ]------------------#
// The panel is Persian, in every language the bot speaks.
//
// This file matches a tapped reply-keyboard button by its text, so it can only
// be Persian if its keyboards are built in Persian too. They are: keyboard.php
// builds the panel from panel_texts() and the shop from $customer_texts, and
// this line is the other half of that same split. Changing one without the
// other prints a button in one language and compares it in the other, which
// kills it silently - including the button that opens the panel.
//
// index.php restores its own copy right after requiring this file, so the shop
// keeps answering in the reader's language.
$textbotlang = panel_texts();
$textadmin = ["panel", "/panel", $textbotlang['Admin']['panelAdmin']];

if (!in_array($from_id, $admin_ids))
    return;
$domainhostsEscaped = htmlspecialchars($domainhosts, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');

$miniAppInstructionText = sprintf($textbotlang['Admin']['webpanel']['miniAppHelp'], $domainhostsEscaped);

// 🎨's editors ask for a name, an emoji or a sticker in a message of the
// admin's own. The ask - and its "send it again" reply - comes with this inline
// cancel, not $backadmin: a reply keyboard replaces the admin's own bottom
// keyboard and stayed there after the answer was saved, until one of its two
// buttons was tapped to get the real one back.
$btpromptcancel = json_encode(['inline_keyboard' => [[['text' => '❌ انصراف', 'callback_data' => 'btpromptcancel', 'style' => 'danger']]]]);
if ($datain === 'btpromptcancel' && $adminrulecheck['rule'] == "administrator") {
    step('home', $from_id);
    deletemessage($from_id, $message_id);
    return;
}
// 🎨: which screen each message shows, and where a screen several others open
// was opened from - its 🔙 goes back there (bt_origin_track)
if (is_string($datain) && $datain !== '' && $adminrulecheck['rule'] == "administrator") {
    bt_origin_track($from_id, $message_id, $datain, (array) ($update['callback_query']['message']['reply_markup']['inline_keyboard'] ?? []));
}

//----------------[  🤖 web panel: address, login, a password of the admin's own, on/off  ]----------------
// «پنل تحت وب ربات 🤖» (it was «✅ فعالسازی پنل تحت وب») used to make a new
// password on every tap, so a second tap locked the admin out of a panel he
// was logged into. It makes one only the first time now; after that it shows
// the address and username with 🌐 ورود, 🔐 تغییر رمز and the panel's on/off
// switch under them, and the password stays until he sets one himself - his
// message with it and the ask are then deleted and the details message shows
// the new one. Off (webpanel_enabled), the panel takes no login at all.
if (!function_exists('webpanel_info')) {
    // the details message and its glass buttons; $pass: the password to show
    // (just made or just set), null: the one he already has. Off, there is no
    // 🌐 ورود - the panel would only turn him away.
    function webpanel_info($adminId, $pass, $title, $textbotlang)
    {
        global $domainhosts;
        $w = $textbotlang['Admin']['webpanel'];
        $on = webpanel_enabled();
        $passLine = $pass !== null ? '<code>' . htmlspecialchars($pass) . '</code>' : $w['passKept'];
        $text = $title . sprintf($w['details'], htmlspecialchars($domainhosts), $adminId, $passLine);
        $rows = [];
        if ($on) {
            $rows[] = [['text' => $w['loginBtn'], 'url' => "https://{$domainhosts}/panel/", 'style' => 'primary']];
        }
        $rows[] = [['text' => $w['changePassBtn'], 'callback_data' => 'webpanel_pass', 'style' => 'danger']];
        $rows[] = [['text' => sprintf($w['toggleBtn'], $on ? $w['stateOn'] : $w['stateOff']), 'callback_data' => 'webpanel_toggle', 'style' => $on ? 'success' : 'danger']];
        return [$text, json_encode(['inline_keyboard' => $rows])];
    }
}
if ($datain === 'webpanel_toggle' && $adminrulecheck['rule'] == "administrator") {
    $wp_on = !webpanel_enabled();
    update("setting", "web_panel_status", $wp_on ? 'on' : 'off', null, null);
    clearSelectCache('setting');
    // a password this message already shows stays on it - only while it is
    // still his (checked against the saved hash), never anything else
    $wp_shown = null;
    if (preg_match('/🔑[^:\n]*:\s*(\S+)\s*$/mu', (string) $text_inline, $wp_m)) {
        $wp_admin = select("admin", "*", "id_admin", $from_id, "select");
        if (is_array($wp_admin) && password_verify($wp_m[1], (string) $wp_admin['password'])) {
            $wp_shown = $wp_m[1];
        }
    }
    $wp_title = $textbotlang['Admin']['webpanel'][$wp_on ? 'turnedOn' : 'turnedOff'];
    [$wp_text, $wp_kb] = webpanel_info($from_id, $wp_shown, $wp_title, $textbotlang);
    Editmessagetext($from_id, $message_id, $wp_text, $wp_kb, 'HTML');
    telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => trim($wp_title)]);
    return;
}
if ($datain === 'webpanel_pass' && $adminrulecheck['rule'] == "administrator") {
    $wp_ask = sendmessage($from_id, $textbotlang['Admin']['webpanel']['askPass'], $btpromptcancel, 'HTML');
    update("user", "Processing_value", json_encode(['wp_msgid' => (int) $message_id, 'wp_ask' => (int) ($wp_ask['result']['message_id'] ?? 0)]), "id", $from_id);
    step('webpanel_pass', $from_id);
    return;
}
if ($user['step'] === 'webpanel_pass' && $datain == '' && $adminrulecheck['rule'] == "administrator") {
    $wp = json_decode((string) ($user['Processing_value'] ?? ''), true);
    $wp = is_array($wp) ? $wp : [];
    $wp_pass = trim((string) $text);
    // whatever he sent leaves the chat - a password, or a wrong try at one
    deletemessage($from_id, $message_id);
    if ($wp_pass === '' || preg_match('/\s/u', $wp_pass) || mb_strlen($wp_pass) < 6 || mb_strlen($wp_pass) > 64) {
        // the ask says why (a second wrong try leaves it as it is: "not modified")
        $wp_res = !empty($wp['wp_ask']) ? Editmessagetext($from_id, (int) $wp['wp_ask'], $textbotlang['Admin']['webpanel']['passInvalid'], $btpromptcancel, 'HTML') : null;
        if (empty($wp_res['ok']) && strpos((string) ($wp_res['description'] ?? ''), 'not modified') === false) {
            sendmessage($from_id, $textbotlang['Admin']['webpanel']['passInvalid'], $btpromptcancel, 'HTML');
        }
        return;
    }
    update("admin", "username", $from_id, "id_admin", $from_id);
    update("admin", "password", password_hash($wp_pass, PASSWORD_BCRYPT, ['cost' => 12]), "id_admin", $from_id);
    step('home', $from_id);
    if (!empty($wp['wp_ask'])) {
        deletemessage($from_id, (int) $wp['wp_ask']);
    }
    [$wp_text, $wp_kb] = webpanel_info($from_id, $wp_pass, $textbotlang['Admin']['webpanel']['passChanged'], $textbotlang);
    $wp_res = !empty($wp['wp_msgid']) ? Editmessagetext($from_id, (int) $wp['wp_msgid'], $wp_text, $wp_kb, 'HTML') : null;
    if (empty($wp_res['ok']) && strpos((string) ($wp_res['description'] ?? ''), 'not modified') === false) {
        sendmessage($from_id, $wp_text, $wp_kb, 'HTML');
    }
    return;
}

