//----------------[  button color manager  ]----------------
if (!function_exists('color_editor_payload')) {
    function color_editor_payload($mode, $textbotlang, $lang = 'fa')
    {
        $rows = mainmenu_layout_get($lang)['keyboard'];
        // The button names are a live preview of what THIS language's customer
        // sees, so they come from its own file - the surrounding chrome stays
        // Persian like the rest of the panel. Same split keyboard_list_text()
        // draws between an item's label and its preview.
        $labels = menu_button_labels(lang_tab_texts($lang));
        $styleEmoji = ['' => '⚪', 'primary' => '🔵', 'success' => '🟢', 'danger' => '🔴'];
        $field = ($mode == 'r') ? 'style_reply' : 'style';
        $kb = ['inline_keyboard' => []];
        foreach ($rows as $r => $row) {
            if (!is_array($row)) {
                continue;
            }
            $kbRow = [];
            foreach ($row as $c => $btn) {
                if (!is_array($btn) || !isset($btn['text'])) {
                    continue;
                }
                $name = $btn['text'];
                if (isset($labels[$name])) {
                    $name = $labels[$name];
                }
                $style = (isset($btn[$field]) && in_array($btn[$field], ['primary', 'success', 'danger'], true)) ? $btn[$field] : '';
                $kbBtn = [
                    'text' => (!empty($btn['hidden']) ? '🚫 ' : '') . $name . ' ' . $styleEmoji[$style],
                    'callback_data' => "btncolor-{$mode}-{$lang}-{$r}-{$c}"
                ];
                if ($style !== '') {
                    $kbBtn['style'] = $style;
                }
                $kbRow[] = $kbBtn;
            }
            if (!empty($kbRow)) {
                $kb['inline_keyboard'][] = $kbRow;
            }
        }
        $kb['inline_keyboard'][] = [['text' => '🔙 بازگشت به منوی قبلی', 'callback_data' => "btnset_open:color:{$lang}", 'style' => 'danger']];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['bottext']['btn_close'], 'callback_data' => 'bt_close', 'style' => 'danger']];
        return json_encode($kb);
    }
}

if (!function_exists('um_tab')) {
    // 👤 مدیریت کاربر has a tab per language: every list, message, top-up and
    // gift started from it is about that language's users only, and amounts are
    // in that language's currency. The tab an admin is on is kept on their own
    // row (um_lang), so each step of a longer flow knows it.
    function um_tab($adminRow)
    {
        $l = is_array($adminRow) ? (string) ($adminRow['um_lang'] ?? '') : '';
        return in_array($l, panel_langs(), true) ? $l : 'fa';
    }
    function um_lang_name($lang, $textbotlang)
    {
        return $textbotlang['bottext']['langs'][$lang] ?? $lang;
    }
    // 👤 جستجوی کاربر: a numeric id as before, or a @username (with or without
    // the @ - the bot keeps each user's Telegram username). Anything else comes
    // back as it was, for the caller's «not a user».
    function um_resolve_user($input)
    {
        global $pdo;
        $s = trim((string) $input);
        if ($s === '' || preg_match('/^\d+$/', $s)) {
            return $s;
        }
        $name = ltrim($s, '@');
        if (!preg_match('/^[A-Za-z][A-Za-z0-9_]{2,31}$/', $name)) {
            return $s;
        }
        $st = $pdo->prepare("SELECT id FROM user WHERE LOWER(username) = LOWER(?) LIMIT 1");
        $st->execute([$name]);
        $id = $st->fetchColumn();
        return $id !== false ? (string) $id : $s;
    }
    // Took a service out of its panel? [true, ''] when it is gone - or was
    // never there, or its panel is no longer in the bot, so there is nothing
    // left to delete - and [false, reason] when the panel refused or did not
    // answer. Marking a service «removed» in the bot used to ignore this, so a
    // timeout left it deleted here and alive in the panel.
    function um_panel_remove(array $inv)
    {
        return clean_panel_remove($inv);
    }
    // a user's services that still exist: every invoice that is not unpaid and
    // not already removed (removebyadmin, removebyuser, removeTime, ...)
    function um_live_services($userId)
    {
        global $pdo;
        $st = $pdo->prepare("SELECT * FROM invoice WHERE id_user = ? AND Status <> 'Unpaid' AND Status NOT LIKE 'remove%'");
        $st->execute([(string) $userId]);
        return $st->fetchAll(PDO::FETCH_ASSOC);
    }
    // 👀 a user's screen: its 24 rows were too many to find anything in. 'main'
    // is an index of sections; each section brings its own buttons and a 🔙 to
    // it, under the same message (um_info_kb_edit). An on/off pair shows the
    // one that applies now.
    function um_info_kb($id, array $u, $section, $tx)
    {
        global $setting;
        $k = $tx['keyboard'];
        $m = $tx['Admin']['manageUser'];
        $t = $tx['Admin']['UserMgmt'];
        $b = fn($text, $cb, $style = 'primary') => ['text' => $text, 'callback_data' => $cb, 'style' => $style];
        $sec = fn($text, $s) => $b($text, "umsc:{$s}:{$id}");
        $agent = (string) ($u['agent'] ?? 'f');
        if ($section === 'bal') {
            $rows = [
                [$b($m['addBalanceUser'], "addbalanceuser_{$id}", 'success'), $b($m['lowBalanceUser'], "lowbalanceuser_{$id}", 'danger')],
                [$b($k['zeroBalance'], "zerobalance-{$id}", 'danger'), $b($k['discountPercent'], "Percentlow_{$id}")],
                [$b($m['viewPaymentUser'], "viewpaymentuser_{$id}")],
            ];
        } elseif ($section === 'svc') {
            $rows = [
                [$b($m['viewOrderUser'], "vieworderuser_{$id}"), $b($k['addOrder'], "addordermanualـ{$id}", 'success')],
                [$b($k['deactivateAccount'], "disableconfig-{$id}", 'danger'), $b($k['activateAccount'], "activeconfig-{$id}", 'success')],
                [$b($k['transferAccount'], "transferaccount_{$id}"), $b($k['testAccountLimit'], "limitusertest_{$id}")],
            ];
            if (intval($setting['statuslimitchangeloc'] ?? 0) == 1) {
                $rows[] = [$b($k['changeLocationLimit'], "changeloclimitbyuser_{$id}")];
            }
            $rows[] = [$b($k['cronMessageStatus'], "statuscronuser-{$id}")];
        } elseif ($section === 'aff') {
            $blk = (string) ($u['aff_block'] ?? '');
            $c = strpos($blk, 'c') !== false;
            $r = strpos($blk, 'r') !== false;
            $state = $c && $r ? $t['affBlockStateBoth'] : ($c ? $t['affBlockStateC'] : ($r ? $t['affBlockStateR'] : $t['affBlockStateNone']));
            $rows = [
                [$b($k['userAffiliates'], "affiliates-{$id}")],
                [$b(strtr($t['affBlockBtn'], ['{state}' => $state]), "umab:{$id}", ($c || $r) ? 'danger' : 'primary')],
                [$b($t['affrwResetBtn'], "affrwzero_{$id}", 'danger')],
                [$b($k['removeFromAffiliate'], "removeaffiliate-{$id}", 'danger'), $b($k['deleteUserAffiliates'], "removeaffiliateuser-{$id}", 'danger')],
            ];
        } elseif ($section === 'acc') {
            $rows = [
                [strtolower((string) ($u['User_Status'] ?? '')) === 'block'
                    ? $b($m['unbanUserList'], "unbanuserr_{$id}", 'success') : $b($m['banUserList'], "banuserlist_{$id}", 'danger')],
                [$b($t['purgeBtn'], "umpurge_{$id}", 'danger')],
                [(string) ($u['verify'] ?? '0') === '1'
                    ? $b($k['unauthUser'], "unverify-{$id}", 'danger') : $b($k['authenticateUser'], "verify_{$id}", 'success')],
                [(string) ($u['cardpayment'] ?? '0') === '1'
                    ? $b($k['deactivateCard'], "carduserhide-{$id}", 'danger') : $b($k['activateCard'], "showcarduser-{$id}", 'success')],
                [$b($m['confirmNumber'], "confirmnumber_{$id}", 'success'), $b($k['verifyChannelMembership'], "confirmchannel-{$id}", 'success')],
            ];
        } elseif ($section === 'agent') {
            if ($agent === 'f') {
                $rows = [[$b($m['addagent'], "addagent_{$id}", 'success')]];
            } else {
                $rows = [[$b($t['agentChangeType'], "addagent_{$id}"), $b($m['removeagent'], "removeagent_{$id}", 'danger')]];
                if ($agent === 'n2') {
                    $rows[] = [$b($k['agentPurchaseCap'], "maxbuyagent_{$id}")];
                }
                $rows[] = [$b($k['activateSalesBot'], "createbot_{$id}", 'success'), $b($k['deleteSalesBot'], "removebotsell_{$id}", 'danger')];
                $rows[] = [$b($k['baseVolumePrice'], "setvolumesrc_{$id}"), $b($k['baseTimePrice'], "settimepricesrc_{$id}")];
                $rows[] = [$b($k['hidePanelForAgent'], "hidepanel_{$id}", 'danger'), $b($k['showHiddenPanels'], "removehide_{$id}", 'success')];
                $rows[] = [$b($k['agentExpireTime'], "expireset_{$id}")];
            }
        } else {
            $lang = in_array($u['lang'] ?? '', panel_langs(), true) ? $u['lang'] : 'fa';
            return ['inline_keyboard' => [
                [$b($k['refreshInfoAlt'], "updateinfouser_{$id}"), $b(strtr($t['langBtn'], ['{lang}' => um_lang_name($lang, $tx)]), "umsetlang_{$id}")],
                [$sec($t['secBalance'], 'bal'), $sec($t['secServices'], 'svc')],
                [$sec($t['secAff'], 'aff'), $sec($t['secAccess'], 'acc')],
                [$sec($t['secAgent'], 'agent'), $b($k['sendMessageToUser'], "sendmessageuser_{$id}")],
            ]];
        }
        $rows[] = [$b($t['secBack'], "umsc:main:{$id}", 'danger')];
        return ['inline_keyboard' => $rows];
    }
    // ...one section of it on the message $mid, the text left as it is
    function um_info_kb_edit($chat, $mid, $id, $section, $tx)
    {
        $u = select("user", "*", "id", (string) $id, "select", ['cache' => false]);
        if (!is_array($u) || (int) $mid <= 0) {
            return;
        }
        telegram('editMessageReplyMarkup', ['chat_id' => $chat, 'message_id' => $mid, 'reply_markup' => json_encode(um_info_kb($id, $u, $section, $tx))]);
    }
    // ⛔️ مسدود از زیرمجموعه‌گیری: a message of its own under the user's screen
    // ($mid), whose 👥 row it keeps up to date
    function um_affblock_payload($id, $tx, $mid)
    {
        $t = $tx['Admin']['UserMgmt'];
        $u = select("user", "*", "id", (string) $id, "select", ['cache' => false]);
        $c = aff_blocked($id, 'c');
        $r = aff_blocked($id, 'r');
        $st = fn($on) => $on ? $t['affBlockOn'] : $t['affBlockOff'];
        $tg = is_array($u) ? (string) ($u['username'] ?? '') : '';
        $who = (!in_array($tg, ['', 'none', 'NOT_USERNAME'], true) ? '@' . htmlspecialchars($tg) . ' ' : '') . "<code>{$id}</code>";
        $text = strtr($t['affBlockCaption'], ['{user}' => $who, '{c}' => $st($c), '{r}' => $st($r)]);
        $rows = [
            [['text' => strtr($t['affBlockToggleC'], ['{state}' => $st($c)]), 'callback_data' => "umabt:c:{$id}:{$mid}", 'style' => $c ? 'danger' : 'success']],
            [['text' => strtr($t['affBlockToggleR'], ['{state}' => $st($r)]), 'callback_data' => "umabt:r:{$id}:{$mid}", 'style' => $r ? 'danger' : 'success']],
            [($c && $r)
                ? ['text' => $t['affBlockNoneBtn'], 'callback_data' => "umabt:n:{$id}:{$mid}", 'style' => 'success']
                : ['text' => $t['affBlockAll'], 'callback_data' => "umabt:b:{$id}:{$mid}", 'style' => 'danger']],
            [['text' => $t['affBlockClose'], 'callback_data' => 'umabx', 'style' => 'danger']],
        ];
        return [$text, json_encode(['inline_keyboard' => $rows])];
    }
    function um_hub_caption($lang, $textbotlang)
    {
        $t = $textbotlang['Admin']['UserMgmt'];
        $counts = um_lang_counts();
        $lines = [];
        foreach (panel_langs() as $l) {
            $lines[] = strtr($t['countLine'], ['{lang}' => um_lang_name($l, $textbotlang), '{n}' => number_format($counts[$l] ?? 0)]);
        }
        return strtr($t['hubCaption'], [
            '{lang}' => um_lang_name($lang, $textbotlang),
            '{counts}' => implode("\n", $lines),
            '{total}' => number_format($counts['total']),
            '{wallet}' => money(um_lang_wallet_sum($lang), currency_for_lang($lang)),
        ]);
    }
    // $canCustomize: an administrator, who can open 🎨 from here
    function um_hub_payload($lang, $textbotlang, $canCustomize = false)
    {
        $k = $textbotlang['keyboard'];
        $rows = [
            panel_lang_tabs($lang, "umlang:%s", null),
            [['text' => $k['usersWithBalance'], 'callback_data' => "uml:balance:1", 'style' => 'primary']],
            [['text' => $k['usersWithAffiliates'], 'callback_data' => "uml:ref:1", 'style' => 'primary']],
            [['text' => $k['activeCardUserList'], 'callback_data' => "uml:card:1", 'style' => 'primary']],
            [['text' => $k['usersWithNegativeBalance'], 'callback_data' => "uml:neg:1", 'style' => 'danger']],
            [['text' => $k['agentList'], 'callback_data' => "agentlistusers", 'style' => 'primary'], ['text' => $k['allUserList'], 'callback_data' => "uml:all:1", 'style' => 'primary']],
            [['text' => $k['searchOrder'], 'callback_data' => "searchorder", 'style' => 'primary'], ['text' => $k['groupCharge'], 'callback_data' => "balanceaddall", 'style' => 'success']],
            [['text' => $k['searchUserBtn'], 'callback_data' => "searchuser", 'style' => 'primary'], ['text' => $k['messagingSection'], 'callback_data' => "systemsms", 'style' => 'success']],
        ];
        // 🎁 حجم یا زمان گروهی (bulkgift.php) opens the administrator's own
        // screen of 🏬 تنظیمات فروشگاه - for any other role it would do nothing
        if ($canCustomize) {
            $rows[] = [['text' => $k['groupVolumeOrTime'], 'callback_data' => "voloume_or_day_all", 'style' => 'success']];
        }
        if ($canCustomize) {
            $rows[] = [['text' => $textbotlang['Admin']['UserMgmt']['assignBtn'], 'callback_data' => "svcgive|start", 'style' => 'primary']];
            // 🧹 balances / referrals / the bot's services, to zero (cleanup.php)
            $rows[] = [['text' => $textbotlang['Admin']['CleanTools']['btn'], 'callback_data' => "cln|menu|" . clean_scope_code($lang), 'style' => 'danger']];
        }
        if ($canCustomize) {
            $rows[] = [['text' => $textbotlang['Admin']['UserMgmt']['customizeBtn'], 'callback_data' => "bt_group|{$lang}|usermgmt"]];
        }
        return json_encode(['inline_keyboard' => $rows]);
    }
    // each list: its title, and what it asks of a user on top of the language
    function um_list_kinds($textbotlang)
    {
        $k = $textbotlang['keyboard'];
        return [
            'all' => [$k['allUserList'], "1 = 1"],
            'balance' => [$k['usersWithBalance'], "Balance > 0"],
            'neg' => [$k['usersWithNegativeBalance'], "Balance < 0"],
            'ref' => [$k['usersWithAffiliates'], "affiliatescount != '0'"],
            'card' => [$k['activeCardUserList'], "cardpayment = '1'"],
            'agent' => [$k['agentList'], "agent != 'f'"],
            'agent_n' => [$k['agentList'] . ' (n)', "agent = 'n'"],
            'agent_n2' => [$k['agentList'] . ' (n2)', "agent = 'n2'"],
        ];
    }
    // one page of a list of this tab's users - the six lists used to be three
    // copies each of the same screen, none of them aware of a language
    function um_list_payload($kind, $lang, $page, $textbotlang)
    {
        global $pdo;
        $kinds = um_list_kinds($textbotlang);
        if (!isset($kinds[$kind])) {
            $kind = 'all';
        }
        [$title, $cond] = $kinds[$kind];
        [$lw, $lp] = user_lang_where($lang);
        $st = $pdo->prepare("SELECT COUNT(*) FROM user WHERE {$lw} AND {$cond}");
        $st->execute($lp);
        $n = (int) $st->fetchColumn();
        $per = 10;
        $pages = max(1, (int) ceil($n / $per));
        $page = max(1, min($pages, (int) $page));
        $st = $pdo->prepare("SELECT * FROM user WHERE {$lw} AND {$cond} ORDER BY id LIMIT " . (($page - 1) * $per) . ", {$per}");
        $st->execute($lp);
        $rows = [[
            ['text' => $textbotlang['keyboard']['operation'], 'callback_data' => "action"],
            ['text' => $textbotlang['keyboard']['username'], 'callback_data' => "username"],
            ['text' => $textbotlang['keyboard']['userId'], 'callback_data' => "iduser"],
        ]];
        foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $r) {
            $name = (string) ($r['username'] ?? '');
            $name = ($name === '' || $name === 'none') ? '—' : $name;
            // a money list says how much, in that user's own wallet currency
            if ($kind === 'balance' || $kind === 'neg') {
                $name .= ' · ' . money($r['Balance'], currency_for_user($r));
            }
            $rows[] = [
                ['text' => $textbotlang['Admin']['manageUser']['manageUserBtn'], 'callback_data' => "manageuser_" . $r['id'], 'style' => 'primary'],
                ['text' => $name, 'callback_data' => "username"],
                ['text' => (string) $r['id'], 'callback_data' => (string) $r['id']],
            ];
        }
        if ($pages > 1) {
            // next on the left, previous on the right, as the old lists had them
            $nav = [];
            if ($page < $pages) {
                $nav[] = ['text' => $textbotlang['users']['page']['next'], 'callback_data' => "uml:{$kind}:" . ($page + 1), 'style' => 'primary'];
            }
            $nav[] = ['text' => "{$page} / {$pages}", 'callback_data' => "uml:{$kind}:{$page}"];
            if ($page > 1) {
                $nav[] = ['text' => $textbotlang['users']['page']['previous'], 'callback_data' => "uml:{$kind}:" . ($page - 1), 'style' => 'primary'];
            }
            $rows[] = $nav;
        }
        $rows[] = [['text' => $textbotlang['keyboard']['backToPrev'], 'callback_data' => 'backlistuser', 'style' => 'danger']];
        $t = $textbotlang['Admin']['UserMgmt'];
        $cap = strtr($n > 0 ? $t['listCaption'] : $t['listEmpty'], [
            '{title}' => $title,
            '{lang}' => um_lang_name($lang, $textbotlang),
            '{n}' => number_format($n),
        ]);
        return [$cap, json_encode(['inline_keyboard' => $rows])];
    }
    // the users a group top-up or a message goes to: this language, this user
    // group ('all', 'f', 'n', 'n2'), buyers or not (optionally of one panel)
    function um_group_where($lang, $agent, $buyers, $panelName = null)
    {
        [$w, $p] = user_lang_where($lang, 'u');
        // the "n" group's button has always sent "nl", which matched nobody
        $agent = $agent === 'nl' ? 'n' : (string) $agent;
        if ($agent !== '' && $agent !== 'all') {
            $w .= " AND u.agent = ?";
            $p[] = $agent;
        }
        if ($buyers === 'customer') {
            $w .= " AND EXISTS (SELECT 1 FROM invoice i WHERE i.id_user = u.id" . ($panelName !== null ? " AND i.Service_location = ?" : "") . ")";
            if ($panelName !== null) {
                $p[] = $panelName;
            }
        } elseif ($buyers === 'notcustomer' || $buyers === 'nonecustomer') {
            $w .= " AND NOT EXISTS (SELECT 1 FROM invoice i WHERE i.id_user = u.id)";
        }
        return [$w, $p];
    }
    // what 🎨 has for one of this section's messages on a tab
    function um_item_sticker($key, $lang)
    {
        $setting = select("setting", "*", null, null, "select");
        $layout = json_decode((string) ($setting['keyboardmain'] ?? ''), true);
        $map = (is_array($layout) && is_array($layout['text_stickers'] ?? null)) ? $layout['text_stickers'] : [];
        return function_exists('bt_effective_sticker') ? (string) bt_effective_sticker($map, $key, $lang) : '';
    }
    function um_item_custom_text($key, $lang)
    {
        $setting = select("setting", "*", null, null, "select");
        $te = json_decode((string) ($setting['text_edit'] ?? ''), true);
        return is_array($te) && bottext_dotted_isset($te[$lang] ?? null, $key);
    }
    // 👁 a message exactly as a customer of $lang gets it: 🎨's text, its
    // button as 🎨 has it (tapping it here only says it is a preview), and a
    // word on what else 🎨 sends with it
    function um_preview_payload($lang, $key, $text, $alias, $textbotlang)
    {
        $t = $textbotlang['Admin']['UserMgmt'];
        $notes = [um_item_custom_text($key, $lang) ? $t['previewCustomText'] : $t['previewDefaultText']];
        $notes[] = um_item_sticker($key, $lang) !== '' ? $t['previewSticker'] : $t['previewNoSticker'];
        $kb = null;
        if ($alias !== null) {
            $bkey = genbtn_alias_to_key($alias);
            $btn = genbtn_render(genbtn_defs($alias, lang_tab_texts($lang))[0], genbtn_override($lang, $bkey, 0), 'umprev');
            $kb = json_encode(['inline_keyboard' => [[$btn]]]);
            if (in_array($alias, genbtn_tap_sticker_aliases(), true) && genbtn_tap_sticker($lang, $bkey) !== '') {
                $notes[] = $t['previewTapSticker'];
            }
        }
        $cap = strtr($t['previewHead'], ['{lang}' => um_lang_name($lang, $textbotlang)])
            . "\n➖➖➖➖➖➖➖➖➖➖\n" . $text
            . "\n➖➖➖➖➖➖➖➖➖➖\n" . implode("\n", $notes);
        return [$cap, $kb];
    }
    // "📨 what the user (English) got:" and the text itself, under a report
    function um_sent_quote($userRow, $sent, $textbotlang)
    {
        $l = in_array($userRow['lang'] ?? '', panel_langs(), true) ? $userRow['lang'] : 'fa';
        return "\n\n" . strtr($textbotlang['Admin']['UserMgmt']['sentHead'], ['{lang}' => um_lang_name($l, $textbotlang)]) . "\n<blockquote>" . $sent . '</blockquote>';
    }
    // what 🎨 has for a tab's broadcasts, in a few words
    function um_bcast_settings($lang, $textbotlang)
    {
        $t = $textbotlang['Admin']['UserMgmt'];
        $n = 0;
        foreach (['b1', 'b2', 'b3', 'b4', 'b5', 'b6'] as $al) {
            if (!empty(genbtn_override($lang, genbtn_alias_to_key($al), 0))) {
                $n++;
            }
        }
        return strtr($t['bcSettings'], [
            '{tpl}' => um_item_custom_text('users.broadcast.message', $lang) ? $t['setCustom'] : $t['setDefault'],
            '{sticker}' => um_item_sticker('users.broadcast.message', $lang) !== '' ? $t['setSticker'] : $t['setNoSticker'],
            '{buttons}' => $n > 0 ? strtr($t['setButtons'], ['{n}' => $n]) : $t['setDefault'],
        ]);
    }
    // "send the amount in dollars (0.5 works too)" - the question for an amount
    // in $currency, with the tab and, for one user, what they have now
    function um_amount_ask($tpl, $lang, $currency, $balanceText, $textbotlang)
    {
        $t = $textbotlang['Admin']['UserMgmt'];
        $dec = (int) (currency_get($currency)['decimals'] ?? 0);
        return strtr($tpl, [
            '{lang}' => um_lang_name($lang, $textbotlang),
            '{currency}' => currency_get($currency)['title'] ?? $currency,
            '{balance}' => (string) $balanceText,
            '{decimals}' => $dec > 0 ? $t['decimalsHint'] : '',
        ]);
    }
    // an amount typed for $currency: its decimals allowed, above zero; null
    // when it is not one
    function um_amount_read($raw, $currency)
    {
        $n = money_normalize($raw);
        if ($n === null || !money_valid($n, $currency) || (float) $n <= 0) {
            return null;
        }
        return $n;
    }
}
if (!function_exists('stats_keyboard')) {
    // 📊 آمار ربات has a tab per language: every number on it is that
    // language's users and sales, money in that language's currency - one
    // total of tomans and dollars together would mean nothing. Each button
    // carries its tab (today_stat:en); the tabs keep the view that is open.
    function stats_keyboard($lang, $view, $textbotlang)
    {
        $k = $textbotlang['keyboard'];
        return json_encode(['inline_keyboard' => [
            panel_lang_tabs($lang, "{$view}:%s", null),
            [['text' => $k['totalStats'], 'callback_data' => "stat_all_bot:{$lang}"]],
            [['text' => $k['lastHourStats'], 'callback_data' => "hoursago_stat:{$lang}"]],
            [['text' => $k['today'], 'callback_data' => "today_stat:{$lang}"], ['text' => $k['yesterday'], 'callback_data' => "yesterday_stat:{$lang}"]],
            [['text' => $k['currentMonth'], 'callback_data' => "month_current_stat:{$lang}"], ['text' => $k['lastMonth'], 'callback_data' => "month_old_stat:{$lang}"]],
            [['text' => $k['statsAtDate'], 'callback_data' => "view_stat_time:{$lang}"]],
        ]]);
    }
    function stats_header($lang, $textbotlang)
    {
        return sprintf($textbotlang['Admin']['stats']['langHeader'], um_lang_name($lang, $textbotlang)) . "\n";
    }
    function stats_one($sql, array $params)
    {
        global $pdo;
        $st = $pdo->prepare($sql);
        $st->execute($params);
        return $st->fetch(PDO::FETCH_ASSOC) ?: [];
    }
    // a period (unix times, both ends included) for one language: the
    // $tplKey text (lastHour, today, yesterday, thisMonth, lastMonth,
    // selectedRange) filled in
    function stats_period_text($lang, $tplKey, $fromTs, $toTs, $textbotlang)
    {
        if (function_exists('wallet_ensure_schema')) {
            wallet_ensure_schema();
        }
        $test = $textbotlang['common']['labels']['testServiceName'];
        $cur = currency_for_lang($lang);
        [$iw, $ip] = stats_lang_where($lang, 'i');
        [$sw, $sp] = stats_lang_where($lang, 's', false);
        [$uw, $up] = user_lang_where($lang);
        // invoices and users keep unix times, service_other a 'Y/m/d H:i:s' text
        $ts = [(string) $fromTs, (string) $toTs];
        $dt = [date('Y/m/d H:i:s', $fromTs), date('Y/m/d H:i:s', $toTs)];
        $orders = stats_one("SELECT COUNT(*) c, COALESCE(SUM(i.price_product), 0) s FROM invoice i WHERE i.time_sell BETWEEN ? AND ? AND i.Status != 'Unpaid' AND i.name_product != ? AND {$iw}", array_merge($ts, [$test], $ip));
        $tests = stats_one("SELECT COUNT(*) c FROM invoice i WHERE i.time_sell BETWEEN ? AND ? AND i.name_product = ? AND {$iw}", array_merge($ts, [$test], $ip));
        $other = [];
        foreach (['extend_user', 'extra_user', 'extra_time_user', 'change_location'] as $type) {
            $paid = $type === 'extend_user' ? " AND s.status != 'unpaid'" : '';
            $other[$type] = stats_one("SELECT COUNT(*) c, COALESCE(SUM(s.price), 0) s FROM service_other s WHERE s.time BETWEEN ? AND ? AND s.type = ?{$paid} AND {$sw}", array_merge($dt, [$type], $sp));
        }
        $newUsers = stats_one("SELECT COUNT(*) c FROM user WHERE register BETWEEN ? AND ? AND register != 'none' AND {$uw}", array_merge($ts, $up));
        $args = [
            $orders['c'] ?? 0, money($orders['s'] ?? 0, $cur),
            $other['extend_user']['c'] ?? 0, money($other['extend_user']['s'] ?? 0, $cur),
            $other['extra_user']['c'] ?? 0, money($other['extra_user']['s'] ?? 0, $cur),
            $other['extra_time_user']['c'] ?? 0, money($other['extra_time_user']['s'] ?? 0, $cur),
            $other['change_location']['c'] ?? 0, money($other['change_location']['s'] ?? 0, $cur),
            $tests['c'] ?? 0, $newUsers['c'] ?? 0,
        ];
        if ($tplKey !== 'lastHour') {
            array_unshift($args, $dt[0], $dt[1]);
        }
        // ⏱ what the hourly services brought in over the same period
        return stats_header($lang, $textbotlang) . vsprintf($textbotlang['Admin']['stats'][$tplKey], $args) . payg_stats_line($lang, $fromTs, $toTs);
    }
    // [from, to] unix times of a named period
    function stats_period_range($view)
    {
        switch ($view) {
            case 'hoursago_stat':
                return [time() - 3600, time()];
            case 'yesterday_stat':
                return [strtotime('yesterday'), strtotime('today') - 1];
            case 'today_stat':
                return [strtotime('today'), time()];
            case 'month_old_stat':
                return [strtotime('first day of last month 00:00:00'), strtotime('first day of this month 00:00:00') - 1];
            default: // month_current_stat
                return [strtotime('first day of this month 00:00:00'), strtotime('first day of next month 00:00:00') - 1];
        }
    }
    function stats_overall_text($lang, $textbotlang)
    {
        global $pdo;
        if (function_exists('wallet_ensure_schema')) {
            wallet_ensure_schema();
        }
        $test = $textbotlang['common']['labels']['testServiceName'];
        $cur = currency_for_lang($lang);
        [$iw, $ip] = stats_lang_where($lang, 'i');
        [$sw, $sp] = stats_lang_where($lang, 's', false);
        [$pw, $pp] = stats_lang_where($lang, 'p');
        [$uw, $up] = user_lang_where($lang);
        $active = "i.Status IN ('active', 'end_of_time', 'end_of_volume', 'sendedwarn', 'send_on_hold')";
        $users = (int) (um_lang_counts()[$lang] ?? 0);
        // buyers are this tab's users, so the conversion rate stays a share of them
        [$bw, $bp] = stats_lang_where($lang, 'i', false);
        $buyers = (int) (stats_one("SELECT COUNT(DISTINCT i.id_user) c FROM invoice i WHERE i.Status != 'Unpaid' AND {$bw}", $bp)['c'] ?? 0);
        $tests = (int) (stats_one("SELECT COUNT(*) c FROM invoice i WHERE i.name_product = ? AND {$iw}", array_merge([$test], $ip))['c'] ?? 0);
        $all = stats_one("SELECT COUNT(*) c, COALESCE(SUM(i.price_product), 0) s FROM invoice i WHERE i.Status != 'Unpaid' AND i.name_product != ? AND {$iw}", array_merge([$test], $ip));
        $act = stats_one("SELECT COUNT(*) c, COALESCE(SUM(i.price_product), 0) s FROM invoice i WHERE {$active} AND i.name_product != ? AND {$iw}", array_merge([$test], $ip));
        $extendSum = (float) (stats_one("SELECT COALESCE(SUM(s.price), 0) s FROM service_other s WHERE s.type = 'extend_user' AND {$sw}", $sp)['s'] ?? 0);
        // a month at yesterday's pace
        $yesterday = (float) (stats_one("SELECT COALESCE(SUM(i.price_product), 0) s FROM invoice i WHERE i.time_sell BETWEEN ? AND ? AND {$active} AND i.name_product != ? AND {$iw}", array_merge([(string) strtotime('yesterday'), (string) (strtotime('today') - 1), $test], $ip))['s'] ?? 0);
        $activeSum = (float) ($act['s'] ?? 0);
        $agents = stats_one("SELECT SUM(agent != 'f') a, SUM(agent = 'n') n, SUM(agent = 'n2') n2 FROM user WHERE {$uw}", $up);
        $panels = (int) $pdo->query("SELECT COUNT(*) FROM marzban_panel")->fetchColumn();
        $gwNames = [
            'cart to cart' => $textbotlang['textbot']['cartToCart'],
            'aqayepardakht' => $textbotlang['textbot']['aqayePardakht'],
            'zarinpal' => $textbotlang['textbot']['zarinPal'],
            'plisio' => $textbotlang['textbot']['nowPayment'],
            'arze digital offline' => $textbotlang['textbot']['nowPaymentTron'],
            'Currency Rial 1' => $textbotlang['textbot']['iranPay2'],
            'Currency Rial 2' => $textbotlang['textbot']['iranPay3'],
            'Currency Rial 3' => $textbotlang['textbot']['iranPay1'],
            'paymentnotverify' => $textbotlang['textbot']['paymentNotVerify'],
            'Star Telegram' => $textbotlang['textbot']['starTelegram'],
            'USDT-BEP20' => $textbotlang['textbot']['usdtbepPayment'],
        ];
        $st = $pdo->prepare("SELECT p.Payment_Method m, COUNT(*) c, COALESCE(SUM(p.price), 0) s FROM Payment_report p WHERE p.payment_Status = 'paid' AND p.Payment_Method NOT IN ('add balance by admin', 'low balance by admin') AND {$pw} GROUP BY p.Payment_Method");
        $st->execute($pp);
        $gateways = '';
        foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $g) {
            $gateways .= sprintf($textbotlang['Admin']['report']['gatewayRow'], $gwNames[$g['m']] ?? $g['m'], $g['c'], money($g['s'], $cur));
        }
        $extendPct = $activeSum > 0 ? min(100, round($extendSum / $activeSum * 100, 2)) : 0;
        return stats_header($lang, $textbotlang) . sprintf(
            $textbotlang['Admin']['stats']['overall'],
            number_format($users),
            number_format($buyers),
            number_format($tests),
            money(um_lang_wallet_sum($lang), $cur),
            number_format((int) ($all['c'] ?? 0)),
            number_format((int) ($act['c'] ?? 0)),
            money($all['s'] ?? 0, $cur),
            money($activeSum, $cur),
            money($extendSum, $cur),
            $users > 0 ? round($buyers / $users * 100, 2) : 0,
            money($buyers > 0 ? $activeSum / $buyers : 0, $cur),
            money($yesterday * 30, $cur),
            $extendPct,
            number_format((int) ($agents['a'] ?? 0)),
            number_format((int) ($agents['n'] ?? 0)),
            number_format((int) ($agents['n2'] ?? 0)),
            number_format($panels),
            $gateways
        ) . payg_stats_line($lang);
    }
}
if (!function_exists('lang_scope_display')) {
    function lang_scope_display($lang, $textbotlang)
    {
        if ($lang === '' || $lang === null || $lang === 'all') {
            return $textbotlang['Admin']['LangScope']['allLangsBtn'];
        }
        // the column has always been allowed to hold a comma list ("fa,en") for
        // multi-language visibility (every read site uses FIND_IN_SET), but this
        // helper used to only label a single code and printed the raw string for
        // anything else - render each part with its own flag label instead
        $parts = array_filter(array_map('trim', explode(',', (string) $lang)), 'strlen');
        if (count($parts) <= 1) {
            return $textbotlang['bottext']['langs'][$lang] ?? $lang;
        }
        $labels = [];
        foreach ($parts as $code) {
            $labels[] = $textbotlang['bottext']['langs'][$code] ?? $code;
        }
        return implode(' ', $labels);
    }
}
if (!function_exists('langscope_kind_meta')) {
    // maps a langscope "kind" to its table/id-column/name-column, and the
    // right list caption key - the one place that knows about all three
    // entity types, so every other langscope_* function stays generic
    function langscope_kind_meta($kind)
    {
        if ($kind === 'panel') {
            return ['table' => 'marzban_panel', 'idField' => 'code_panel', 'nameField' => 'name_panel', 'captionKey' => 'panelsListCaption'];
        }
        if ($kind === 'product') {
            return ['table' => 'product', 'idField' => 'id', 'nameField' => 'name_product', 'captionKey' => 'productsListCaption'];
        }
        return ['table' => 'category', 'idField' => 'id', 'nameField' => 'remark', 'captionKey' => 'categoriesListCaption'];
    }
}
if (!function_exists('langscope_hub_payload')) {
    function langscope_hub_payload($textbotlang)
    {
        $kb = ['inline_keyboard' => [
            [['text' => $textbotlang['Admin']['LangScope']['panelsBtn'], 'callback_data' => 'langscope_list:panel']],
            [['text' => $textbotlang['Admin']['LangScope']['productsBtn'], 'callback_data' => 'langscope_list:product']],
            [['text' => $textbotlang['Admin']['LangScope']['categoriesBtn'], 'callback_data' => 'langscope_list:category']],
            [['text' => $textbotlang['Admin']['LangScope']['cascadeBtn'], 'callback_data' => 'langscope_casc_hub', 'style' => 'danger']],
            // opened from its own button under 🏬 تنظیمات فروشگاه - the "back"
            // that used to sit here led into 🎨 شخصی‌سازی نمایش دکمه‌ها instead
            [['text' => $textbotlang['bottext']['btn_close'], 'callback_data' => 'langscope_close', 'style' => 'danger']],
        ]];
        return json_encode($kb);
    }
}
if (!function_exists('langscope_list_payload')) {
    // one list per kind (panel/product/category): every row + its current
    // language, tap to open the picker for that one item
    // Telegram refuses a keyboard of more than 100 buttons, so a long catalogue
    // is shown a page at a time; $focusId opens on the page holding that item
    // (coming back from its picker)
    function langscope_list_payload($kind, $textbotlang, $page = 0, $focusId = null)
    {
        $meta = langscope_kind_meta($kind);
        $rows = select($meta['table'], "*", null, null, "fetchAll");
        $kb = ['inline_keyboard' => []];
        if (!is_array($rows) || empty($rows)) {
            $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['emptyList'], 'callback_data' => 'langscope_hub']];
        } else {
            $rows = array_values($rows);
            $per = 40;
            $pages = (int) ceil(count($rows) / $per);
            if ($focusId !== null) {
                foreach ($rows as $i => $row) {
                    if ((string) $row[$meta['idField']] === (string) $focusId) {
                        $page = intdiv($i, $per);
                        break;
                    }
                }
            }
            $page = max(0, min($pages - 1, (int) $page));
            foreach (array_slice($rows, $page * $per, $per) as $row) {
                $name = (string) $row[$meta['nameField']];
                // two products can share a name - their category tells them apart
                if ($kind === 'product' && trim((string) ($row['category'] ?? '')) !== '') {
                    $name .= ' · ' . $row['category'];
                }
                $label = $name . ' — ' . lang_scope_display($row['lang'] ?? 'all', $textbotlang);
                $kb['inline_keyboard'][] = [['text' => $label, 'callback_data' => "langscope_open:{$kind}:{$row[$meta['idField']]}"]];
            }
            if ($pages > 1) {
                // next on the left, previous on the right - the order the
                // user list's pages already use
                $nav = [];
                if ($page < $pages - 1) {
                    $nav[] = ['text' => $textbotlang['users']['page']['next'], 'callback_data' => "langscope_list:{$kind}:" . ($page + 1)];
                }
                $nav[] = ['text' => ($page + 1) . ' / ' . $pages, 'callback_data' => "langscope_list:{$kind}:{$page}"];
                if ($page > 0) {
                    $nav[] = ['text' => $textbotlang['users']['page']['previous'], 'callback_data' => "langscope_list:{$kind}:" . ($page - 1)];
                }
                $kb['inline_keyboard'][] = $nav;
            }
        }
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['backToHubBtn'], 'callback_data' => 'langscope_hub']];
        return json_encode($kb);
    }
}
if (!function_exists('langscope_picker_caption')) {
    // the picker's caption, naming the panel/product/category being set and
    // where it shows now - it used to ask "which languages?" about nothing
    function langscope_picker_caption($kind, $id, $textbotlang)
    {
        $t = $textbotlang['Admin']['LangScope'];
        $meta = langscope_kind_meta($kind);
        $row = select($meta['table'], "*", $meta['idField'], $id, "select");
        if (!is_array($row)) {
            return $t['pickerCaption'];
        }
        return strtr($t['pickerItem'], [
            '{kind}' => $t['kind_' . $kind] ?? '',
            '{name}' => htmlspecialchars((string) $row[$meta['nameField']]),
            '{current}' => lang_scope_display($row['lang'] ?? 'all', $textbotlang),
        ]) . "\n\n" . $t['pickerCaption'];
    }
}
if (!function_exists('lang_scope_picker_payload')) {
    // single-tap picker: 5 languages + "all languages", used identically for
    // panels, products and categories via the unified langscope_set:{kind}
    // callback - the underlying table/column differences are resolved once,
    // in langscope_kind_meta()
    // multi-select: one or many languages per panel/product/category. Each
    // language button carries the bitmask it would produce if tapped, so the
    // in-progress selection lives entirely in callback_data - no server-side
    // session state, exactly like the cascade picker below. $bitmask is null on
    // first open (derived from what is stored) and supplied on every re-render.
    function lang_scope_picker_payload($kind, $id, $currentLang, $textbotlang, $bitmask = null)
    {
        $langs = panel_langs();
        if ($bitmask === null) {
            $bitmask = langscope_casc_lang_to_bitmask($currentLang);
        }
        $kb = ['inline_keyboard' => []];
        $row = [];
        foreach ($langs as $i => $code) {
            $bits = $bitmask;
            $bits[$i] = ($bits[$i] === '1') ? '0' : '1';
            $mark = ($bitmask[$i] === '1') ? '✅ ' : '';
            $row[] = ['text' => $mark . $textbotlang['bottext']['langs'][$code], 'callback_data' => "langscope_tog:{$kind}:{$id}:{$bits}"];
            if (count($row) === 2) {
                $kb['inline_keyboard'][] = $row;
                $row = [];
            }
        }
        if (!empty($row)) {
            $kb['inline_keyboard'][] = $row;
        }
        $isAll = (strpos($bitmask, '1') === false);
        $kb['inline_keyboard'][] = [['text' => ($isAll ? '✅ ' : '') . $textbotlang['Admin']['LangScope']['allLangsBtn'], 'callback_data' => "langscope_set:{$kind}:{$id}:all"]];
        if (!$isAll) {
            $kb['inline_keyboard'][] = [['text' => '💾 ذخیره', 'callback_data' => "langscope_apply:{$kind}:{$id}:{$bitmask}", 'style' => 'success']];
        }
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['backToHubBtn'], 'callback_data' => "langscope_back:{$kind}:{$id}"]];
        return json_encode($kb);
    }
}
if (!function_exists('langscope_casc_lang_to_bitmask')) {
    // converts a stored lang value ('all', '', null, or a comma list like
    // "fa,en") into a 1/0 string, one character per panel_langs() entry, used
    // as the multi-select picker's transient state (carried in callback_data,
    // no server-side session needed). Width follows that list rather than a
    // fixed 5, so dropping or re-adding a language cannot leave the two halves
    // of this pair disagreeing about which bit means what.
    function langscope_casc_lang_to_bitmask($langValue)
    {
        $langs = panel_langs();
        if ($langValue === 'all' || $langValue === null || $langValue === '') {
            return str_repeat('0', count($langs));
        }
        $parts = array_map('trim', explode(',', $langValue));
        $bits = '';
        foreach ($langs as $code) {
            $bits .= in_array($code, $parts, true) ? '1' : '0';
        }
        return $bits;
    }
}
if (!function_exists('langscope_casc_bitmask_to_langs')) {
    function langscope_casc_bitmask_to_langs($bitmask)
    {
        $langs = panel_langs();
        $picked = [];
        foreach ($langs as $i => $code) {
            if (($bitmask[$i] ?? '0') === '1') {
                $picked[] = $code;
            }
        }
        return $picked;
    }
}
