if (!function_exists('gw_legacy_settings_datain')) {
    // Gateways that still have a dedicated global screen for integration
    // credentials (API keys / merchant IDs) - these stay global-only (one
    // processor account for the whole bot), so the bridge reuses the existing
    // datain string untouched instead of duplicating that logic per language.
    function gw_legacy_settings_datain($key)
    {
        $map = [
            // 'card' deliberately absent - replaced by the inline, per-language
            // "🔧 تنظیمات فنی درگاه" screen (cardlegacy:{lang}) built directly
            // into gateway_settings_payload(). $CartManage/cartsetting itself
            // stays fully intact (still reachable elsewhere, still the return
            // keyboard for ~15 unrelated flows) - only this one entry point
            // into it is retired in favor of the new screen.
            'plisio' => 'plisiosetting',
            'nowpayment' => 'nowpaymentsetting',
            'iranpay1' => 'iranpay1setting',
            'iranpay3' => 'iranpay3setting',
            'aqayepardakht' => 'aqayepardakhtsetting',
            'zarinpal' => 'zarinpalsetting',
            'digitaltron' => 'affilnecurrencysetting',
            'startelegrams' => 'startelegram',
        ];
        return $map[$key] ?? null;
    }
}
if (!function_exists('gateway_hub_payload')) {
    // Top screen of "💳 درگاه‌های پرداخت". Language tabs on top, then one clean
    // row per applicable gateway. Screen reads right-to-left, so array order is
    // reversed from the "obvious" left-to-right one: [تنظیمات] [✅/❌] [name] -
    // Telegram lays out inline buttons strictly by array order regardless of
    // text direction, so this is what actually puts the name on the visual
    // right and تنظیمات on the visual left.
    function gateway_hub_payload($lang, $textbotlang)
    {
        $t = $textbotlang['Admin']['GatewayLang'];
        $kb = ['inline_keyboard' => []];
        $tabs = [];
        foreach (panel_langs() as $l) {
            $tabs[] = [
                'text' => ($lang === $l ? '✅' : '') . ($textbotlang['bottext']['langs'][$l] ?? $l),
                'callback_data' => "gwlang:{$l}",
            ];
        }
        $kb['inline_keyboard'][] = $tabs;
        // column headers - order matches the row layout below: عملیات on the
        // visual left, وضعیت in the middle, عنوان on the visual right
        $kb['inline_keyboard'][] = [
            ['text' => $t['colAction'], 'callback_data' => "gwname:{$lang}:_col", 'style' => 'danger'],
            ['text' => $t['colStatus'], 'callback_data' => "gwname:{$lang}:_col", 'style' => 'danger'],
            ['text' => $t['colTitle'], 'callback_data' => "gwname:{$lang}:_col", 'style' => 'danger'],
        ];
        $shownGroups = [];
        foreach (array_keys(gateway_registry($textbotlang)) as $key) {
            if (!gateway_applicable_for_lang($key, $lang)) {
                continue;
            }
            // a grouped gateway is represented by its group's single row, drawn
            // once at the position of its first visible member
            $group = gateway_group_of($key);
            if ($group !== null) {
                if (isset($shownGroups[$group])) {
                    continue;
                }
                $shownGroups[$group] = true;
                $state = gateway_group_state($group, $lang);
                $mark = ['all' => '✅', 'some' => '🔘', 'none' => '❌'][$state];
                $kb['inline_keyboard'][] = [
                    ['text' => $t['openGroupBtn'], 'callback_data' => "gwgroup:{$lang}:{$group}"],
                    [
                        'text' => $mark,
                        'callback_data' => "gwgrouptoggle:{$lang}:{$group}",
                        'style' => $state === 'all' ? 'success' : ($state === 'some' ? 'primary' : 'danger'),
                    ],
                    // the family as this tab's customer sees it
                    gateway_tab_group_button($lang, $group, "gwgroup:{$lang}:{$group}"),
                ];
                continue;
            }
            $on = gateway_allowed_for_lang($key, $lang);
            // the checkmark reflects what a real user actually sees (allowed
            // for this language AND switched on globally), not just the
            // per-language flag alone - otherwise a gateway can show ✅ here
            // while still being invisible to everyone, with no visible clue
            // why (this is exactly what happened 2026-08-08: admin turns the
            // language switch on, sees ✅, assumes done, but the separate
            // global switch inside تنظیمات was still off)
            $effectivelyOn = $on && gateway_globally_on($key);
            $kb['inline_keyboard'][] = [
                ['text' => $textbotlang['keyboard']['settings'], 'callback_data' => "gwset:{$lang}:{$key}"],
                [
                    'text' => $effectivelyOn ? '✅' : '❌',
                    'callback_data' => "gwtoggle:{$lang}:{$key}",
                    'style' => $effectivelyOn ? 'success' : 'danger',
                ],
                // the name is a label, not a second way into تنظیمات - tapping
                // it explains what the row is instead of navigating. It is
                // the gateway exactly as this tab's customer sees it.
                gateway_tab_button($lang, $key, "gwname:{$lang}:{$key}"),
            ];
        }
        $kb['inline_keyboard'][] = [['text' => $t['disableAll'], 'callback_data' => "gwall:{$lang}:0", 'style' => 'danger']];
        $kb['inline_keyboard'][] = [['text' => $t['enableAll'], 'callback_data' => "gwall:{$lang}:1", 'style' => 'success']];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['bottext']['btn_close'], 'callback_data' => 'gwlang_close', 'style' => 'danger']];
        return json_encode($kb);
    }
}
if (!function_exists('gateway_group_state')) {
    // 'all' | 'some' | 'none' - how many of the group's gateways a real user
    // would actually see (per-language flag AND the global switch, the same
    // pair the per-gateway ✅ already reflects).
    function gateway_group_state($group, $lang)
    {
        $members = gateway_group_members($group, $lang);
        if (empty($members)) {
            return 'none';
        }
        $on = 0;
        foreach ($members as $key) {
            if (gateway_allowed_for_lang($key, $lang) && gateway_globally_on($key)) {
                $on++;
            }
        }
        return $on === 0 ? 'none' : ($on === count($members) ? 'all' : 'some');
    }
}
if (!function_exists('gateway_group_payload')) {
    // One group's own screen: the same [تنظیمات] [✅/❌] [name] rows the hub used
    // to show inline, plus a way back. Same column order and same callbacks, so
    // nothing about configuring a gateway changes - only where it lives.
    function gateway_group_payload($lang, $group, $textbotlang)
    {
        $t = $textbotlang['Admin']['GatewayLang'];
        $kb = ['inline_keyboard' => []];
        $kb['inline_keyboard'][] = [
            ['text' => $t['colAction'], 'callback_data' => "gwname:{$lang}:_col", 'style' => 'danger'],
            ['text' => $t['colStatus'], 'callback_data' => "gwname:{$lang}:_col", 'style' => 'danger'],
            ['text' => $t['colTitle'], 'callback_data' => "gwname:{$lang}:_col", 'style' => 'danger'],
        ];
        foreach (gateway_group_members($group, $lang) as $key) {
            $effectivelyOn = gateway_allowed_for_lang($key, $lang) && gateway_globally_on($key);
            $kb['inline_keyboard'][] = [
                ['text' => $textbotlang['keyboard']['settings'], 'callback_data' => "gwset:{$lang}:{$key}"],
                [
                    'text' => $effectivelyOn ? '✅' : '❌',
                    'callback_data' => "gwtoggle:{$lang}:{$key}",
                    'style' => $effectivelyOn ? 'success' : 'danger',
                ],
                gateway_tab_button($lang, $key, "gwname:{$lang}:{$key}"),
            ];
        }
        $kb['inline_keyboard'][] = [['text' => $t['backBtn'], 'callback_data' => "gwlang:{$lang}", 'style' => 'danger']];
        return json_encode($kb);
    }
}
if (!function_exists('gateway_group_caption')) {
    function gateway_group_caption($lang, $group, $textbotlang)
    {
        $t = $textbotlang['Admin']['GatewayLang'];
        $cap = strtr($t['groupCaption'], [
            '{group}' => gateway_tab_group_name($lang, $group),
            '{lang}' => $textbotlang['bottext']['langs'][$lang] ?? $lang,
        ]);
        // some families need a word of explanation (the offline ones settle
        // straight to the bot's wallet and need manual confirmation)
        $note = $t['groupNotes'][$group] ?? '';
        return trim($note) !== '' ? ($cap . "\n\n" . $note) : $cap;
    }
}
if (!function_exists('gateway_name_alert')) {
    // What a display-only name button says when tapped. Short on purpose:
    // answerCallbackQuery silently drops the whole call over 200 characters.
    function gateway_name_alert($lang, $key, $textbotlang)
    {
        $t = $textbotlang['Admin']['GatewayLang'];
        if ($key === '_col') {
            return $t['colAlert'];
        }
        $label = gateway_tab_name($lang, $key);
        $langOn = gateway_allowed_for_lang($key, $lang);
        $globalOn = gateway_globally_on($key);
        if ($langOn && $globalOn) {
            $state = $t['nameAlertOn'];
        } elseif (!$globalOn) {
            $state = $t['nameAlertGlobalOff'];
        } else {
            $state = $t['nameAlertLangOff'];
        }
        return strtr($t['nameAlert'], ['{name}' => $label, '{state}' => $state]);
    }
}
if (!function_exists('gateway_hub_caption')) {
    function gateway_hub_caption($lang, $textbotlang)
    {
        $t = $textbotlang['Admin']['GatewayLang'];
        $cap = strtr($t['hubCaption'], [
            '{lang}' => $textbotlang['bottext']['langs'][$lang] ?? $lang,
            '{currency}' => currency_get(currency_for_lang($lang))['title'] ?? currency_for_lang($lang),
        ]);
        $any = false;
        foreach (array_keys(gateway_registry($textbotlang)) as $key) {
            if (gateway_applicable_for_lang($key, $lang) && gateway_allowed_for_lang($key, $lang) && gateway_globally_on($key)) {
                $any = true;
                break;
            }
        }
        if (!$any) {
            $cap .= "\n\n" . $t['noneWarn'];
        }
        return $cap;
    }
}
if (!function_exists('topup_hub_payload')) {
    // "🏦 شارژ حساب": language tabs, then one row per applicable gateway with
    // its package count. Every applicable gateway is listed regardless of its
    // current on/off state, so packages can be prepared before a gateway goes
    // live - on/off itself is controlled from 💳 درگاه‌های پرداخت, not here.
    // members of a family that a customer of this language would actually see at
    // checkout - the same effective-status rule the hub itself uses
    function topup_hub_live_members($group, $lang)
    {
        $out = [];
        // the category list, not the layout families: this section groups
        // card-to-card and the single offline gateway too
        foreach (gateway_disc_groups()[$group] ?? [] as $k) {
            if (!gateway_applicable_for_lang($k, $lang)) {
                continue;
            }
            if (gateway_allowed_for_lang($k, $lang) && gateway_globally_on($k)) {
                $out[] = $k;
            }
        }
        return $out;
    }
    // "کارت به کارت: ۳ بسته" for every gateway of this family that has any,
    // as a quote under the screen. Buttons stay blue - what is configured is
    // reported here instead of colouring the row.
    function topup_hub_group_report($lang, $members, $textbotlang)
    {
        $lines = [];
        foreach ($members as $key) {
            $n = count(topup_packages_for($lang, $key));
            if ($n > 0) {
                $lines[] = '• ' . htmlspecialchars(gateway_tab_name($lang, $key)) . ": <b>{$n} بسته</b>";
            }
        }
        return empty($lines) ? '' : "\n\n<blockquote>📦 <b>بسته‌های تعریف‌شده</b>\n" . implode("\n", $lines) . '</blockquote>';
    }
    function topup_hub_group_payload($lang, $group, $textbotlang)
    {
        $members = topup_hub_live_members($group, $lang);
        $rows = [];
        foreach ($members as $key) {
            // always blue, like every other row in this section: green used to
            // mean "has packages", which the quote under the caption now says
            // by name and by count
            $rows[] = [gateway_tab_button($lang, $key, "topupset:{$lang}:{$key}")];
        }
        $rows[] = [['text' => $textbotlang['Admin']['TopupPkg']['backToPrevBtn'], 'callback_data' => "topuplang:{$lang}", 'style' => 'danger']];
        $cap = strtr($textbotlang['Admin']['TopupPkg']['hubGroupCaption'], [
            '{group}' => htmlspecialchars(gateway_tab_group_name($lang, $group)),
            '{lang}' => $textbotlang['bottext']['langs'][$lang] ?? $lang,
        ]);
        $cap .= topup_hub_group_report($lang, $members, $textbotlang);
        return [$cap, json_encode(['inline_keyboard' => $rows])];
    }
    function topup_hub_payload($lang, $textbotlang)
    {
        $t = $textbotlang['Admin']['TopupPkg'];
        $kb = ['inline_keyboard' => []];
        $tabs = [];
        foreach (panel_langs() as $l) {
            $tabs[] = [
                'text' => ($lang === $l ? '✅' : '') . ($textbotlang['bottext']['langs'][$l] ?? $l),
                'callback_data' => "topuplang:{$l}",
            ];
        }
        $kb['inline_keyboard'][] = $tabs;
        // Every live gateway sits inside its category - the same four this
        // section's discount hub uses, so card-to-card and the single offline
        // gateway are categories too rather than loose rows next to them.
        // A category is drawn once, at the position of its first live member.
        foreach (array_keys(gateway_disc_groups()) as $group) {
            $liveInGroup = [];
            foreach (gateway_disc_groups()[$group] as $key) {
                if (gateway_applicable_for_lang($key, $lang)
                    && gateway_allowed_for_lang($key, $lang) && gateway_globally_on($key)) {
                    $liveInGroup[] = $key;
                }
            }
            if (empty($liveInGroup)) {
                continue;
            }
            // no count, no green: this row opens a menu. What is configured
            // inside is reported as a quote under the caption.
            $kb['inline_keyboard'][] = [gateway_tab_group_button($lang, $group, "topupgrp:{$lang}:{$group}")];
        }
        // 🎨 ظاهر نمایش درگاه ها moved to 🎨 شخصی‌سازی پیام‌های ربات →
        // 💰 پیام‌های افزایش موجودی, alongside the other top-up appearance and
        // message settings - this hub keeps only the packages and the discount
        $kb['inline_keyboard'][] = [['text' => '🎁 تخفیف شارژ', 'callback_data' => "dslang:{$lang}", 'style' => 'primary']];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['bottext']['btn_close'], 'callback_data' => 'topup_close', 'style' => 'danger']];
        return json_encode($kb);
    }
}
if (!function_exists('topup_hub_caption')) {
    function topup_hub_caption($lang, $textbotlang)
    {
        $t = $textbotlang['Admin']['TopupPkg'];
        $cap = strtr($t['hubCaption'], [
            '{lang}' => $textbotlang['bottext']['langs'][$lang] ?? $lang,
            '{currency}' => currency_get(currency_for_lang($lang))['title'] ?? currency_for_lang($lang),
        ]);
        // no row on this screen turns green any more, so what has actually been
        // defined is reported here - by category, with the gateway names
        $tp_rep = [];
        foreach (array_keys(gateway_disc_groups()) as $tp_g) {
            $tp_members = topup_hub_live_members($tp_g, $lang);
            $tp_bits = [];
            foreach ($tp_members as $tp_k) {
                $tp_n = count(topup_packages_for($lang, $tp_k));
                if ($tp_n === 0) {
                    continue;
                }
                // a category with one gateway would otherwise print its name
                // twice - "کارت به کارت: کارت به کارت (3)"
                $tp_bits[] = count($tp_members) === 1
                    ? "<b>{$tp_n} بسته</b>"
                    : htmlspecialchars(gateway_tab_name($lang, $tp_k)) . " ({$tp_n})";
            }
            if (!empty($tp_bits)) {
                $tp_rep[] = '• ' . htmlspecialchars(gateway_tab_group_name($lang, $tp_g)) . ': ' . implode('، ', $tp_bits);
            }
        }
        if (!empty($tp_rep)) {
            $cap .= "\n\n<blockquote>📦 <b>بسته‌های تعریف‌شده</b>\n" . implode("\n", $tp_rep) . '</blockquote>';
        }
        return $cap;
    }
}
if (!function_exists('topup_packages_payload')) {
    // no fixed cap - every real package, columns-per-row chunked, plus
    // exactly one trailing "+" to add the next one
    function topup_packages_payload($lang, $key, $textbotlang)
    {
        $t = $textbotlang['Admin']['TopupPkg'];
        $packages = topup_packages_for($lang, $key, true);
        $slots = [];
        foreach ($packages as $i => $p) {
            $slots[] = topup_package_button($p, $lang, "topuppick:{$lang}:{$key}:{$i}");
        }
        $slots[] = ['text' => '➕', 'callback_data' => "topupadd:{$lang}:{$key}"];
        $kb = ['inline_keyboard' => array_chunk($slots, topup_columns_for($lang, $key))];
        $tp_customStyle = topup_btnstyle_for($lang, $key, 'custom', true);
        $tp_backStyle = topup_btnstyle_for($lang, $key, 'back', true);
        // مبلغ دلخواه opens its amount limits; بازگشت به روش پرداخت is a preview
        // only - its colour/name/position are set in 🎨 → 💳 درگاه‌ها, and tapping
        // it here says so rather than opening a second, competing editor
        $kb['inline_keyboard'][] = [
            topup_styled_button(lang_tab_texts($lang)['users']['Balance']['customAmountBtn'], $tp_customStyle, "topupminmax:{$lang}:{$key}", 'primary'),
            topup_styled_button(lang_tab_texts($lang)['users']['Balance']['backToMethodBtn'], $tp_backStyle, "tpbackinfo:{$lang}:{$key}", 'danger'),
        ];
        // This screen's OWN caption is edited here - it is the text shown on
        // this very step, so it belongs next to the packages it describes.
        $kb['inline_keyboard'][] = [
            ['text' => $t['defaultCaptionBtn'], 'callback_data' => "topupcapdefault:{$lang}:{$key}"],
            ['text' => $t['editCaptionBtn'], 'callback_data' => "topupcap:{$lang}:{$key}"],
        ];
        // Every gateway's message rows - custom-amount caption, invoice caption,
        // invoice button styling, expired-invoice caption, the link message -
        // live in 🎨 شخصی‌سازی پیام‌های ربات → 💰 پیام‌های افزایش موجودی → 💳
        // کپشن و دکمه‌های درگاه‌ها, one screen per gateway. This screen keeps only
        // what belongs to the packages themselves: the amounts, the custom-amount
        // limits, this step's own caption and the package appearance. A gateway
        // added later therefore gets the same shape with no work here.

        $kb['inline_keyboard'][] = [['text' => $t['displayBtn'], 'callback_data' => "topupdisp:{$lang}:{$key}"]];
        // the admin's own way out - the "🔙 بازگشت به روش پرداخت" row above is a
        // preview of the CUSTOMER's button (it opens that button's styling), so
        // this screen had no actual back button of its own
        // back to the category this gateway was opened through - every gateway
        // now has one, so this is always one step back rather than a jump out
        $tpHubGroup = gateway_disc_group_of($key);
        $tpHubBack = $tpHubGroup !== null ? "topupgrp:{$lang}:{$tpHubGroup}" : "topuplang:{$lang}";
        $kb['inline_keyboard'][] = [['text' => '🔙 بازگشت به منوی قبلی', 'callback_data' => $tpHubBack, 'style' => 'danger']];
        return json_encode($kb);
    }
}
if (!function_exists('topup_packages_caption')) {
    function topup_packages_caption($lang, $key, $textbotlang)
    {
        // exactly what a real user of this language/gateway would see - the
        // admin edits it right here (topupcap:) with an immediate live preview
        return topup_caption_for($lang, $key, lang_tab_texts($lang)['users']['Balance']['pkgPromptTitle']);
    }
    // topup_packages_caption_with_preview() alone stays a pure passthrough of the package
    // caption (existing override/reset round-trip tests depend on that exact
    // contract) - every real screen-render call site uses THIS wrapper
    // instead, which adds quoted previews of the invoice/expired-invoice
    // captions too (card/plisio only - other gateways have neither concept)
    function topup_packages_caption_preview_quote($text)
    {
        // Telegram's HTML parser support for a <blockquote> nested inside
        // another <blockquote> is unverified/risky - some caption defaults
        // (e.g. plisio's cryptoInstruction) already contain their own, so
        // strip any inner ones before wrapping to guarantee this never nests
        return '<blockquote>' . str_replace(['<blockquote>', '</blockquote>'], '', $text) . '</blockquote>';
    }
    function topup_packages_caption_with_preview($lang, $key, $textbotlang)
    {
        $t = $textbotlang['Admin']['TopupPkg'];
        $out = $t['captionPreviewPackagesLabel'] . "\n" . topup_packages_caption_preview_quote(topup_packages_caption($lang, $key, $textbotlang));
        // card's invoice/expired previews are NOT shown here any more - their
        // edit buttons moved to 🎨 → 💰 پیام‌های افزایش موجودی, and a preview
        // with no way to act on it just made this screen longer. See
        // topup_card_caption_previews(), which renders them next to the buttons.
        if ($key === 'plisio') {
            $out .= "\n\n" . $t['captionPreviewInvoiceLabel'] . "\n" . topup_packages_caption_preview_quote(plisio_invoice_caption_for($lang, lang_tab_texts($lang)['users']['Balance']['cryptoInstruction']));
            $out .= "\n\n" . $t['captionPreviewExpiredLabel'] . "\n" . topup_packages_caption_preview_quote(plisio_invoice_expired_caption_for($lang, lang_tab_texts($lang)['users']['Balance']['plisioInvoiceExpiredCaption']));
        }
        return $out;
    }
}
if (!function_exists('topup_card_caption_previews')) {
    // Live previews of the four card-to-card captions, quoted, for the
