}
if (!function_exists('product_pick_payload')) {
    // ✏️ ویرایش محصول / ❌ حذف محصول: a panel's products one language tab at
    // a time - exactly the ones that tab's customers are shown - so it is
    // plain which product is on in which language. $panelRow null means the
    // «همه پنل ها» products. 'edit' lists one user type ($agent); 'delete'
    // lists every type and names the agent ones.
    function product_pick_payload($mode, $lang, $panelRow, $agent, $textbotlang, $note = '')
    {
        global $pdo;
        $t = $textbotlang['Admin']['Product'];
        $langName = $textbotlang['bottext']['langs'][$lang] ?? $lang;
        $sql = "SELECT * FROM product WHERE (Location = ? OR Location = '/all') AND (FIND_IN_SET(?, lang) OR lang = 'all' OR lang IS NULL OR lang = '')";
        $args = [is_array($panelRow) ? (string) $panelRow['name_panel'] : '/all', $lang];
        if ($mode === 'edit') {
            $sql .= " AND agent = ?";
            $args[] = (string) $agent;
        }
        $stmt = $pdo->prepare($sql . " ORDER BY id");
        $stmt->execute($args);
        $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
        $pid = is_array($panelRow) ? (int) $panelRow['id'] : 0;
        $kb = ['inline_keyboard' => [panel_lang_tabs($lang, $mode === 'edit' ? 'pedit|%s' : "pdel|l|%s|{$pid}")]];
        $agentNames = ['n' => $textbotlang['keyboard']['normalAgent'], 'n2' => $textbotlang['keyboard']['advancedAgent']];
        foreach ($rows as $row) {
            $label = (string) $row['name_product'];
            if (in_array(trim((string) ($row['lang'] ?? '')), ['', 'all'], true)) {
                $label .= ' 🌍';
            }
            if ($mode === 'delete' && isset($agentNames[$row['agent']])) {
                $label .= ' · ' . $agentNames[$row['agent']];
            }
            $kb['inline_keyboard'][] = [['text' => $label, 'callback_data' => $mode === 'edit' ? "productedit_{$row['id']}" : "pdel|a|{$lang}|{$pid}|{$row['id']}"]];
        }
        if ($mode === 'edit') {
            // 📐 the same tool as 🎨 ← ظاهر دکمه‌های محصول ← 📐 چیدمان, for this tab; back comes here
            $kb['inline_keyboard'][] = [['text' => $t['layoutBtn'], 'callback_data' => "help_lay:product:{$lang}:pe"]];
            $code = is_array($panelRow) ? (string) $panelRow['code_panel'] : 'all';
            $kb['inline_keyboard'][] = [['text' => $textbotlang['keyboard']['backToPrevMenu2'], 'callback_data' => "locationedit_{$code}"]];
        } else {
            $kb['inline_keyboard'][] = [['text' => $textbotlang['keyboard']['backToPreviousMenu'], 'callback_data' => 'pdel|p']];
        }
        $caption = ($mode === 'edit' ? $t['selectEditProduct'] : $t['selectRemoveProduct']) . "\n\n" . strtr($t['pickTabNote'], [
            '{panel}' => htmlspecialchars(is_array($panelRow) ? (string) $panelRow['name_panel'] : $textbotlang['keyboard']['allPanels']),
            '{lang}' => $langName,
        ]);
        if (is_array($panelRow) && !in_array($lang, app_row_langs($panelRow), true)) {
            $caption .= "\n\n" . strtr($t['pickPanelHidden'], ['{lang}' => $langName]);
        }
        if (empty($rows)) {
            $caption .= "\n\n" . $t['pickEmpty'];
        }
        return [$note . $caption, json_encode($kb)];
    }
    // ❌ حذف محصول's first step: which panel
    function product_delete_panels_payload($textbotlang)
    {
        $kb = ['inline_keyboard' => []];
        foreach (select("marzban_panel", "*", null, null, "fetchAll") ?: [] as $p) {
            $kb['inline_keyboard'][] = [['text' => (string) $p['name_panel'], 'callback_data' => "pdel|l|fa|{$p['id']}"]];
        }
        $kb['inline_keyboard'][] = [['text' => $textbotlang['keyboard']['allPanels'], 'callback_data' => 'pdel|l|fa|0']];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['keyboard']['backToPreviousMenu'], 'callback_data' => 'backproductadmin']];
        return json_encode($kb);
    }
}
if (!function_exists('product_currency_of')) {
    function product_currency_of($productId)
    {
        global $pdo;
        $q = $pdo->prepare("SELECT currency FROM product WHERE id = ? LIMIT 1");
        $q->execute([$productId]);
        $c = $q->fetchColumn();
        return ($c !== false && $c !== null && $c !== '') ? $c : currency_default_code();
    }
}
if (!function_exists('product_info_caption')) {
    // re-fetches + formats one product's info summary - reusable after every
    // field edit so the admin lands back on the SAME product's panel instead
    // of a generic menu, and can keep editing without re-navigating
    function product_info_caption($id_product, $agent, $locationName, $textbotlang)
    {
        global $pdo;
        $q = $pdo->prepare("SELECT * FROM product WHERE id = ? AND agent = ? AND (Location = ? OR Location = '/all') LIMIT 1");
        $q->bindValue(1, $id_product, PDO::PARAM_STR);
        $q->bindValue(2, $agent, PDO::PARAM_STR);
        $q->bindValue(3, $locationName, PDO::PARAM_STR);
        $q->execute();
        $info_product = $q->fetch(PDO::FETCH_ASSOC);
        if (!$info_product) {
            return null;
        }
        $count_invoice = select("invoice", "*", "name_product", $info_product['name_product'], "count");
        return sprintf($textbotlang['Admin']['Product']['editSummary'], $info_product['name_product'], money($info_product['price_product'], $info_product['currency'] ?? null), $info_product['Volume_constraint'], $info_product['Location'], $info_product['Service_time'], $info_product['agent'], $info_product['data_limit_reset'], $info_product['note'], $info_product['category'], $count_invoice)
            . product_speed_caption_line($info_product, $textbotlang);
    }
    // 🎁 اکانت تست of one panel: what it is set to, bold in a quote, a glass
    // button for each - 🚀 its speed only on Rebecca, nothing else holds one -
    // and a red ❌ بستن
    function panel_test_menu_payload($panel, $textbotlang)
    {
        $t = $textbotlang['Admin']['TestMenu'];
        $k = $textbotlang['keyboard'];
        $panel = is_array($panel) ? $panel : [];
        $del = (int) ($panel['del_usertest'] ?? 0);
        $rows = [
            strtr($t['rowTime'], ['{v}' => (int) ($panel['time_usertest'] ?? 1)]),
            strtr($t['rowVolume'], ['{v}' => (int) ($panel['val_usertest'] ?? 100)]),
            strtr($t['rowDelete'], ['{v}' => $del > 0 ? strtr($t['deleteHours'], ['{n}' => $del]) : $t['deleteOff']]),
        ];
        $kb = [
            [['text' => $k['testServiceTime'], 'callback_data' => 'ptest_time'], ['text' => $k['testAccountVolume'], 'callback_data' => 'ptest_vol']],
            [['text' => $k['testDeleteTime'], 'callback_data' => 'ptest_del']],
        ];
        if (($panel['type'] ?? '') === 'rebecca') {
            $rows[] = strtr($t['rowSpeed'], ['{v}' => speed_limit_label($panel['speed_usertest'] ?? 0, $t['speedNone'])]);
            $kb[] = [['text' => $t['speedBtn'], 'callback_data' => 'ptest_speed']];
        }
        $kb[] = [['text' => $t['closeBtn'], 'callback_data' => 'ptest_x', 'style' => 'danger']];
        return [strtr($t['caption'], ['{panel}' => htmlspecialchars((string) ($panel['name_panel'] ?? '')), '{rows}' => implode("\n", $rows)]), json_encode(['inline_keyboard' => $kb])];
    }
    // 🚀 a product's speed under its summary - where its panel can hold one
    function product_speed_caption_line($row, $textbotlang)
    {
        if (!is_array($row) || !speed_limit_applies($row['Location'] ?? '')) {
            return '';
        }
        return "\n" . sprintf($textbotlang['Admin']['Product']['speedLine'], speed_limit_label($row['speed_limit'] ?? 0, $textbotlang['Admin']['Product']['speedNone']));
    }
}
if (!function_exists('help_layout_back_cb')) {
    // where the layout/color/emoji/rename tool screens' "back" button goes:
    // the tutorial system's own sub-hubs for its two kinds, or the new
    // button-styling per-kind sub-hub for everything else (panel/product/category)
    function help_layout_back_cb($kind, $lang)
    {
        // :bt - since 📚 مدیریت آموزش‌ها stopped carrying its own copy of the
        // display hub, 🎨 شخصی‌سازی ← 📚 پیام و دکمه‌های آموزش is the only way
        // into these two screens, so this is where their chain has to end up.
        // Without it, backing out of the colour/layout/emoji tools dropped the
        // admin into 📚 مدیریت آموزش‌ها, a menu they never came through.
        if ($kind === 'categories') {
            return "help_disp_cat:{$lang}:bt";
        }
        if ($kind === 'tutorials') {
            return "help_disp_tut:{$lang}:bt";
        }
        return "btnstyle_kindhub:{$kind}:{$lang}";
    }
}
