if (!function_exists('feature_section_effective')) {
    // The four ⚙️ تنظیمات sub-screens of 🌐 وضعیت قابلیت‌ها (هر زبان). Each
    // value is read through feature_setting_value(), so a language nobody has
    // touched still shows (and the bot still uses) the original global value.
    // Keys are stable strings - they are what the per-language store is keyed
    // by and what the value prompts carry in their callback_data.
    function feature_section_effective($lang)
    {
        $setting = select("setting", "*", null, null, "select");
        $aff = select("affiliates", "*", null, null, "select");
        $limit = json_decode((string) $setting['limitnumber'], true);
        if (!is_array($limit)) {
            $limit = [];
        }
        return [
            'aff_percent' => feature_setting_value('aff_percent', $lang, (string) $setting['affiliatespercentage']),
            'aff_giftamount' => feature_setting_value('aff_giftamount', $lang, (string) $aff['price_Discount']),
            'aff_commission' => feature_setting_value('aff_commission', $lang, (string) $aff['status_commission']),
            'aff_startgift' => feature_setting_value('aff_startgift', $lang, (string) $aff['Discount']),
            'aff_firstbuy' => feature_setting_value('aff_firstbuy', $lang, (string) $aff['porsant_one_buy']),
            'aff_classic' => aff_classic_on($lang) ? '1' : '0',
            'aff_banner_text' => feature_aff_banner($lang, $aff)[0],
            'aff_banner_media' => feature_aff_banner($lang, $aff)[1],
            'wheel_price' => feature_setting_value('wheel_price', $lang, (string) $setting['wheelـluck_price']),
            'loc_limit_all' => feature_setting_value('loc_limit_all', $lang, (string) ($limit['all'] ?? 0)),
            'loc_limit_free' => feature_setting_value('loc_limit_free', $lang, (string) ($limit['free'] ?? 0)),
            'phone_prefix' => implode(',', phone_prefixes_for_lang($lang)),
        ];
    }
}
if (!function_exists('feature_section_of_key')) {
    // which of the four sections a value key belongs to - the value prompts
    // only carry the key, and the screen to return to has to be derivable
    // from it. null means "not a key this screen owns", i.e. ignore.
    function feature_section_of_key($key)
    {
        $map = [
            'aff_percent' => 'affc',
            'aff_giftamount' => 'affc',
            'aff_banner' => 'affc',
            'wheel_price' => 'wheel',
            'loc_limit_all' => 'loc',
            'loc_limit_free' => 'loc',
            'app_name' => 'linkapp',
            'app_link' => 'linkapp',
            'phone_prefix' => 'phone',
            'lottery_1' => 'lottery',
            'lottery_2' => 'lottery',
            'lottery_3' => 'lottery',
            'affrw_need' => 'affr',
            'affrw_gb' => 'affr',
            'affrw_days' => 'affr',
            'affrw_speed' => 'affr',
            'affrw_max' => 'affr',
            'affrw_reset' => 'affr',
        ];
        return $map[$key] ?? null;
    }
}
if (!function_exists('feature_phone_prefix_label')) {
    // "+98" / "+7 / +375" / "any country" - an unset language really does
    // accept every country, so it needs wording rather than an empty gap
    function feature_phone_prefix_label($lang, $sectionTexts)
    {
        $p = phone_prefixes_for_lang($lang);
        if (!$p) {
            return $sectionTexts['phoneAny'] ?? 'any';
        }
        $flags = phone_country_choices();
        return implode(' / ', array_map(function ($x) use ($flags) {
            return (isset($flags[$x]) ? $flags[$x][0] . ' ' : '') . '+' . $x;
        }, $p));
    }
}
if (!function_exists('feature_section_caption')) {
    function feature_section_caption($textbotlang, $lang, $section)
    {
        // Persian wording, $lang data - same split as the screen above it
        $tx = lang_tab_texts('fa');
        $v = feature_section_effective($lang);
        $langName = $tx['bottext']['langs'][$lang] ?? $lang;
        $s = $tx['Admin']['FeatureSection'];
        // amounts belong to this language's currency (setting.lang_currency),
        // so they are rendered with its symbol/decimals rather than as a bare
        // number the admin would read as toman
        $cur = currency_for_lang($lang);
        if ($section === 'linkapp') {
            $rows = app_rows_for_lang($lang);
            $list = '';
            foreach ($rows as $r) {
                // a row with no language of its own is shown to every language,
                // so say so - editing or deleting it here hits all of them
                $shared = ($r['lang'] === null || $r['lang'] === '' || $r['lang'] === 'all');
                $list .= "\n• " . ($shared ? '🌍 ' : '') . htmlspecialchars($r['name'], ENT_QUOTES, 'UTF-8');
            }
            if ($list === '') {
                $list = "\n" . $s['appNone'];
            }
            return strtr($s['appTitle'], ['{lang}' => $langName, '{list}' => $list]);
        }
        if ($section === 'lottery') {
            $lp = lottery_prizes_for_lang($lang);
            $la = (string) feature_value('Lotteryagent', $lang, (string) (select("setting", "*", null, null, "select")['Lotteryagent'] ?? '0')) === '1';
            return strtr($s['lotteryTitle'], [
                '{lang}' => $langName,
                '{p1}' => money($lp[0], $cur),
                '{p2}' => money($lp[1], $cur),
                '{p3}' => money($lp[2], $cur),
                '{agents}' => $la ? $tx['Admin']['Status']['statuson'] : $tx['Admin']['Status']['statusoff'],
            ]);
        }
        if ($section === 'phone') {
            $phAud = (string) feature_setting_value('phone_audience', $lang, 'all');
            return strtr($s['phoneTitle'], [
                '{lang}' => $langName,
                '{prefixes}' => feature_phone_prefix_label($lang, $s),
            ]) . strtr($s['phoneAudLine'], ['{aud}' => $s['phoneAud_' . $phAud] ?? $s['phoneAud_all']]);
        }
        if ($section === 'wheel') {
            return strtr($s['wheelTitle'], ['{lang}' => $langName, '{price}' => money($v['wheel_price'], $cur)]);
        }
        if (in_array($section, ['aff', 'affc', 'affr', 'refvc', 'refvr'], true)) {
            return aff_section_caption($lang, $section);
        }
        return strtr($s['locTitle'], [
            '{lang}' => $langName,
            '{all}' => (string) $v['loc_limit_all'],
            '{free}' => (string) $v['loc_limit_free'],
        ]);
    }
}
if (!function_exists('feature_section_payload')) {
    function feature_section_payload($textbotlang, $lang, $section)
    {
        // Persian wording, $lang data - same split as the screen above it
        $tx = lang_tab_texts('fa');
        $s = $tx['Admin']['FeatureSection'];
        $v = feature_section_effective($lang);
        $on = $tx['Admin']['Status']['statuson'];
        $off = $tx['Admin']['Status']['statusoff'];
        $cur = currency_for_lang($lang);
        $rows = [];
        if ($section === 'linkapp') {
            foreach (app_rows_for_lang($lang) as $r) {
                $shared = ($r['lang'] === null || $r['lang'] === '' || $r['lang'] === 'all');
                $rows[] = [
                    ['text' => '✏️ ' . ($shared ? '🌍 ' : '') . $r['name'], 'callback_data' => "flsappe:{$lang}:{$r['id']}"],
                    ['text' => '🗑', 'callback_data' => "flsappd:{$lang}:{$r['id']}", 'style' => 'danger'],
                ];
            }
            $rows[] = [['text' => $s['appAdd'], 'callback_data' => "flsask:{$lang}:app_name", 'style' => 'success']];
        } elseif ($section === 'lottery') {
            $lp = lottery_prizes_for_lang($lang);
            foreach ([1 => '🥇', 2 => '🥈', 3 => '🥉'] as $lr => $lm) {
                $rows[] = [['text' => strtr($s['lotteryPrizeBtn'], ['{medal}' => $lm, '{rank}' => (string) $lr, '{prize}' => money($lp[$lr - 1], $cur)]), 'callback_data' => "flsask:{$lang}:lottery_{$lr}"]];
            }
            $la = (string) feature_value('Lotteryagent', $lang, (string) (select("setting", "*", null, null, "select")['Lotteryagent'] ?? '0'));
            $rows[] = [
                ['text' => $la === '1' ? $on : $off, 'callback_data' => "flstog:{$lang}:lottery_agent:" . ($la === '1' ? '1' : '0'), 'style' => $la === '1' ? 'success' : 'danger'],
                ['text' => $s['lotteryAgentsBtn'], 'callback_data' => "none"],
            ];
        } elseif ($section === 'phone') {
            // who is asked for a number: everyone / newcomers / invited
            $phAud = (string) feature_setting_value('phone_audience', $lang, 'all');
            $rows[] = [['text' => strtr($s['phoneAudBtn'], ['{aud}' => $s['phoneAud_' . $phAud] ?? $s['phoneAud_all']]), 'callback_data' => "flsph:{$lang}:aud", 'style' => 'primary']];
            $ph_cur = phone_prefixes_for_lang($lang);
            $ph_all = empty($ph_cur);
            $rows[] = [['text' => ($ph_all ? '✅ ' : '❌ ') . $s['phoneAllBtn'], 'callback_data' => "flsph:{$lang}:all", 'style' => $ph_all ? 'success' : 'primary']];
            $ph_choices = phone_country_choices();
            $ph_cells = [];
            foreach ($ph_choices as $ph_code => $ph_c) {
                $ph_on = in_array((string) $ph_code, $ph_cur, true);
                $ph_cells[] = ['text' => ($ph_on ? '✅ ' : '') . $ph_c[0] . ' +' . $ph_code, 'callback_data' => "flsph:{$lang}:t:{$ph_code}", 'style' => $ph_on ? 'success' : 'primary'];
            }
            foreach (array_chunk($ph_cells, 3) as $ph_row) {
                $rows[] = $ph_row;
            }
            // a code typed in that is not one of the buttons: tap to take it off
            foreach (array_diff($ph_cur, array_map('strval', array_keys($ph_choices))) as $ph_code) {
                $rows[] = [['text' => '✅ +' . $ph_code, 'callback_data' => "flsph:{$lang}:t:{$ph_code}", 'style' => 'success']];
            }
            $rows[] = [['text' => $s['phoneAddBtn'], 'callback_data' => "flsask:{$lang}:phone_prefix"]];
            $ph_def = array_values(array_filter(explode(',', (string) (phone_prefix_defaults()[$lang] ?? '')), 'strlen'));
            $rows[] = [['text' => strtr($s['phoneDefaultBtn'], ['{def}' => $ph_def ? implode(' / ', array_map(fn($c) => '+' . $c, $ph_def)) : $s['phoneAny']]), 'callback_data' => "flsph:{$lang}:def"]];
        } elseif ($section === 'wheel') {
            $rows[] = [['text' => strtr($s['wheelPriceBtn'], ['{price}' => money($v['wheel_price'], $cur)]), 'callback_data' => "flsask:{$lang}:wheel_price"]];
        } elseif (in_array($section, ['aff', 'affc', 'affr', 'refvc', 'refvr'], true)) {
            // 👥 طرح‌های زیرمجموعه‌گیری and its pages carry their own back button
            return json_encode(['inline_keyboard' => aff_section_rows($lang, $section)]);
        } else {
            $rows[] = [['text' => strtr($s['locAllBtn'], ['{all}' => (string) $v['loc_limit_all']]), 'callback_data' => "flsask:{$lang}:loc_limit_all"]];
            $rows[] = [['text' => strtr($s['locFreeBtn'], ['{free}' => (string) $v['loc_limit_free']]), 'callback_data' => "flsask:{$lang}:loc_limit_free"]];
            $rows[] = [['text' => $s['locResetBtn'], 'callback_data' => "flsloc:{$lang}:ask", 'style' => 'danger']];
        }
        $rows[] = [['text' => $s['back'], 'callback_data' => "fls_lang:{$lang}"]];
        return json_encode(['inline_keyboard' => $rows]);
    }
}
if (!function_exists('svcgive_panels_payload')) {
    // 🔗 واگذاری سرویس پنل به کاربر: a service made straight on a panel and
    // handed to a customer outside the bot becomes theirs in the bot - listed
    // under 🛍 سرویس های من, renewable, watched by the cron jobs like any other.
    // Step 1: its panel (not the manual-sale ones - they have no accounts).
    function svcgive_panels_payload($textbotlang)
    {
        $t = $textbotlang['Admin']['UserMgmt'];
        $rows = [];
        foreach (select("marzban_panel", "*", null, null, "fetchAll") ?: [] as $p) {
            if (($p['type'] ?? '') === 'Manualsale') {
                continue;
            }
            $rows[] = [['text' => '🖥 ' . $p['name_panel'], 'callback_data' => "svcgive|p|{$p['id']}", 'style' => 'primary']];
        }
        if (empty($rows)) {
            $rows[] = [['text' => $t['assignNoPanel'], 'callback_data' => 'none']];
        }
        $rows[] = [['text' => $t['assignBackBtn'], 'callback_data' => 'backlistuser', 'style' => 'danger']];
        return json_encode(['inline_keyboard' => $rows]);
    }
    // the account on its panel, or null when the panel does not have it
    function svcgive_account($panelRow, $username)
    {
        global $ManagePanel;
        $d = $ManagePanel->DataUser($panelRow['name_panel'], $username);
        return (is_array($d) && ($d['status'] ?? '') !== 'Unsuccessful' && !empty($d['username'])) ? $d : null;
    }
    // who already has it in the bot (a listed service) - an account can be
    // shared, so this is a list
    function svcgive_owners($panelName, $username)
    {
        global $pdo;
        $st = $pdo->prepare("SELECT DISTINCT id_user FROM invoice WHERE username = ? AND Service_location = ? AND Status IN ('active', 'end_of_time', 'end_of_volume', 'sendedwarn', 'send_on_hold')");
        $st->execute([(string) $username, (string) $panelName]);
        return array_map('strval', $st->fetchAll(PDO::FETCH_COLUMN));
    }
    // a bot user by numeric id or @username, or null
    function svcgive_find_user($text)
    {
        $text = trim((string) $text);
        if (ctype_digit($text)) {
            $u = select("user", "*", "id", $text, "select");
        } elseif (preg_match('/^@?(\w{3,32})$/', $text, $m)) {
            $u = select("user", "*", "username", $m[1], "select");
        } else {
            $u = false;
        }
        return is_array($u) ? $u : null;
    }
    // several at once - ids or @usernames, one a line or split by spaces or
    // commas: [found user rows by id, what was not found]
    function svcgive_find_users($text)
    {
        $found = [];
        $missing = [];
        foreach (preg_split('/[\s,،]+/u', trim((string) $text), -1, PREG_SPLIT_NO_EMPTY) as $tok) {
            $u = svcgive_find_user($tok);
            if ($u === null) {
                $missing[] = $tok;
            } else {
                $found[(string) $u['id']] = $u;
            }
        }
        return [$found, $missing];
    }
    // «all users» is this 👤 tab's users, like every other action there
    function svcgive_tab_user_ids($lang)
    {
        global $pdo;
        [$lw, $lp] = user_lang_where($lang);
        $st = $pdo->prepare("SELECT id FROM user WHERE {$lw}");
        $st->execute($lp);
        return array_map('strval', $st->fetchAll(PDO::FETCH_COLUMN));
    }
    // the ✅ screen: who gets it, and - once it is anyone's but one person's -
    // what sharing it means
    function svcgive_confirm_text($d, $panelRow, $count, $sharedWith, $textbotlang)
    {
        $t = $textbotlang['Admin']['UserMgmt'];
        $vars = [
            '{username}' => htmlspecialchars((string) ($d['sg_user'] ?? '')),
            '{panel}' => htmlspecialchars((string) $panelRow['name_panel']),
            '{n}' => $count,
            '{lang}' => $textbotlang['bottext']['langs'][$d['sg_lang'] ?? 'fa'] ?? '',
        ];
        if (($d['sg_to'] ?? null) === 'all') {
            $out = strtr($t['assignConfirmAll'], $vars);
        } elseif (count((array) ($d['sg_to'] ?? [])) === 1) {
            $u = select("user", "*", "id", (string) $d['sg_to'][0], "select");
            $out = strtr($t['assignConfirm'], $vars + [
                '{id}' => $d['sg_to'][0],
                '{name}' => (is_array($u) && !empty($u['username']) && $u['username'] !== 'none') ? '@' . htmlspecialchars($u['username']) : '',
            ]);
        } else {
            $out = strtr($t['assignConfirmMany'], $vars + ['{ids}' => implode(' ', array_map(fn($i) => "<code>{$i}</code>", array_slice((array) $d['sg_to'], 0, 20))) . ($count > 20 ? ' …' : '')]);
        }
        if ($sharedWith > 0) {
            $out .= strtr($t['assignAlready'], ['{n}' => $sharedWith]);
        }
        if ($count + $sharedWith > 1) {
            $out .= $t['assignShared'];
        }
        return $out;
    }
    // what the admin is shown about the account before handing it over
    function svcgive_account_text($acc, $textbotlang)
    {
        $t = $textbotlang['Admin']['UserMgmt'];
        $gb = fn($b) => rtrim(rtrim(number_format(((float) $b) / 1073741824, 2, '.', ''), '0'), '.');
        $limit = (float) ($acc['data_limit'] ?? 0);
        $exp = (int) ($acc['expire'] ?? 0);
        return strtr($t['assignAccount'], [
            '{status}' => htmlspecialchars((string) ($acc['status'] ?? '')),
            '{used}' => $gb($acc['used_traffic'] ?? 0),
            '{limit}' => $limit > 0 ? $gb($limit) . ' GB' : $t['assignUnlimited'],
            '{expire}' => $exp > 0 ? jdate('Y/m/d', $exp) : $t['assignUnlimited'],
        ]);
    }
    // Hands it over: one invoice row per customer, as the panel has the
    // account now, named in each one's language. $users: [id => lang].
    // Returns how many rows it made.
    function svcgive_assign_many($panelRow, $acc, array $users)
    {
        global $pdo;
        $limit = (float) ($acc['data_limit'] ?? 0);
        $exp = (int) ($acc['expire'] ?? 0);
        $volume = $limit > 0 ? rtrim(rtrim(number_format($limit / 1073741824, 2, '.', ''), '0'), '.') : '0';
        $days = $exp > 0 ? (string) max(0, (int) ceil(($exp - time()) / 86400)) : '0';
        $status = ['limited' => 'end_of_volume', 'expired' => 'end_of_time', 'on_hold' => 'send_on_hold'][$acc['status'] ?? ''] ?? 'active';
        $notif = json_encode(['volume' => false, 'time' => false]);
        $names = [];
        $stmt = $pdo->prepare("INSERT INTO invoice (id_user, id_invoice, username, time_sell, Service_location, name_product, price_product, Volume, Service_time, Status, notifctions) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
        // one transaction: «all users» can be thousands of rows
        $pdo->beginTransaction();
        foreach ($users as $uid => $lang) {
            $lang = in_array($lang, panel_langs(), true) ? $lang : 'fa';
            $names[$lang] = $names[$lang] ?? lang_tab_texts($lang)['users']['status']['assignedServiceName'];
            $stmt->execute([(string) $uid, bin2hex(random_bytes(4)), (string) $acc['username'], time(), (string) $panelRow['name_panel'], $names[$lang], '0', $volume, $days, $status, $notif]);
        }
        $pdo->commit();
        return count($users);
    }
}
if (!function_exists('aff_section_rows')) {
    // 👥 طرح‌های زیرمجموعه‌گیری: a short page with the two plans, a page for
    // each, and one for each plan's 🛡. One colour, one meaning:
    // 🟢 on · 🔴 off (the state is in the text too) · 🔵 a value to set ·
    // ⚪️ another page or back.
    function aff_section_rows($lang, $section)
    {
        $tx = lang_tab_texts('fa');
        $s = $tx['Admin']['FeatureSection'];
        $st = $tx['Admin']['Status'];
        $v = feature_section_effective($lang);
        $cur = currency_for_lang($lang);
        $tog = fn($isOn, $label, $cb) => ['text' => ($isOn ? '✅ ' : '❌ ') . $label, 'callback_data' => $cb, 'style' => $isOn ? 'success' : 'danger'];
        $val = fn($label, $cb) => ['text' => $label, 'callback_data' => $cb, 'style' => 'primary'];
        $go = fn($label, $cb) => ['text' => $label, 'callback_data' => $cb];
        $plan = fn($isOn, $cb) => ['text' => $isOn ? $s['affPlanIsOn'] : $s['affPlanIsOff'], 'callback_data' => $cb, 'style' => $isOn ? 'success' : 'danger'];
        $rw = affrw_cfg($lang);
        if ($section === 'aff') {
            return [
                [$go(strtr($s['affPlanBtn'], ['{plan}' => $s['refvPlan_c'], '{state}' => $v['aff_classic'] === '1' ? $st['statuson'] : $st['statusoff']]), "flsec:{$lang}:affc")],
                [$go(strtr($s['affPlanBtn'], ['{plan}' => $s['refvPlan_r'], '{state}' => $rw['on'] ? $st['statuson'] : $st['statusoff']]), "flsec:{$lang}:affr")],
                [$go($s['back'], "fls_lang:{$lang}")],
            ];
        }
        if ($section === 'affc') {
            return [
                [$plan($v['aff_classic'] === '1', "flstog:{$lang}:aff_classic:{$v['aff_classic']}")],
                [$val(strtr($s['affPercentBtn'], ['{percent}' => (string) $v['aff_percent']]), "flsask:{$lang}:aff_percent")],
                [$tog($v['aff_commission'] === 'oncommission', $s['affCommissionBtn'], "flstog:{$lang}:aff_commission:{$v['aff_commission']}")],
                [$tog($v['aff_firstbuy'] === 'on_buy_porsant', $s['affFirstBuyBtn'], "flstog:{$lang}:aff_firstbuy:{$v['aff_firstbuy']}")],
                [$val(strtr($s['affGiftBtn'], ['{gift}' => money($v['aff_giftamount'], $cur)]), "flsask:{$lang}:aff_giftamount")],
                [$tog($v['aff_startgift'] === 'onDiscountaffiliates', $s['affStartGiftBtn'], "flstog:{$lang}:aff_startgift:{$v['aff_startgift']}")],
                [$val($s['affBannerBtn'], "flsask:{$lang}:aff_banner")],
                [$go(strtr($s['refvOpenBtn'], ['{state}' => refv_state_text($lang, 'c', $s, true)]), "flsec:{$lang}:refvc")],
                [$go($s['affTestClassicBtn'], "afftest:{$lang}:c")],
                [$go($s['back'], "flsec:{$lang}:aff")],
            ];
        }
        if ($section === 'affr') {
            $rwPanel = affrw_panel($rw);
            return [
                [$plan($rw['on'], "flsaffrw:{$lang}:on")],
                [
                    $val(strtr($s['affrwNeedBtn'], ['{need}' => $rw['need']]), "flsask:{$lang}:affrw_need"),
                    $val(strtr($s['affrwMaxBtn'], ['{max}' => $rw['max']]), "flsask:{$lang}:affrw_max"),
                ],
                [
                    $val(strtr($s['affrwVolumeBtn'], ['{volume}' => volume_num($rw['gb'])]), "flsask:{$lang}:affrw_gb"),
                    $val(strtr($s['affrwDaysBtn'], ['{days}' => $rw['days']]), "flsask:{$lang}:affrw_days"),
                ],
                // 🚀 only when its panel is Rebecca - nothing else holds a speed
                ...($rwPanel !== null && ($rwPanel['type'] ?? '') === 'rebecca'
                    ? [[$val(strtr($s['affrwSpeedBtn'], ['{speed}' => speed_limit_label($rw['speed'], $s['affrwSpeedNone'])]), "flsask:{$lang}:affrw_speed")]]
                    : []),
                [$val(strtr($s['affrwPanelBtn'], ['{panel}' => $rwPanel !== null ? $rwPanel['name_panel'] : $s['affrwNoPanel']]), "flsaffrw:{$lang}:panel")],
                [$val(strtr($s['affrwModeBtn'], ['{mode}' => $rw['mode'] === 'auto' ? $s['affrwModeAuto'] : $s['affrwModeAdmin']]), "flsaffrw:{$lang}:mode")],
                [$tog(feature_setting_value('affrw_leave', $lang, '0') === '1', $s['affrwLeaveBtn'], "flsaffrw:{$lang}:leave")],
                [$val($s['affrwResetUserBtn'], "flsask:{$lang}:affrw_reset")],
                [$go(strtr($s['refvOpenBtn'], ['{state}' => refv_state_text($lang, 'r', $s, true)]), "flsec:{$lang}:refvr")],
                [$go($s['affTestRewardBtn'], "afftest:{$lang}:r")],
                [$go($s['back'], "flsec:{$lang}:aff")],
            ];
        }
        // 🛡 of one plan
        $p = $section === 'refvr' ? 'r' : 'c';
        $rv = refv_cfg($lang, $p);
        $names = array_map(fn($r) => (string) $r['remark'], refv_channel_rows($rv));
        return [
            [$tog($rv['phone'], $s['refvPhoneBtn'], "flsrefv:{$lang}:{$p}:phone")],
            [$tog($rv['channel'], $s['refvChannelBtn'], "flsrefv:{$lang}:{$p}:channel")],
            [$val(strtr($s['refvChannelsBtn'], ['{list}' => $names ? implode('، ', $names) : $s['refvNone']]), "flsrefv:{$lang}:{$p}:pick")],
            [$val(strtr($s['refvVipBtn'], ['{n}' => count($rv['vip'])]), "flsrefv:{$lang}:{$p}:vip")],
            [$go($s['back'], "flsec:{$lang}:aff{$p}")],
        ];
