        sendmessage($to, strtr($real ? $t['introRReal'] : $t['introRView'], $vars) . ($cfg['on'] ? '' : $t['planOff']) . ($cfg['mode'] === 'auto' ? $t['modeAuto'] : ''), null, 'HTML');
