                '{lang}' => $langName,
                '{round}' => 1,
                '{max}' => $cfg['max'],
                '{services}' => $r['servicesNone'],
                '{count}' => $cfg['need'],
                '{need}' => $cfg['need'],
                '{volume}' => volume_num($cfg['gb']),
                '{days}' => $cfg['days'],
                '{panel}' => aff_bidi($panel['name_panel'] ?? '', htmlspecialchars((string) ($panel['name_panel'] ?? $fa['Admin']['FeatureSection']['affrwNoPanel']))),
                '{list}' => rtrim($list),
