        configdisplay_element_set_emoji($cc_m[1], (int) $cc_m[2], '', $cc_icon, $cc_kind);
        $cc_msg = "✅ ایموجی پریمیوم ذخیره شد! 💎";
    } else {
        preg_match('/^\X/u', trim((string) $text), $cc_em);
        $cc_emoji = $cc_em[0] ?? '';
