    Editmessagetext($from_id, $message_id, $cd_text, $cd_kb, 'HTML');
    return;
}
if (preg_match('/^cfgdeliv\|set\|([a-z]{2})\|([^|]+)\|(purchase|usertest|affrw)\|(1|2)\|([bur])$/', $datain, $cd_m) && $adminrulecheck['rule'] == "administrator") {
    config_delivery_set_mode($cd_m[3], $cd_m[2], $cd_m[4], $cd_m[1]);
    list($cd_text, $cd_kb) = config_delivery_panel_payload($cd_m[1], $cd_m[2], $cd_m[5]);
    Editmessagetext($from_id, $message_id, $cd_text, $cd_kb, 'HTML');
    return;
}
if (preg_match('/^admperm\|(open|test|buy|affrw)\|([a-z]{2})$/', $datain, $ap_m) && $adminrulecheck['rule'] == "administrator") {
    $ap_setting = select("setting", "*", null, null, "select");
    if ($ap_m[1] === 'test') {
        update("setting", "admin_test_unlimited", ((string) ($ap_setting['admin_test_unlimited'] ?? '1') !== '0') ? '0' : '1', null, null);
    } elseif ($ap_m[1] === 'buy') {
        update("setting", "admin_buy_free", ((string) ($ap_setting['admin_buy_free'] ?? '0') === '1') ? '0' : '1', null, null);
    } elseif ($ap_m[1] === 'affrw') {
        update("setting", "admin_affrw_unlimited", ((string) ($ap_setting['admin_affrw_unlimited'] ?? '0') === '1') ? '0' : '1', null, null);
    }
    list($ap_text, $ap_kb) = admin_perm_payload($ap_m[2]);
    Editmessagetext($from_id, $message_id, $ap_text, $ap_kb, 'HTML');
    return;
}
if (preg_match('/^cfgdeliv\|qr\|([a-z]{2})\|([^|]+)\|(purchase|usertest|affrw)\|([bur])$/', $datain, $cd_m) && $adminrulecheck['rule'] == "administrator") {
    // mode 2 sends the config page only - there is no message for a QR to ride
    // on, so it cannot be switched on there (only off, if an old setting has it)
    if (config_delivery_mode($cd_m[3], $cd_m[2], $cd_m[1]) === '2' && !config_delivery_qr_on($cd_m[3], $cd_m[2], $cd_m[1])) {
        telegram('answerCallbackQuery', [
            'callback_query_id' => $callback_query_id,
            'text' => "❌ در حالت ۲ ارسال QR کد ممکن نیست.\n\nحالت ۲ فقط صفحه‌ی کانفیگ رو می‌فرسته. برای QR، اول «حالت ۱» رو انتخاب کن.",
            'show_alert' => true,
            'cache_time' => 1,
        ]);
        return;
    }
    config_delivery_set_qr($cd_m[3], $cd_m[2], !config_delivery_qr_on($cd_m[3], $cd_m[2], $cd_m[1]), $cd_m[1]);
    list($cd_text, $cd_kb) = config_delivery_panel_payload($cd_m[1], $cd_m[2], $cd_m[4]);
    Editmessagetext($from_id, $message_id, $cd_text, $cd_kb, 'HTML');
    return;
}
if (preg_match('/^cfgdeliv\|rst\|([a-z]{2})\|([^|]+)\|(purchase|usertest|affrw)\|([bur])$/', $datain, $cd_m) && $adminrulecheck['rule'] == "administrator") {
    config_delivery_panel_reset($cd_m[2], $cd_m[3], $cd_m[1]);
    list($cd_text, $cd_kb) = config_delivery_panel_payload($cd_m[1], $cd_m[2], $cd_m[4]);
    // names the mode the reset actually restores - config_delivery_default_mode()
    // returns '1', so this line claiming "حالت ۲" has been telling admins their
    // panel went somewhere it did not
    Editmessagetext($from_id, $message_id, "🔁 این پنل به حالت پیش‌فرض (حالت " . config_delivery_mode_fa(config_delivery_default_mode()) . "، QR کد روشن) برگشت.\n\n" . $cd_text, $cd_kb, 'HTML');
    return;
}
if (preg_match('/^cfgdeliv\|cfgcol\|([a-z]{2})\|([^|]+)\|([bur])$/', $datain, $cd_m) && $adminrulecheck['rule'] == "administrator") {
    // the flow this screen belongs to: test account ('u'), 🎁 gift ('r') or purchase
    $cd_colKind = ['u' => 'usertest', 'r' => 'affrw'][$cd_m[3]] ?? 'buy';
    cfgcol_back_set($from_id, $cd_colKind, "cfgdeliv|p|{$cd_m[1]}|{$cd_m[2]}|{$cd_m[3]}");
    list($cd_text, $cd_kb) = config_col_order_payload($textbotlang, $cd_m[1], null, "cfgdeliv|p|{$cd_m[1]}|{$cd_m[2]}|{$cd_m[3]}", $cd_colKind === 'affrw' ? 'users.affiliates.rewardConfigHint' : null, $cd_colKind);
    Editmessagetext($from_id, $message_id, $cd_text, $cd_kb, 'HTML');
    return;
}
// the service buttons are edited for four places - the service's screen in
// 🛍 سرویس‌های من (statusbtn|...) and the messages that deliver a bought
// service's, a test account's and a 🎁 referral gift's config (buybtn|,
// testbtn|, refbtn|). Same screens, separate settings (statusbtn_kinds).
$sb_kind = statusbtn_kind_of_data((string) $datain);
$sb_pfx = statusbtn_prefix($sb_kind);
$sb_data = $sb_kind === 'mine' ? $datain : 'statusbtn|' . substr((string) $datain, strlen($sb_pfx) + 1);
$sb_ks = $sb_kind === 'mine' ? '' : $sb_kind . ':';
if (preg_match('/^statusbtn\|list\|([a-z]{2})$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    list($sb_text, $sb_kb) = statusbtn_list_payload($sb_m[1], $textbotlang, $sb_kind);
    Editmessagetext($from_id, $message_id, $sb_text, $sb_kb, 'HTML');
    return;
}
if (preg_match('/^statusbtn\|cat\|([a-z]{2})\|(color|emoji|text|layout)$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    if ($sb_m[2] === 'layout') {
        list($sb_text, $sb_kb) = statusbtn_layout_payload($sb_m[1], $textbotlang, null, $sb_kind);
    } else {
        list($sb_text, $sb_kb) = statusbtn_cat_payload($sb_m[1], $sb_m[2], $textbotlang, $sb_kind);
    }
    Editmessagetext($from_id, $message_id, $sb_text, $sb_kb, 'HTML');
    return;
}
if (preg_match('/^statusbtn\|laypick\|([a-z]{2})\|(\d+)$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    list($sb_text, $sb_kb) = statusbtn_layout_payload($sb_m[1], $textbotlang, (int) $sb_m[2], $sb_kind);
    Editmessagetext($from_id, $message_id, $sb_text, $sb_kb, 'HTML');
    return;
}
if (preg_match('/^statusbtn\|laycancel\|([a-z]{2})$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    list($sb_text, $sb_kb) = statusbtn_layout_payload($sb_m[1], $textbotlang, null, $sb_kind);
    Editmessagetext($from_id, $message_id, $sb_text, $sb_kb, 'HTML');
    return;
}
if (preg_match('/^statusbtn\|layswap\|([a-z]{2})\|(\d+)\|(\d+)$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    $sb_ordered = statusbtn_ordered_keys($sb_m[1], $textbotlang, $sb_kind);
    $sb_i1 = (int) $sb_m[2];
    $sb_i2 = (int) $sb_m[3];
    if (isset($sb_ordered[$sb_i1], $sb_ordered[$sb_i2]) && $sb_i1 !== $sb_i2) {
        $sb_tmp = $sb_ordered[$sb_i1];
        $sb_ordered[$sb_i1] = $sb_ordered[$sb_i2];
        $sb_ordered[$sb_i2] = $sb_tmp;
        statusbtn_set_order($sb_m[1], $sb_ordered, $sb_kind);
    }
    list($sb_text, $sb_kb) = statusbtn_layout_payload($sb_m[1], $textbotlang, null, $sb_kind);
    Editmessagetext($from_id, $message_id, $sb_text, $sb_kb, 'HTML');
    return;
}
if (preg_match('/^statusbtn\|layreset\|([a-z]{2})$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    statusbtn_reset_order($sb_m[1], $sb_kind);
    list($sb_text, $sb_kb) = statusbtn_layout_payload($sb_m[1], $textbotlang, null, $sb_kind);
    Editmessagetext($from_id, $message_id, "🔁 چیدمان به پیش‌فرض برگشت.\n\n" . $sb_text, $sb_kb, 'HTML');
