}
if (preg_match('/^statusbtn\|postoggle\|([a-z]{2})\|([^|]+)$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    statusbtn_toggle_pos($sb_m[1], $sb_m[2], $sb_kind);
    list($sb_text, $sb_kb) = statusbtn_cat_payload($sb_m[1], 'emoji', $textbotlang, $sb_kind);
    Editmessagetext($from_id, $message_id, $sb_text, $sb_kb, 'HTML');
    return;
}
if (preg_match('/^statusbtn\|open\|([a-z]{2})\|([^|]+)$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    list($sb_text, $sb_kb) = statusbtn_detail_payload($sb_m[1], $sb_m[2], $textbotlang, $sb_kind);
    Editmessagetext($from_id, $message_id, $sb_text, $sb_kb, 'HTML');
    return;
}
if (preg_match('/^statusbtn\|text\|([a-z]{2})\|([^|]+)$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    savedata("clear", "bt_msgid", $message_id);
    step("statusbtntxt-{$sb_m[1]}-{$sb_ks}{$sb_m[2]}", $from_id);
    $sb_kb = json_encode(['inline_keyboard' => [
        [['text' => '❌ انصراف', 'callback_data' => "{$sb_pfx}|cat|{$sb_m[1]}|text"]],
    ]]);
    Editmessagetext($from_id, $message_id, "✏️ متن جدید دکمه رو بفرست ✍️\n\n💎 اگه اول اسم یه ایموجی پریمیوم بذاری، همون ایموجی پریمیوم دکمه می‌شه.", $sb_kb, 'HTML');
    return;
}
if (preg_match('/^statusbtn\|style\|([a-z]{2})\|([^|]+)\|(primary|success|danger)$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    statusbtn_set_field($sb_m[1], $sb_m[2], 'style', $sb_m[3], $sb_kind);
    list($sb_text, $sb_kb) = statusbtn_detail_payload($sb_m[1], $sb_m[2], $textbotlang, $sb_kind);
    Editmessagetext($from_id, $message_id, $sb_text, $sb_kb, 'HTML');
    return;
}
if (preg_match('/^statusbtn\|emoji\|([a-z]{2})\|([^|]+)$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    step("statusbtnemo-{$sb_m[1]}-{$sb_ks}{$sb_m[2]}", $from_id);
    $sb_kb = json_encode(['inline_keyboard' => [
        [['text' => '❌ انصراف', 'callback_data' => "{$sb_pfx}|cat|{$sb_m[1]}|emoji"]],
    ]]);
    $sb_prompt = "💎 یه ایموجی (ساده یا پریمیوم) بفرست، کنار متن دکمه نشون داده می‌شه 👇\n\n";
    $sb_prompt .= "📌 ایموجی پریمیوم به‌خاطر محدودیت تلگرام همیشه سمت راست (ابتدای متن) قرار می‌گیره.\n";
    $sb_prompt .= "برای ایموجی ساده، جای قرارگیریش (چپ/راست) از دکمه‌های صفحه‌ی قبل قابل تغییره.";
    Editmessagetext($from_id, $message_id, $sb_prompt, $sb_kb, 'HTML');
    return;
}
if (preg_match('/^statusbtn\|simple\|([a-z]{2})\|([^|]+)$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    $sb_ov = statusbtn_override($sb_m[1], $sb_m[2], $sb_kind);
    statusbtn_set_field($sb_m[1], $sb_m[2], 'simple', empty($sb_ov['simple']), $sb_kind);
    list($sb_text, $sb_kb) = statusbtn_detail_payload($sb_m[1], $sb_m[2], $textbotlang, $sb_kind);
    Editmessagetext($from_id, $message_id, $sb_text, $sb_kb, 'HTML');
    return;
}
if (preg_match('/^statusbtn\|pos\|([a-z]{2})\|([^|]+)\|(left|right)$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    statusbtn_set_field($sb_m[1], $sb_m[2], 'pos', $sb_m[3], $sb_kind);
    list($sb_text, $sb_kb) = statusbtn_detail_payload($sb_m[1], $sb_m[2], $textbotlang, $sb_kind);
    Editmessagetext($from_id, $message_id, $sb_text, $sb_kb, 'HTML');
    return;
}
if (preg_match('/^statusbtn\|rst\|([a-z]{2})\|([^|]+)$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    statusbtn_reset($sb_m[1], $sb_m[2], $sb_kind);
    list($sb_text, $sb_kb) = statusbtn_detail_payload($sb_m[1], $sb_m[2], $textbotlang, $sb_kind);
    Editmessagetext($from_id, $message_id, "🔁 این دکمه به پیش‌فرض برگشت.\n\n" . $sb_text, $sb_kb, 'HTML');
    return;
}
if (preg_match('/^statusbtn\|rstall\|([a-z]{2})$/', $sb_data, $sb_m) && $adminrulecheck['rule'] == "administrator") {
    statusbtn_reset_all($sb_m[1], $sb_kind);
    list($sb_text, $sb_kb) = statusbtn_list_payload($sb_m[1], $textbotlang, $sb_kind);
    Editmessagetext($from_id, $message_id, "🔁 همه‌ی دکمه‌ها به پیش‌فرض برگشتن.\n\n" . $sb_text, $sb_kb, 'HTML');
    return;
}
if (preg_match('/^bt_sep\|(\w+)$/', $datain, $bt_sep_m) && $adminrulecheck['rule'] == "administrator") {
    telegram('answerCallbackQuery', [
        'callback_query_id' => $callback_query_id,
        'text' => bt_section_meta($bt_sep_m[1])['alert'],
        'show_alert' => true,
        'cache_time' => 1,
    ]);
    return;
}
// The alert that answered the sample config buttons on the caption-preview
// screen lived here. That screen is gone, and nothing else ever produced its
// callback.
if (preg_match('/^cfgcolbt-(getfirst|namefirst)-([a-z]{2})$/', $datain, $cc_m) && $adminrulecheck['rule'] == "administrator") {
    config_col_set_order($cc_m[2], $cc_m[1] === 'namefirst', 'usertest');
    list($cc_info, $cc_kb) = cfgcol_hub_render($textbotlang, $cc_m[2], 'usertest');
    Editmessagetext($from_id, $message_id, $cc_info, $cc_kb, 'HTML');
    return;
}
//----------------[  button color manager handlers  ]----------------
if ($text == "🎨 رنگ‌بندی دکمه‌ها" && $adminrulecheck['rule'] == "administrator") {
    sendmessage($from_id, "🎨 <b>بخش رنگ‌بندی دکمه‌های منوی اصلی</b>\n\nنوع کیبورد رو انتخاب کن 👇", $keyboard_colormanage, 'HTML');
    step('colormanage', $from_id);
    return;
}
if ($text == "🎛 رنگ دکمه‌های شیشه‌ای" && $adminrulecheck['rule'] == "administrator") {
    $color_kb = color_editor_payload('i', $textbotlang);
    sendmessage($from_id, "🎛 <b>رنگ‌بندی دکمه‌های شیشه‌ای (اینلاین)</b>\n\nاین لیست، پیش‌نمایش زنده‌ی منوته 🎨\nروی هر دکمه بزن تا رنگش عوض بشه 👇\n⚪ پیش‌فرض ← 🔵 آبی ← 🟢 سبز ← 🔴 قرمز\n🚫 = دکمه پنهان شده", $color_kb, 'HTML');
    return;
}
if ($text == "⌨️ رنگ دکمه‌های کیبوردی" && $adminrulecheck['rule'] == "administrator") {
    $color_kb = color_editor_payload('r', $textbotlang);
    sendmessage($from_id, "⌨️ <b>رنگ‌بندی دکمه‌های کیبوردی (معمولی)</b>\n\nاین لیست، پیش‌نمایش زنده‌ی منوته 🎨\nروی هر دکمه بزن تا رنگش عوض بشه 👇\n⚪ پیش‌فرض ← 🔵 آبی ← 🟢 سبز ← 🔴 قرمز\n🚫 = دکمه پنهان شده", $color_kb, 'HTML');
    return;
}
if (preg_match('/^btncolor-(i|r)-([a-z]{2})-(\d+)-(\d+)$/', $datain, $colormatch) && $adminrulecheck['rule'] == "administrator") {
    $color_mode = $colormatch[1];
    $color_lang = $colormatch[2];
    $color_r = intval($colormatch[3]);
    $color_c = intval($colormatch[4]);
    $color_layout = mainmenu_layout_get($color_lang);
    if (is_array($color_layout) && isset($color_layout['keyboard'][$color_r][$color_c]) && is_array($color_layout['keyboard'][$color_r][$color_c])) {
        $color_field = ($color_mode == 'r') ? 'style_reply' : 'style';
        $color_order = ['', 'primary', 'success', 'danger'];
        $color_cur = isset($color_layout['keyboard'][$color_r][$color_c][$color_field]) ? $color_layout['keyboard'][$color_r][$color_c][$color_field] : '';
        $color_cur_idx = array_search($color_cur, $color_order, true);
        if ($color_cur_idx === false) {
            $color_cur_idx = 0;
        }
        $color_next = $color_order[($color_cur_idx + 1) % count($color_order)];
        if ($color_next === '') {
            unset($color_layout['keyboard'][$color_r][$color_c][$color_field]);
        } else {
            $color_layout['keyboard'][$color_r][$color_c][$color_field] = $color_next;
        }
        mainmenu_layout_save($color_lang, $color_layout);
    }
    $color_kb = color_editor_payload($color_mode, $textbotlang, $color_lang);
    $color_title = ($color_mode == 'r') ? "⌨️ <b>رنگ‌بندی دکمه‌های کیبوردی (معمولی)</b>" : "🎛 <b>رنگ‌بندی دکمه‌های شیشه‌ای (اینلاین)</b>";
    Editmessagetext($from_id, $message_id, $color_title . "\n\nاین لیست، پیش‌نمایش زنده‌ی منوته 🎨\nروی هر دکمه بزن تا رنگش عوض بشه 👇\n⚪ پیش‌فرض ← 🔵 آبی ← 🟢 سبز ← 🔴 قرمز\n🚫 = دکمه پنهان شده", $color_kb, 'HTML');
    return;
}

//----------------[  language switch settings handlers  ]----------------
if ($text == "🌐 تنظیمات تغییر زبان" && $adminrulecheck['rule'] == "administrator") {
    $lsw_kb = lang_switch_settings_payload();
    sendmessage($from_id, "🌐 <b>تنظیمات تغییر زبان کاربر</b>\n\n1️⃣ روشن/خاموش بودن نمایش خودکار منوی انتخاب زبان\n2️⃣ نمایش فقط بار اول یا هر بار که کاربر /start می‌زنه\n3️⃣ زبان‌هایی که توی منوی انتخاب نشون داده می‌شن (حداقل یکی باید روشن بمونه)\n\nروی هر مورد بزن تا تنظیمش کنی 👇", $lsw_kb, 'HTML');
    return;
}
// all four write through lang_switch_save(), so the stored shape stays one
// thing rather than four hand-rolled json_encode calls that could drift
if ($datain == "lsw_toggle" && $adminrulecheck['rule'] == "administrator") {
    lang_switch_save(['enabled' => !lang_switch_settings()['enabled']]);
    Editmessagetext($from_id, $message_id, lang_switch_settings_caption($textbotlang), lang_switch_settings_payload(), 'HTML');
    return;
}
if (preg_match('/^lsw_mode-(once|always)$/', $datain, $lsw_match) && $adminrulecheck['rule'] == "administrator") {
    lang_switch_save(['mode' => $lsw_match[1]]);
    Editmessagetext($from_id, $message_id, lang_switch_settings_caption($textbotlang), lang_switch_settings_payload(), 'HTML');
    return;
}
if (preg_match('/^lsw_lang-(fa|en)$/', $datain, $lsw_match) && $adminrulecheck['rule'] == "administrator") {
    $lsw_langs = lang_switch_settings()['langs'];
    $lsw_code = $lsw_match[1];
    $lsw_warn = '';
    if (in_array($lsw_code, $lsw_langs, true)) {
        if (count($lsw_langs) <= 1) {
            $lsw_warn = "⚠️ حداقل یه زبون باید روشن بمونه!\n\n";
        } else {
            $lsw_langs = array_values(array_diff($lsw_langs, [$lsw_code]));
        }
    } else {
        $lsw_langs[] = $lsw_code;
    }
    lang_switch_save(['langs' => $lsw_langs]);
    Editmessagetext($from_id, $message_id, $lsw_warn . lang_switch_settings_caption($textbotlang), lang_switch_settings_payload(), 'HTML');
    return;
}

//----------------[  close-button sticker (🖼 استیکر دکمه بستن), per section  ]----------------
if (preg_match('/^clst2tog:([a-z]{2}):([a-z]{2})$/', $datain, $cs_m) && $adminrulecheck['rule'] == "administrator") {
    $cs_key = close_sticker_alias_to_key($cs_m[2]);
    if ($cs_key === null) {
        return;
    }
