    $ly_default = array_map(static fn($ly_frow) => array_column($ly_frow, 'text'), mainmenu_factory_layout()['keyboard']);
    $ly_bykey = [];
    if (is_array($ly_layout) && isset($ly_layout['keyboard']) && is_array($ly_layout['keyboard'])) {
        foreach ($ly_layout['keyboard'] as $ly_row) {
            foreach ((array) $ly_row as $ly_b) {
                if (is_array($ly_b) && isset($ly_b['text'])) {
                    $ly_bykey[$ly_b['text']] = $ly_b;
                }
            }
        }
    }
    $ly_newrows = [];
    foreach ($ly_default as $ly_drow) {
        $ly_nr = [];
        foreach ($ly_drow as $ly_k) {
            if (isset($ly_bykey[$ly_k])) {
                $ly_nr[] = $ly_bykey[$ly_k];
                unset($ly_bykey[$ly_k]);
            }
        }
        if (!empty($ly_nr)) {
            $ly_newrows[] = $ly_nr;
        }
    }
    foreach ($ly_bykey as $ly_b) {
        $ly_newrows[] = [$ly_b];
    }
    if (!is_array($ly_layout)) {
        $ly_layout = [];
    }
    $ly_changed = $ly_newrows !== $ly_layout['keyboard'];
    $ly_layout['keyboard'] = $ly_newrows;
    mainmenu_layout_save($ly_lang, $ly_layout);
    telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'cache_time' => 1,
