if (preg_match('/^renamereset-([a-z]{2})$/', $datain, $rn_m) && $adminrulecheck['rule'] == "administrator") {
    $rn_lang = $rn_m[1];
    // factory default is NOT "everything visible" - table.php's own keyboardmain
    // ships these keys pre-hidden, so resetting must restore THAT, not clear
    // every hidden flag unconditionally (which used to undo the factory default)
    $rn_default_hidden = mainmenu_default_hidden_keys();
    $rn_layout = mainmenu_layout_get($rn_lang);
    if (is_array($rn_layout) && isset($rn_layout['keyboard']) && is_array($rn_layout['keyboard'])) {
        foreach ($rn_layout['keyboard'] as $rn_r => $rn_row) {
            if (!is_array($rn_row)) {
                continue;
            }
            foreach ($rn_row as $rn_c => $rn_b) {
                if (is_array($rn_b)) {
                    unset($rn_layout['keyboard'][$rn_r][$rn_c]['custom_text']);
                    if (isset($rn_b['text']) && in_array($rn_b['text'], $rn_default_hidden, true)) {
                        $rn_layout['keyboard'][$rn_r][$rn_c]['hidden'] = true;
                    } else {
                        unset($rn_layout['keyboard'][$rn_r][$rn_c]['hidden']);
                    }
                }
            }
        }
        // shared by every language - one tab's reset leaves it as it was
        $rn_layout['keyboard'] = mainmenu_langbtn_mark($rn_layout['keyboard'], mainmenu_langbtn_hidden());
        $rn_changed = $rn_layout['keyboard'] !== mainmenu_layout_get($rn_lang)['keyboard'];
        mainmenu_layout_save($rn_lang, $rn_layout);
    }
    // a tap that changes nothing redraws the same message, which Telegram
    // refuses ("message is not modified") - the toast is the answer then
    telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'cache_time' => 1,
        'text' => !empty($rn_changed) ? '🔄 نام و نمایش دکمه‌ها به پیش‌فرض برگشت' : '✅ همه‌ی دکمه‌ها از قبل روی پیش‌فرض بودن']);
    $rn_kb = rename_editor_payload($textbotlang, null, $rn_lang);
    Editmessagetext($from_id, $message_id, "🔄 نام و نمایش دکمه‌ها به پیش‌فرض برگشت (رنگ و ایموجی و استیکرها حفظ شدن)" . mainmenu_tab_note($rn_lang) . mainmenu_langbtn_note() . "\n\n✏️ <b>نام و نمایش دکمه‌های منو</b> 👇", $rn_kb, 'HTML');
    return;
}

//----------------[  🖥 نودهای ربکا  ]----------------
// cvol.php: 🧩 حجم دلخواه's hub - a panel's custom plans (💰 قیمت‌گذاری,
// ⚙️ وضعیت قابلیت‌ها, 🏬 تنظیمات فروشگاه). Its ➕/⏳/🌐 in the glass 💰 menu
// hand the panel's own questions on as if typed, so those run as before.
if (function_exists('cvol_admin_dispatch') && cvol_admin_dispatch()) {
    return;
}
// rbsvc.php: ⚙️ تنظیم پروتکل و اینباند on a Rebecca panel - its services as
// buttons instead of a username (other panels go on to the username question)
if (function_exists('rbsvc_admin_dispatch') && rbsvc_admin_dispatch()) {
    return;
}
// directpay.php: 💳 پرداخت مستقیم - its switch in 🛒 وضعیت قابلیت‌های فروشگاه and its settings hub
if (function_exists('dpay_admin_dispatch') && dpay_admin_dispatch()) {
    return;
}
// backup_import.php: 📥 a backup handed to the bot (🗄 تنظیمات بکاپ) - one
// message carries the whole import: the prompt, the files as they come in,
// a password when one is asked, the last yes, then the watcher's progress.
// Administrators only; the files never leave storage/restore until used.
if (preg_match('/^bkimp_(start|hub|cancel|go|back|yes|pick)(?:\|([a-f0-9]{6})\|(\d))?$/', $datain, $bi_m) && $adminrulecheck['rule'] == "administrator") {
    $bi_t = $textbotlang['Admin']['BackupImport'];
    $bi_alert = function ($text) use ($callback_query_id) {
        telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => $text, 'show_alert' => true]);
    };
    $bi_hub = function ($note = '') use ($textbotlang, $from_id, $message_id) {
        [$bk_caption, $bk_kb] = backup_settings_hub_payload($textbotlang);
        Editmessagetext($from_id, $message_id, ($note !== '' ? $note . "\n\n" : '') . $bk_caption, $bk_kb, 'HTML');
    };
    $bi_st = bkimp_state($from_id);
    switch ($bi_m[1]) {
        case 'start':
            if (bkimp_busy()) {
                $bi_alert($bi_t['busy']);
                break;
            }
            if (!bkimp_watcher_ready()) {
                Editmessagetext($from_id, $message_id, $bi_t['noWatcher'], json_encode(['inline_keyboard' => [[['text' => $bi_t['backBtn'], 'callback_data' => 'bkimp_hub', 'style' => 'primary']]]]), 'HTML');
                break;
            }
            bkimp_reset($from_id);
            $bi_st = bkimp_state($from_id, ['items' => [], 'msg' => (int) $message_id]);
            [$bi_text, $bi_kb] = bkimp_screen($bi_st);
            Editmessagetext($from_id, $message_id, $bi_text, $bi_kb, 'HTML');
            step('bkimp_wait', $from_id);
            break;
        case 'hub':
            $bi_hub();
            break;
        case 'cancel':
            bkimp_reset($from_id);
            step('home', $from_id);
            $bi_hub($bi_t['cancelled']);
            break;
        case 'pick':
            [$bi_text, $bi_kb] = bkimp_screen(bkimp_pick($from_id, $bi_m[2], $bi_m[3]));
            Editmessagetext($from_id, $message_id, $bi_text, $bi_kb, 'HTML');
            break;
        case 'back':
            [$bi_text, $bi_kb] = bkimp_screen($bi_st);
            Editmessagetext($from_id, $message_id, $bi_text, $bi_kb, 'HTML');
            break;
        case 'go':
        case 'yes':
            if (!bkimp_ready($bi_st)) {
                $bi_alert($bi_t['expired']);
                bkimp_reset($from_id);
                step('home', $from_id);
                $bi_hub();
                break;
            }
            if ($bi_m[1] === 'go') {
                [$bi_text, $bi_kb] = bkimp_confirm_screen($bi_st);
                Editmessagetext($from_id, $message_id, $bi_text, $bi_kb, 'HTML');
                break;
            }
            if (bkimp_busy()) {
                $bi_alert($bi_t['busy']);
                break;
            }
            if (!bkimp_watcher_ready()) {
                Editmessagetext($from_id, $message_id, $bi_t['noWatcher'], json_encode(['inline_keyboard' => [[['text' => $bi_t['backBtn'], 'callback_data' => 'bkimp_back', 'style' => 'primary']]]]), 'HTML');
                break;
            }
            Editmessagetext($from_id, $message_id, bkimp_queued_text(), json_encode(['inline_keyboard' => []]), 'HTML');
            if (!bkimp_request($bi_st, $from_id, $message_id)) {
                [$bi_text, $bi_kb] = bkimp_screen($bi_st, $bi_t['failPlain']);
                Editmessagetext($from_id, $message_id, $bi_text, $bi_kb, 'HTML');
                break;
            }
