            $rbn_note = strtr($rbn_bundle ? $rbn_t['addDone'] : $rbn_t['addNoBundle'], ['{name}' => htmlspecialchars((string) $rbn_node['name']), '{port}' => (int) $rbn_d['d']['port'], '{api}' => (int) $rbn_d['d']['api_port']]);
            // a fresh message under the bundle, so the steps read in order
            [$rbn_text, $rbn_kb] = rbn_node_screen($rbn_panel, (int) ($rbn_node['id'] ?? 0), $rbn_note);
            sendmessage($from_id, $rbn_text, $rbn_kb, 'HTML');
            break;
        case 'ed':
            [$rbn_node] = rbn_node($rbn_panel, $rbn_id);
            $rbn_show($rbn_node === null ? rbn_node_screen($rbn_panel, $rbn_id) : rbn_edit_screen($rbn_panel, $rbn_node));
            break;
        case 'ef':
            [$rbn_node] = rbn_node($rbn_panel, $rbn_id);
            if ($rbn_node === null || !isset($rbn_t['field'][$rbn_arg])) {
                $rbn_show(rbn_node_screen($rbn_panel, $rbn_id));
                break;
            }
            savedata("clear", "rbn", ['p' => $rbn_p, 'n' => $rbn_id, 'f' => $rbn_arg]);
            step('rbn_edit', $from_id);
            $rbn_show([strtr($rbn_t['editAsk'], ['{field}' => $rbn_t['field'][$rbn_arg], '{now}' => htmlspecialchars(rbn_field_now($rbn_node, $rbn_arg))]), rbn_kb([[rbn_btn($rbn_t['btnCancel'], "rbn|ed|{$rbn_p}|{$rbn_id}", 'danger')]])]);
            break;
    }
    return;
}
// ...an Xray version typed in for a node: it has to exist before anyone is asked to install it
if ($user['step'] === 'rbn_core' && $datain === '' && $adminrulecheck['rule'] == "administrator"
    && !in_array($text, [$textbotlang['Admin']['backAdminBtn'], $textbotlang['Admin']['backMenuBtn']], true)) {
    $rbn_t = $textbotlang['Admin']['RbNodes'];
    $rbn_d = (json_decode((string) $user['Processing_value'], true) ?: [])['rbn'] ?? null;
    $rbn_panel = is_array($rbn_d) ? rbn_panel($rbn_d['p'] ?? 0) : null;
    $rbn_id = is_array($rbn_d) ? (int) ($rbn_d['n'] ?? 0) : 0;
    if ($rbn_panel === null || $rbn_id <= 0) {
        step('home', $from_id);
        sendmessage($from_id, $rbn_t['stale'], null, 'HTML');
        return;
    }
    $rbn_p = (int) $rbn_panel['id'];
    $rbn_cancel = rbn_kb([[rbn_btn($rbn_t['btnCancel'], "rbn|core|{$rbn_p}|{$rbn_id}", 'danger')]]);
    $rbn_tag = rbn_xray_tag($text);
    if ($rbn_tag === null) {
        sendmessage($from_id, $rbn_t['coreCustomBad'], $rbn_cancel, 'HTML');
        return;
    }
    // the check asks the panel and GitHub, which takes a moment: say so, then answer in the same message
    $rbn_wait = sendmessage($from_id, strtr($rbn_t['coreCustomChecking'], ['{ver}' => htmlspecialchars($rbn_tag)]), null, 'HTML');
    $rbn_mid = (int) ($rbn_wait['result']['message_id'] ?? 0);
    $rbn_reply = function ($rbn_msg, $rbn_markup) use ($from_id, $rbn_mid) {
        if ($rbn_mid > 0) {
            Editmessagetext($from_id, $rbn_mid, $rbn_msg, $rbn_markup, 'HTML');
        } else {
            sendmessage($from_id, $rbn_msg, $rbn_markup, 'HTML');
        }
    };
    [$rbn_state, $rbn_why, $rbn_recent] = rbn_xray_version_check($rbn_panel, $rbn_tag);
    if ($rbn_state === 'no') {
        $rbn_list = $rbn_recent ? implode(' · ', array_map(fn($v) => '<code>' . htmlspecialchars($v) . '</code>', $rbn_recent)) : '—';
        $rbn_reply(strtr($rbn_t['coreCustomNo'], ['{ver}' => htmlspecialchars($rbn_tag), '{recent}' => $rbn_list]), $rbn_cancel);
        return;
    }
    if ($rbn_state !== 'yes') {
        $rbn_reply(strtr($rbn_t['coreCustomUnknown'], ['{ver}' => htmlspecialchars($rbn_tag), '{why}' => $rbn_why]), $rbn_cancel);
        return;
    }
    // it exists: asked once
    step('home', $from_id);
    [$rbn_node] = rbn_node($rbn_panel, $rbn_id);
    $rbn_cur = is_array($rbn_node) ? (string) ($rbn_node['xray_version'] ?? '') : '';
    $rbn_same = $rbn_cur !== '' && ltrim($rbn_cur, 'vV') === ltrim($rbn_tag, 'v');
    [$rbn_text, $rbn_kb] = rbn_core_ask_screen($rbn_panel, $rbn_id, $rbn_tag, is_array($rbn_node) ? (string) $rbn_node['name'] : '',
        strtr($rbn_t[$rbn_same ? 'coreCustomSame' : 'coreCustomFound'], ['{ver}' => htmlspecialchars($rbn_tag), '{xray}' => htmlspecialchars($rbn_cur !== '' ? $rbn_cur : '—')]));
    $rbn_reply($rbn_text, $rbn_kb);
    return;
}
// ...a 🔁 reminder gap or count typed in
if ($user['step'] === 'rbn_repeat' && $datain === '' && $adminrulecheck['rule'] == "administrator"
    && !in_array($text, [$textbotlang['Admin']['backAdminBtn'], $textbotlang['Admin']['backMenuBtn']], true)) {
    $rbn_t = $textbotlang['Admin']['RbNodes'];
    $rbn_d = (json_decode((string) $user['Processing_value'], true) ?: [])['rbn'] ?? null;
    $rbn_panel = is_array($rbn_d) ? rbn_panel($rbn_d['p'] ?? 0) : null;
    if ($rbn_panel === null || !preg_match('/^(down|load)-(e|n)$/', (string) ($rbn_d['f'] ?? ''), $rbn_rk)) {
        step('home', $from_id);
        sendmessage($from_id, $rbn_t['stale'], null, 'HTML');
        return;
    }
    $rbn_v = rbn_rep_value($rbn_rk[2], $text);
    if ($rbn_v === null) {
        sendmessage($from_id, $rbn_t[$rbn_rk[2] === 'e' ? 'repBadEvery' : 'repBadMax'], rbn_kb([[rbn_btn($rbn_t['btnCancel'], "rbn|rp|" . (int) $rbn_panel['id'] . "|0|{$rbn_rk[1]}", 'danger')]]), 'HTML');
        return;
    }
    step('home', $from_id);
    rbn_rep_set($rbn_rk[1], $rbn_rk[2] === 'e' ? 'every' : 'max', $rbn_v);
    [$rbn_text, $rbn_kb] = rbn_repeat_screen($rbn_panel, $rbn_rk[1], strtr($rbn_t[$rbn_rk[2] === 'e' ? 'repSavedEvery' : 'repSavedMax'], ['{v}' => $rbn_rk[2] === 'e' ? $rbn_v : rbn_rep_max_label($rbn_v)]));
    sendmessage($from_id, $rbn_text, $rbn_kb, 'HTML');
    return;
}
// ...a 🚨 limit typed in (1-100)
if ($user['step'] === 'rbn_load' && $datain === '' && $adminrulecheck['rule'] == "administrator"
    && !in_array($text, [$textbotlang['Admin']['backAdminBtn'], $textbotlang['Admin']['backMenuBtn']], true)) {
    $rbn_t = $textbotlang['Admin']['RbNodes'];
    $rbn_d = (json_decode((string) $user['Processing_value'], true) ?: [])['rbn'] ?? null;
    $rbn_panel = is_array($rbn_d) ? rbn_panel($rbn_d['p'] ?? 0) : null;
    $rbn_f = is_array($rbn_d) ? (string) ($rbn_d['f'] ?? '') : '';
    if ($rbn_panel === null || !in_array($rbn_f, ['cpu', 'ram'], true)) {
        step('home', $from_id);
        sendmessage($from_id, $rbn_t['stale'], null, 'HTML');
        return;
    }
    $rbn_v = rbn_load_value($text);
    if ($rbn_v === null) {
        sendmessage($from_id, $rbn_t['loadBad'], rbn_kb([[rbn_btn($rbn_t['btnCancel'], "rbn|ld|" . (int) $rbn_panel['id'], 'danger')]]), 'HTML');
        return;
    }
    step('home', $from_id);
    rbn_load_limit_set($rbn_f, $rbn_v);
    [$rbn_text, $rbn_kb] = rbn_load_screen($rbn_panel, strtr($rbn_t['loadSaved'], ['{what}' => $rbn_t['load' . strtoupper($rbn_f)], '{v}' => $rbn_v]));
    sendmessage($from_id, $rbn_text, $rbn_kb, 'HTML');
    return;
}
// ...the channel or group a panel's reports go to, typed in
if ($user['step'] === 'rbn_dest' && $datain === '' && $adminrulecheck['rule'] == "administrator"
    && !in_array($text, [$textbotlang['Admin']['backAdminBtn'], $textbotlang['Admin']['backMenuBtn']], true)) {
    $rbn_t = $textbotlang['Admin']['RbNodes'];
    $rbn_d = (json_decode((string) $user['Processing_value'], true) ?: [])['rbn'] ?? null;
    $rbn_panel = is_array($rbn_d) ? rbn_panel($rbn_d['p'] ?? 0) : null;
    if ($rbn_panel === null) {
        step('home', $from_id);
        sendmessage($from_id, $rbn_t['stale'], null, 'HTML');
        return;
    }
    $rbn_p = (int) $rbn_panel['id'];
    $rbn_cancel = rbn_kb([[rbn_btn($rbn_t['btnCancel'], "rbn|dst|{$rbn_p}", 'danger')]]);
    $rbn_chat = rbn_chat_value($text);
    if ($rbn_chat === null) {
        sendmessage($from_id, $rbn_t['destChatBad'], $rbn_cancel, 'HTML');
        return;
    }
    [$rbn_id, $rbn_why] = rbn_chat_try($rbn_panel, $rbn_chat);
    if ($rbn_id === null) {
        sendmessage($from_id, strtr($rbn_t['destChatFail'], ['{why}' => htmlspecialchars($rbn_why)]), $rbn_cancel, 'HTML');
        return;
    }
    step('home', $from_id);
    rbn_dest_set($rbn_panel, 'chat:' . $rbn_id);
    [$rbn_text, $rbn_kb] = rbn_hub_screen($rbn_panel, strtr($rbn_t['destSaved'], ['{dest}' => htmlspecialchars(rbn_dest_label('chat:' . $rbn_id))]));
    sendmessage($from_id, $rbn_text, $rbn_kb, 'HTML');
    return;
}
// ...and the values typed for a new node, or for a field of one
if (in_array($user['step'], ['rbn_add', 'rbn_edit'], true) && $datain === '' && $adminrulecheck['rule'] == "administrator"
    && !in_array($text, [$textbotlang['Admin']['backAdminBtn'], $textbotlang['Admin']['backMenuBtn']], true)) {
    $rbn_t = $textbotlang['Admin']['RbNodes'];
    $rbn_d = (json_decode((string) $user['Processing_value'], true) ?: [])['rbn'] ?? null;
    $rbn_panel = is_array($rbn_d) ? rbn_panel($rbn_d['p'] ?? 0) : null;
    if ($rbn_panel === null) {
        step('home', $from_id);
        sendmessage($from_id, $rbn_t['stale'], null, 'HTML');
        return;
    }
    $rbn_p = (int) $rbn_panel['id'];
    $rbn_f = (string) ($rbn_d['f'] ?? '');
    if ($user['step'] === 'rbn_edit') {
        $rbn_id = (int) ($rbn_d['n'] ?? 0);
        $rbn_v = rbn_field_value($rbn_f, $text);
        if ($rbn_v === null) {
            sendmessage($from_id, $rbn_t['addBad'], rbn_kb([[rbn_btn($rbn_t['btnCancel'], "rbn|ed|{$rbn_p}|{$rbn_id}", 'danger')]]), 'HTML');
            return;
        }
        step('home', $from_id);
        [$rbn_ok, $rbn_why] = rbn_edit($rbn_panel, $rbn_id, $rbn_f, $rbn_v);
        $rbn_label = $rbn_t['act']['ed'] . ' — ' . ($rbn_t['field'][$rbn_f] ?? $rbn_f);
        [$rbn_text, $rbn_kb] = rbn_node_screen($rbn_panel, $rbn_id, $rbn_ok ? strtr($rbn_t['done'], ['{action}' => $rbn_label]) : strtr($rbn_t['failed'], ['{action}' => $rbn_label, '{why}' => $rbn_why]));
        sendmessage($from_id, $rbn_text, $rbn_kb, 'HTML');
        return;
    }
    // ➕ name → address → port → API port → coefficient, «-» keeping a default
    $rbn_cancel = rbn_kb([[rbn_btn($rbn_t['btnCancel'], "rbn|hub|{$rbn_p}", 'danger')]]);
    $rbn_defaults = ['port' => 62050, 'api_port' => 62051, 'coef' => 1];
    $rbn_raw = trim((string) $text);
    $rbn_v = ($rbn_raw === '-' && isset($rbn_defaults[$rbn_f])) ? $rbn_defaults[$rbn_f] : rbn_field_value($rbn_f, $rbn_raw);
    if ($rbn_v === null) {
        sendmessage($from_id, $rbn_t['addBad'], $rbn_cancel, 'HTML');
        return;
    }
    if ($rbn_f === 'api_port' && (int) $rbn_v === (int) ($rbn_d['d']['port'] ?? 0)) {
        sendmessage($from_id, $rbn_t['addSamePorts'], $rbn_cancel, 'HTML');
        return;
    }
    $rbn_d['d'][$rbn_f] = $rbn_v;
    $rbn_order = ['name', 'address', 'port', 'api_port', 'coef'];
    $rbn_next = $rbn_order[array_search($rbn_f, $rbn_order, true) + 1] ?? 'ready';
    $rbn_d['f'] = $rbn_next;
    savedata("clear", "rbn", $rbn_d);
    if ($rbn_next === 'ready') {
        step('home', $from_id);
        [$rbn_text, $rbn_kb] = rbn_add_summary($rbn_panel, $rbn_d['d']);
        sendmessage($from_id, $rbn_text, $rbn_kb, 'HTML');
        return;
    }
    sendmessage($from_id, $rbn_t['addAsk'][$rbn_next], $rbn_cancel, 'HTML');
    return;
}
//----------------[  👤 🧹 پاکسازی و ریست  ]----------------
// balances to zero (with a way back), every زیرمجموعه to zero, and the services
// the bot sold taken out of their panels (a run that goes on in the
// background, then reports). Each change asks once more, and the removal asks
// for a word. Only an administrator; the same tools are in the web panel.
if (preg_match('/^cln\|(menu|bal|ref|svc|undo|job)\|(all|[a-z]{2})(?:\|(go|ask|stop|retry))?$/', $datain, $cln_m) && $adminrulecheck['rule'] == "administrator") {
    $cln_t = $textbotlang['Admin']['CleanTools'];
    $cln_scope = clean_scope_from_code($cln_m[2]);
    $cln_code = clean_scope_code($cln_scope);
    $cln_act = $cln_m[3] ?? '';
    $cln_show = function ($screen) use ($from_id, $message_id) {
        Editmessagetext($from_id, $message_id, $screen[0], $screen[1], 'HTML');
    };
    $cln_done = fn($text, $back = null) => Editmessagetext($from_id, $message_id, $text, clean_kb($back ?? clean_back_rows($cln_code, $cln_t)), 'HTML');
    if ($user['step'] === 'cln_svc_word') {
        step('home', $from_id);
    }
    if ($cln_m[1] === 'menu') {
        $cln_show(clean_menu_screen($cln_scope, $textbotlang));
    } elseif ($cln_m[1] === 'bal') {
        if ($cln_act === 'go') {
            [$cln_n] = clean_balance_zero($cln_scope, 'bot:' . $from_id);
            $cln_done($cln_n > 0 ? strtr($cln_t['balDone'], ['{n}' => number_format($cln_n)]) : $cln_t['balNone']);
        } else {
            $cln_show(clean_balance_screen($cln_scope, $textbotlang));
        }
    } elseif ($cln_m[1] === 'undo') {
        if ($cln_act === 'go') {
            [$cln_n] = clean_balance_undo();
            $cln_done($cln_n > 0 ? strtr($cln_t['undoDone'], ['{n}' => number_format($cln_n)]) : $cln_t['undoNone']);
        } else {
            $cln_show(clean_undo_screen($textbotlang));
        }
    } elseif ($cln_m[1] === 'ref') {
        if ($cln_act === 'go') {
            $cln_n = clean_ref_reset($cln_scope);
            $cln_done(strtr($cln_t['refDone'], ['{n}' => number_format($cln_n)]));
        } else {
            $cln_show(clean_ref_screen($cln_scope, $textbotlang));
        }
    } elseif ($cln_m[1] === 'svc') {
        if ($cln_act === 'ask') {
            // the word comes next, as a message
            $cln_p = clean_svc_preview($cln_scope);
            if (clean_job_active() !== null || $cln_p['services'] === 0) {
                $cln_show(clean_svc_screen($cln_scope, $textbotlang));
            } else {
                savedata("clear", "cln_scope", $cln_code);
                step('cln_svc_word', $from_id);
                $cln_done(strtr($cln_t['svcWord'], ['{n}' => number_format($cln_p['services'])]), [[['text' => $cln_t['cancelBtn'], 'callback_data' => "cln|menu|{$cln_code}", 'style' => 'primary']]]);
            }
        } else {
            $cln_show(clean_svc_screen($cln_scope, $textbotlang));
        }
    } elseif ($cln_m[1] === 'job') {
        if ($cln_act === 'stop') {
            clean_svc_stop();
            $cln_job = clean_job_current();
            if ($cln_job !== null) {
                clean_job_notify((int) $cln_job['id']);
            }
        } elseif ($cln_act === 'retry') {
            if (clean_svc_retry() > 0) {
                bulkgift_kick();
            }
        }
        $cln_show(clean_job_screen($cln_scope, $textbotlang));
    }
    return;
}
// ...and the word that confirms the removal of the bot's services
if ($user['step'] === 'cln_svc_word' && $datain === '' && $adminrulecheck['rule'] == "administrator"
    && !in_array($text, [$textbotlang['Admin']['backAdminBtn'], $textbotlang['Admin']['backMenuBtn']], true)) {
    $cln_t = $textbotlang['Admin']['CleanTools'];
    $cln_d = json_decode((string) $user['Processing_value'], true) ?: [];
    $cln_code = in_array(($cln_d['cln_scope'] ?? ''), array_merge(['all'], panel_langs()), true) ? $cln_d['cln_scope'] : 'all';
    $cln_scope = clean_scope_from_code($cln_code);
    if (!clean_word_ok($text)) {
        sendmessage($from_id, $cln_t['svcWordBad'], clean_kb([[['text' => $cln_t['cancelBtn'], 'callback_data' => "cln|menu|{$cln_code}", 'style' => 'primary']]]), 'HTML');
        return;
    }
    step('home', $from_id);
    [$cln_job, $cln_why] = clean_svc_start($cln_scope, 'bot:' . $from_id, (string) $from_id);
    if ($cln_job > 0) {
        bulkgift_kick();
        $cln_run = clean_job_current();
        sendmessage($from_id, strtr($cln_t['svcStarted'], ['{n}' => number_format((int) ($cln_run['total'] ?? 0))]), clean_kb([[['text' => $cln_t['jobBtn'], 'callback_data' => "cln|job|{$cln_code}", 'style' => 'primary']], ...clean_back_rows($cln_code, $cln_t)]), 'HTML');
    } else {
        sendmessage($from_id, $cln_why === 'busy' ? $cln_t['svcBusy'] : $cln_t['svcNone'], clean_kb(clean_back_rows($cln_code, $cln_t)), 'HTML');
    }
    return;
}
//----------------[  👤 🔗 واگذاری سرویس پنل به کاربر  ]----------------
// panel -> the account's username (checked on the panel) -> who gets it: one
// customer, several, or every customer of this 👤 tab -> confirm. An account
// can be shared: those who already have it keep it, the new ones join them.
// Each step checks again, so nothing stale is ever handed over.
if (preg_match('/^svcgive\|(start|p|all|ok|no)(?:\|(\d+))?$/', $datain, $sg_m) && $adminrulecheck['rule'] == "administrator") {
    $sg_t = $textbotlang['Admin']['UserMgmt'];
    $sg_back = json_encode(['inline_keyboard' => [[['text' => $sg_t['assignBackBtn'], 'callback_data' => 'backlistuser', 'style' => 'danger']]]]);
    $sg_yesno = json_encode(['inline_keyboard' => [[
        ['text' => $sg_t['assignYes'], 'callback_data' => 'svcgive|ok', 'style' => 'success'],
        ['text' => $sg_t['assignCancel'], 'callback_data' => 'svcgive|no', 'style' => 'danger'],
    ]]]);
    if ($sg_m[1] === 'start') {
        step('home', $from_id);
        Editmessagetext($from_id, $message_id, $sg_t['assignPickPanel'], svcgive_panels_payload($textbotlang), 'HTML');
        return;
    }
    if ($sg_m[1] === 'no') {
        step('home', $from_id);
        Editmessagetext($from_id, $message_id, $sg_t['assignCancelled'], $sg_back, 'HTML');
        return;
    }
    if ($sg_m[1] === 'p') {
        $sg_panel = select("marzban_panel", "*", "id", (int) ($sg_m[2] ?? 0), "select");
        if (!is_array($sg_panel)) {
            return;
        }
        savedata("clear", "sg_panel", (int) $sg_panel['id']);
        step('svcgive_user', $from_id);
        Editmessagetext($from_id, $message_id, strtr($sg_t['assignAskUsername'], ['{panel}' => htmlspecialchars((string) $sg_panel['name_panel'])]), json_encode(['inline_keyboard' => [[['text' => $sg_t['assignCancel'], 'callback_data' => 'svcgive|no', 'style' => 'danger']]]]), 'HTML');
        return;
    }
    $sg_d = json_decode((string) $user['Processing_value'], true) ?: [];
    $sg_panel = select("marzban_panel", "*", "id", (int) ($sg_d['sg_panel'] ?? 0), "select");
    if ($sg_m[1] === 'all') {
        // 👥 every customer of this 👤 tab
        if ($user['step'] !== 'svcgive_to' || !is_array($sg_panel) || !isset($sg_d['sg_user'])) {
            telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => $sg_t['assignStale'], 'show_alert' => true]);
            return;
        }
        $sg_lang = um_tab($user);
        $sg_owners = svcgive_owners($sg_panel['name_panel'], $sg_d['sg_user']);
        $sg_n = count(array_diff(svcgive_tab_user_ids($sg_lang), $sg_owners));
        savedata("save", "sg_to", 'all');
        savedata("save", "sg_lang", $sg_lang);
        $sg_d['sg_to'] = 'all';
        $sg_d['sg_lang'] = $sg_lang;
        step('svcgive_confirm', $from_id);
        Editmessagetext($from_id, $message_id, svcgive_confirm_text($sg_d, $sg_panel, $sg_n, count($sg_owners), $textbotlang), $sg_yesno, 'HTML');
        return;
    }
    // ✅: everything checked once more, then handed over
    $sg_acc = (is_array($sg_panel) && isset($sg_d['sg_user'])) ? svcgive_account($sg_panel, $sg_d['sg_user']) : null;
    step('home', $from_id);
    if ($user['step'] !== 'svcgive_confirm' || $sg_acc === null || empty($sg_d['sg_to'])) {
        telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => $sg_t['assignStale'], 'show_alert' => true]);
        return;
    }
    $sg_owners = svcgive_owners($sg_panel['name_panel'], $sg_acc['username']);
    $sg_all = $sg_d['sg_to'] === 'all';
    $sg_targets = [];
    if ($sg_all) {
        foreach (array_diff(svcgive_tab_user_ids($sg_d['sg_lang'] ?? 'fa'), $sg_owners) as $sg_id) {
            $sg_targets[$sg_id] = $sg_d['sg_lang'] ?? 'fa';
        }
    } else {
        foreach (array_diff(array_map('strval', (array) $sg_d['sg_to']), $sg_owners) as $sg_id) {
            $sg_row = select("user", "*", "id", $sg_id, "select");
            if (is_array($sg_row)) {
                $sg_targets[$sg_id] = $sg_row['lang'] ?? 'fa';
            }
        }
    }
    if (empty($sg_targets)) {
        Editmessagetext($from_id, $message_id, $sg_t['assignAllHave'], $sg_back, 'HTML');
        return;
    }
    $sg_count = svcgive_assign_many($sg_panel, $sg_acc, $sg_targets);
    $sg_uname = htmlspecialchars($sg_acc['username']);
    if (!$sg_all) {
        // a few, typed in by hand: told now, each in their own language
        foreach ($sg_targets as $sg_id => $sg_lang) {
            bottext_extras_key_hint('users.status.assignedNotice');
            sendmessage($sg_id, strtr(lang_tab_texts($sg_lang)['users']['status']['assignedNotice'], ['{username}' => $sg_uname]), null, 'HTML');
        }
        $sg_note = $sg_t['assignNoteSent'];
    } else {
        // a whole tab: through the 👤 broadcast queue, twenty a run - unless
        // a broadcast is already going out, which it must not overwrite
        $sg_busy = is_file('cronbot/users.json') && count((array) json_decode((string) file_get_contents('cronbot/users.json'), true)) > 0;
        if ($sg_busy) {
            $sg_note = $sg_t['assignNoteBusy'];
        } else {
            $sg_progress = sendmessage($from_id, $sg_t['assignQueueStarted'], json_encode(['inline_keyboard' => [[['text' => $textbotlang['keyboard']['cancelOperation'], 'callback_data' => 'cancel_sendmessage', 'style' => 'danger']]]]), 'HTML');
            file_put_contents('cronbot/users.json', json_encode(array_map(fn($i) => ['id' => (string) $i], array_keys($sg_targets))));
            file_put_contents('cronbot/info', json_encode([
                'id_admin' => $from_id,
                'type' => 'sendmessage',
                'id_message' => $sg_progress['result']['message_id'] ?? 0,
                'message' => strtr(lang_tab_texts($sg_d['sg_lang'] ?? 'fa')['users']['status']['assignedNotice'], ['{username}' => $sg_uname]),
                'pingmessage' => 'no',
                'btnmessage' => 'none',
                'lang' => $sg_d['sg_lang'] ?? 'fa',
                'hint' => 'users.status.assignedNotice',
            ]));
            $sg_note = $sg_t['assignNoteQueued'];
        }
    }
    Editmessagetext($from_id, $message_id, strtr($sg_t['assignDone'], ['{username}' => $sg_uname, '{n}' => $sg_count]) . $sg_note, $sg_back, 'HTML');
    return;
}
if (in_array($user['step'], ['svcgive_user', 'svcgive_to'], true) && $datain === '' && $adminrulecheck['rule'] == "administrator"
    && !in_array($text, [$textbotlang['Admin']['backAdminBtn'], $textbotlang['Admin']['backMenuBtn']], true)) {
    $sg_t = $textbotlang['Admin']['UserMgmt'];
    $sg_cancel = json_encode(['inline_keyboard' => [[['text' => $sg_t['assignCancel'], 'callback_data' => 'svcgive|no', 'style' => 'danger']]]]);
    $sg_d = json_decode((string) $user['Processing_value'], true) ?: [];
    $sg_panel = select("marzban_panel", "*", "id", (int) ($sg_d['sg_panel'] ?? 0), "select");
    if (!is_array($sg_panel)) {
        step('home', $from_id);
        return;
    }
    if ($user['step'] === 'svcgive_user') {
        // the account, on the panel picked
        $sg_name = trim((string) $text);
        $sg_acc = $sg_name !== '' ? svcgive_account($sg_panel, $sg_name) : null;
        if ($sg_acc === null) {
            sendmessage($from_id, strtr($sg_t['assignNotFound'], ['{username}' => htmlspecialchars($sg_name), '{panel}' => htmlspecialchars((string) $sg_panel['name_panel'])]), $sg_cancel, 'HTML');
            return;
        }
        $sg_owners = svcgive_owners($sg_panel['name_panel'], $sg_acc['username']);
        savedata("save", "sg_user", $sg_acc['username']);
        step('svcgive_to', $from_id);
        $sg_lang = um_tab($user);
        sendmessage($from_id, strtr($sg_t['assignAskUser'], [
            '{username}' => htmlspecialchars($sg_acc['username']),
            '{panel}' => htmlspecialchars((string) $sg_panel['name_panel']),
            '{account}' => svcgive_account_text($sg_acc, $textbotlang),
            '{owned}' => $sg_owners ? strtr($sg_t['assignOwnedNote'], ['{n}' => count($sg_owners)]) : '',
            '{lang}' => um_lang_name($sg_lang, $textbotlang),
        ]), json_encode(['inline_keyboard' => [
            [['text' => strtr($sg_t['assignAllBtn'], ['{lang}' => um_lang_name($sg_lang, $textbotlang)]), 'callback_data' => 'svcgive|all', 'style' => 'primary']],
            [['text' => $sg_t['assignCancel'], 'callback_data' => 'svcgive|no', 'style' => 'danger']],
        ]]), 'HTML');
        return;
    }
    // who it goes to: one or more ids / @usernames
    [$sg_found, $sg_missing] = svcgive_find_users($text);
    if (empty($sg_found)) {
        sendmessage($from_id, strtr($sg_t['assignNoUser'], ['{id}' => htmlspecialchars(implode(' ', $sg_missing))]), $sg_cancel, 'HTML');
        return;
    }
    $sg_owners = svcgive_owners($sg_panel['name_panel'], (string) ($sg_d['sg_user'] ?? ''));
    $sg_new = array_values(array_diff(array_keys($sg_found), $sg_owners));
    if (empty($sg_new)) {
        sendmessage($from_id, $sg_t['assignAllHave'], $sg_cancel, 'HTML');
        return;
    }
    savedata("save", "sg_to", $sg_new);
    $sg_d['sg_to'] = $sg_new;
    step('svcgive_confirm', $from_id);
    $sg_missingNote = $sg_missing ? strtr($sg_t['assignMissing'], ['{list}' => htmlspecialchars(implode(' ', $sg_missing))]) : '';
    sendmessage($from_id, svcgive_confirm_text($sg_d, $sg_panel, count($sg_new), count($sg_owners), $textbotlang) . $sg_missingNote, json_encode(['inline_keyboard' => [[
        ['text' => $sg_t['assignYes'], 'callback_data' => 'svcgive|ok', 'style' => 'success'],
        ['text' => $sg_t['assignCancel'], 'callback_data' => 'svcgive|no', 'style' => 'danger'],
    ]]]), 'HTML');
    return;
}

//----------------[  🛡 راستی‌آزمایی دعوت‌ها  ]----------------
if (preg_match('/^flsrefv:([a-z]{2}):([cr]):(phone|channel|pick|vip|vipadd|ch:(\d+)|vipdel:(\d+))$/', $datain, $rv_m) && $adminrulecheck['rule'] == "administrator") {
    $rv_lang = $rv_m[1];
    $rv_plan = $rv_m[2];
    // $rv_m[2..] as they were before the plan was in the callback
    array_splice($rv_m, 2, 1);
    $rv_s = lang_tab_texts('fa')['Admin']['FeatureSection'];
    $rv = refv_cfg($rv_lang, $rv_plan);
    $rv_alert = function ($t) use ($callback_query_id) {
        telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => $t, 'show_alert' => true]);
    };
    $rv_hasChannels = (bool) select("channels", "*", null, null, "fetchAll");
    if ($rv_m[2] === 'phone') {
        // checked against 📞 احراز شماره تماس's own country codes - so it
        // has to be on for this language first
        if (!$rv['phone'] && feature_value('get_number', $rv_lang, $setting['get_number']) != "onAuthenticationphone") {
            $rv_alert($rv_s['refvPhoneNeeds']);
            return;
        }
        feature_setting_set("refv_{$rv_plan}_phone", $rv_lang, $rv['phone'] ? '0' : '1');
    } elseif ($rv_m[2] === 'channel') {
        if (!$rv['channel'] && !refv_channel_rows($rv)) {
            $rv_alert($rv_hasChannels ? $rv_s['refvChannelNeeds'] : $rv_s['refvNoChannels']);
            return;
        }
        feature_setting_set("refv_{$rv_plan}_channel", $rv_lang, $rv['channel'] ? '0' : '1');
    } elseif ($rv_m[2] === 'pick' || strpos($rv_m[2], 'ch:') === 0) {
        if (!$rv_hasChannels) {
            $rv_alert($rv_s['refvNoChannels']);
            return;
        }
        if (strpos($rv_m[2], 'ch:') === 0) {
            $rv_id = (int) $rv_m[3];
            $rv_list = in_array($rv_id, $rv['channels'], true) ? array_diff($rv['channels'], [$rv_id]) : array_merge($rv['channels'], [$rv_id]);
            feature_setting_set("refv_{$rv_plan}_channels", $rv_lang, implode(',', $rv_list));
            if (empty($rv_list)) {
                // nothing to join is no channel check at all
                feature_setting_set("refv_{$rv_plan}_channel", $rv_lang, '0');
            }
        }
        [$rv_cap, $rv_kb] = refv_pick_payload($rv_lang, $rv_plan, $textbotlang);
        Editmessagetext($from_id, $message_id, $rv_cap, $rv_kb);
        return;
    } elseif ($rv_m[2] === 'vipadd') {
        savedata("clear", "rv_lang", $rv_lang);
        savedata("save", "rv_plan", $rv_plan);
        step('refvvip', $from_id);
        Editmessagetext($from_id, $message_id, $rv_s['ask_refv_vip'], json_encode(['inline_keyboard' => [[['text' => $rv_s['cancel'], 'callback_data' => "flsrefv:{$rv_lang}:{$rv_plan}:vip", 'style' => 'danger']]]]));
        return;
    } elseif ($rv_m[2] === 'vip' || strpos($rv_m[2], 'vipdel:') === 0) {
        step('home', $from_id);
        if (strpos($rv_m[2], 'vipdel:') === 0) {
            feature_setting_set("refv_{$rv_plan}_vip", $rv_lang, implode(',', array_diff($rv['vip'], [(string) $rv_m[4]])));
        }
        [$rv_cap, $rv_kb] = refv_vip_payload($rv_lang, $rv_plan, $textbotlang);
        Editmessagetext($from_id, $message_id, $rv_cap, $rv_kb);
        return;
    }
    Editmessagetext($from_id, $message_id, feature_section_caption($textbotlang, $rv_lang, "refv{$rv_plan}"), feature_section_payload($textbotlang, $rv_lang, "refv{$rv_plan}"));
    return;
}
if ($user['step'] === 'refvvip' && $datain === '' && $adminrulecheck['rule'] == "administrator"
    && !in_array($text, [$textbotlang['Admin']['backAdminBtn'], $textbotlang['Admin']['backMenuBtn']], true)) {
    $rv_pv = json_decode((string) $user['Processing_value'], true);
    $rv_lang = $rv_pv['rv_lang'] ?? 'fa';
    $rv_plan = ($rv_pv['rv_plan'] ?? 'c') === 'r' ? 'r' : 'c';
    $rv_u = svcgive_find_user($text);
    if ($rv_u === null) {
        sendmessage($from_id, strtr($textbotlang['Admin']['UserMgmt']['assignNoUser'], ['{id}' => htmlspecialchars(trim((string) $text))]), null, 'HTML');
        return;
    }
    feature_setting_set("refv_{$rv_plan}_vip", $rv_lang, implode(',', array_unique(array_merge(refv_cfg($rv_lang, $rv_plan)['vip'], [(string) $rv_u['id']]))));
    step('home', $from_id);
    [$rv_cap, $rv_kb] = refv_vip_payload($rv_lang, $rv_plan, $textbotlang);
    sendmessage($from_id, $rv_cap, $rv_kb, 'HTML');
    return;
}
// 📯 🎯 who has to join each channel for the bot to work
if (preg_match('/^chngate:([a-z]{2})(?::(\d+))?$/', $datain, $cg_m) && $adminrulecheck['rule'] == "administrator") {
    $cg_lang = $cg_m[1];
    if (isset($cg_m[2])) {
        $cg_map = channel_gate_map($cg_lang);
        $cg_next = ['all' => 'new', 'new' => 'invited', 'invited' => 'none', 'none' => 'all'][channel_gate_aud($cg_lang, $cg_m[2])] ?? 'all';
        // «new» means from now on
        $cg_map[(string) $cg_m[2]] = ['aud' => $cg_next, 'since' => $cg_next === 'new' ? time() : 0];
        feature_setting_set('chn_gate', $cg_lang, json_encode($cg_map));
    }
    [$cg_cap, $cg_kb] = chngate_payload($cg_lang, $textbotlang);
    Editmessagetext($from_id, $message_id, $cg_cap, $cg_kb);
    return;
}

//----------------[  🎁 کانفیگ رایگان با دعوت  ]----------------
// 🔄 from a customer's own screen: their free-config count back to zero
if (preg_match('/^affrwzero_(\d+)$/', $datain, $rz_m) && $adminrulecheck['rule'] == "administrator") {
    affrw_reset($rz_m[1]);
    telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => $textbotlang['Admin']['UserMgmt']['affrwResetDone'], 'show_alert' => true]);
    return;
}
// ⚙️ قوانین اکانت کانفیگ رایگان, one tab's
if (preg_match('/^affrwrule\|([a-z]{2})\|(open|del|hours|renew|uname)$/', $datain, $ar_m) && $adminrulecheck['rule'] == "administrator") {
    $ar_lang = $ar_m[1];
    if ($ar_m[2] === 'hours') {
        savedata("clear", "ar_lang", $ar_lang);
        step('affrwrulehours', $from_id);
        $ar_s = lang_tab_texts('fa')['Admin']['AffRules'];
        Editmessagetext($from_id, $message_id, $ar_s['askHours'], json_encode(['inline_keyboard' => [[['text' => $ar_s['cancel'], 'callback_data' => "affrwrule|{$ar_lang}|open", 'style' => 'danger']]]]));
        return;
    }
    if ($ar_m[2] === 'del') {
        // never -> as soon as it ends -> some hours after -> never
        feature_setting_set('affrw_del', $ar_lang, ['no' => 'end', 'end' => 'hours', 'hours' => 'no'][(string) feature_setting_value('affrw_del', $ar_lang, 'no')] ?? 'end');
    } elseif ($ar_m[2] === 'renew') {
        feature_setting_set('affrw_renew', $ar_lang, (string) feature_setting_value('affrw_renew', $ar_lang, '0') === '1' ? '0' : '1');
    } elseif ($ar_m[2] === 'uname') {
        feature_setting_set('affrw_uname', $ar_lang, ['ref' => 'random', 'random' => 'user', 'user' => 'ref'][(string) feature_setting_value('affrw_uname', $ar_lang, 'ref')] ?? 'random');
    } else {
        step('home', $from_id);
    }
    [$ar_cap, $ar_kb] = affrw_rules_payload($ar_lang);
    Editmessagetext($from_id, $message_id, $ar_cap, $ar_kb);
    return;
}
if ($user['step'] === 'affrwrulehours' && $datain === '' && $adminrulecheck['rule'] == "administrator"
    && !in_array($text, [$textbotlang['Admin']['backAdminBtn'], $textbotlang['Admin']['backMenuBtn']], true)) {
    $ar_lang = json_decode((string) $user['Processing_value'], true)['ar_lang'] ?? 'fa';
    $ar_h = trim((string) $text);
    if (!ctype_digit($ar_h) || (int) $ar_h < 1 || (int) $ar_h > 8760) {
        sendmessage($from_id, lang_tab_texts('fa')['Admin']['AffRules']['invalidHours'], null, 'HTML');
        return;
    }
    feature_setting_set('affrw_del_hours', $ar_lang, (string) (int) $ar_h);
    step('home', $from_id);
    [$ar_cap, $ar_kb] = affrw_rules_payload($ar_lang);
    sendmessage($from_id, $ar_cap, $ar_kb, 'HTML');
    return;
}
// 🧪 تست / 👁 پیش‌نمایش of a 👥 plan, in one tab's language
if (preg_match('/^afftest:([a-z]{2}):(c|r|r:view|r:real|r:go)$/', $datain, $at_m) && $adminrulecheck['rule'] == "administrator") {
    $at_lang = $at_m[1];
    $at_fa = lang_tab_texts('fa');
    $at_t = $at_fa['Admin']['AffTest'];
    if ($at_m[2] === 'r') {
        [$at_cap, $at_kb] = afftest_menu_payload($at_lang);
        Editmessagetext($from_id, $message_id, $at_cap, $at_kb);
        return;
    }
    if ($at_m[2] === 'r:real' || $at_m[2] === 'r:go') {
        $at_cfg = affrw_cfg($at_lang);
        $at_panel = affrw_panel($at_cfg);
        if ($at_panel === null) {
            telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => $at_fa['Admin']['FeatureSection']['affrwPanelFirst'], 'show_alert' => true]);
            return;
        }
        if ($at_m[2] === 'r:real') {
            Editmessagetext($from_id, $message_id, strtr($at_t['confirm'], ['{volume}' => volume_num($at_cfg['gb']), '{days}' => $at_cfg['days'], '{panel}' => htmlspecialchars($at_panel['name_panel'])]), json_encode(['inline_keyboard' => [
                [['text' => $at_t['confirmBtn'], 'callback_data' => "afftest:{$at_lang}:r:go", 'style' => 'success']],
                [['text' => $at_fa['Admin']['FeatureSection']['back'], 'callback_data' => "afftest:{$at_lang}:r"]],
            ]]));
            return;
        }
        // one config per tap: the confirm button is gone before it is made
        [$at_cap, $at_kb] = afftest_menu_payload($at_lang);
        Editmessagetext($from_id, $message_id, $at_cap, $at_kb);
    }
    telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => $at_t['sending']]);
    if ($at_m[2] === 'c') {
        afftest_classic($from_id, $at_lang);
    } else {
        afftest_reward($from_id, $at_lang, $at_m[2] === 'r:go');
    }
    return;
}
if (preg_match('/^flsaffrw:([a-z]{2}):(on|mode|panel|leave|p:(\d+))$/', $datain, $rw_m) && $adminrulecheck['rule'] == "administrator") {
    $rw_lang = $rw_m[1];
    $rw = affrw_cfg($rw_lang);
    if ($rw_m[2] === 'on') {
        if (!$rw['on'] && affrw_panel($rw) === null) {
            telegram('answerCallbackQuery', [
                'callback_query_id' => $callback_query_id,
                'text' => lang_tab_texts('fa')['Admin']['FeatureSection']['affrwPanelFirst'],
                'show_alert' => true,
            ]);
            return;
        }
        // switched on: only people who join from now count
        if (!$rw['on']) {
            feature_setting_set('affrw_since', $rw_lang, (string) time());
        }
        feature_setting_set('affrw_on', $rw_lang, $rw['on'] ? '0' : '1');
    } elseif ($rw_m[2] === 'mode') {
        feature_setting_set('affrw_mode', $rw_lang, $rw['mode'] === 'auto' ? 'admin' : 'auto');
    } elseif ($rw_m[2] === 'leave') {
        $rw_lv = feature_setting_value('affrw_leave', $rw_lang, '0') === '1';
        // it watches 🛡's channels - without them it could never see a leave
        $rw_rv = refv_cfg($rw_lang, 'r');
        if (!$rw_lv && (!$rw_rv['channel'] || !refv_channel_rows($rw_rv))) {
            telegram('answerCallbackQuery', [
                'callback_query_id' => $callback_query_id,
                'text' => lang_tab_texts('fa')['Admin']['FeatureSection']['affrwLeaveNeedsChannel'],
                'show_alert' => true,
            ]);
            return;
        }
        feature_setting_set('affrw_leave', $rw_lang, $rw_lv ? '0' : '1');
    } elseif ($rw_m[2] === 'panel') {
        [$rw_cap, $rw_kb] = affrw_panel_payload($rw_lang);
        Editmessagetext($from_id, $message_id, $rw_cap, $rw_kb);
        return;
    } else {
        $rw_p = select("marzban_panel", "*", "id", (int) $rw_m[3], "select");
        if (is_array($rw_p)) {
            feature_setting_set('affrw_panel', $rw_lang, (string) $rw_p['code_panel']);
        }
    }
    Editmessagetext($from_id, $message_id, feature_section_caption($textbotlang, $rw_lang, 'affr'), feature_section_payload($textbotlang, $rw_lang, 'affr'));
    return;
}
if (preg_match('/^affrw\|(ok|no)\|(\d+)$/', $datain, $rw_m)) {
    $rw_t = lang_tab_texts('fa')['Admin']['AffReward'];
    $rw_uid = $rw_m[2];
    // the request as it stands before this tap moves it on - afterwards its
    // count starts again, and the invitees and the time it was would be gone
    $rw_req = affrw_request_text($rw_uid);
    $rw_row = affrw_row($rw_uid);
    $rw_admin = aff_label($from_id, select("user", "*", "id", $from_id, "select"));
    if ($rw_m[1] === 'ok') {
        // one config however many admins tap: only the tap that moves the
        // request on makes it
        if (!affrw_move($rw_uid, 'pending', 'giving')) {
            telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => $rw_t['handled'], 'show_alert' => true]);
            return;
        }
        if (!affrw_give($rw_uid, null, "\n\n" . strtr($rw_t['reportApproved'], ['{admin}' => $rw_admin]))) {
            affrw_move($rw_uid, 'giving', 'pending');
            telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => $rw_t['failed'], 'show_alert' => true]);
            return;
        }
        Editmessagetext($from_id, $message_id, $rw_req . $rw_t['approved'], null);
    } else {
        if (!affrw_move($rw_uid, 'pending', 'rejected')) {
            telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => $rw_t['handled'], 'show_alert' => true]);
            return;
        }
        bottext_extras_key_hint('users.affiliates.rewardRejected');
        sendmessage($rw_uid, payer_texts($rw_uid)['users']['affiliates']['rewardRejected'], null, 'HTML');
        Editmessagetext($from_id, $message_id, $rw_req . $rw_t['rejected'], null);
        // ❌ in the report group's 🎁 topic too, under its ⏳
        affrw_topic($rw_row['lang'] ?? 'fa', strtr($rw_t['reportRejected'], [
            '{user}' => aff_user_block($rw_uid, select("user", "*", "id", $rw_uid, "select")),
            '{round}' => affrw_times($rw_row) + 1,
            '{max}' => affrw_cfg($rw_row['lang'] ?? 'fa')['max'],
            '{admin}' => $rw_admin,
        ]));
    }
    return;
}

//----------------[  channel join-gate button settings: dispatchers  ]----------------
// Every callback carries the language tab it acts on. The bare forms from
// before the tabs existed can still arrive from an old message in the chat;
// they mean fa, the tab those looks were set up on.
if (!function_exists('chnbtn_lang_arg')) {
    function chnbtn_lang_arg($l)
    {
        return in_array((string) $l, panel_langs(), true) ? (string) $l : 'fa';
    }
}
if (preg_match('/^chnbtn_hub(?::([a-z]{2}))?$/', $datain, $ch_m) && $adminrulecheck['rule'] == "administrator") {
    $ch_lang = chnbtn_lang_arg($ch_m[1] ?? '');
    $ch_kb = chnbtn_hub_payload($textbotlang, $ch_lang);
    Editmessagetext($from_id, $message_id, "📯 <b>دکمه‌های کانال</b>" . mainmenu_tab_note($ch_lang) . "\n\nرنگ، ایموجی، چیدمان و نام/نمایش دکمه‌های پیام «عضویت اجباری» رو از اینجا تنظیم کن 👇", $ch_kb, 'HTML');
    return;
}
if (preg_match('/^chnbtn_open:(color|emoji|layout|rename)(?::([a-z]{2}))?$/', $datain, $ch_m) && $adminrulecheck['rule'] == "administrator") {
    $ch_lang = chnbtn_lang_arg($ch_m[2] ?? '');
    $ch_note = mainmenu_tab_note($ch_lang);
    if ($ch_m[1] === 'color') {
