// The 👁 پیش‌نمایش screen used to live here. Every item's editing screen now
// quotes its own live text (bt_current_text_quote), so nothing pointed at this
// any more - and a screen the admin had to leave the editor to reach told them
// strictly less than the quote sitting above the buttons does.
if (preg_match('/^btact\|back\|([a-z]{2})$/', $datain, $btm) && $adminrulecheck['rule'] == "administrator") {
    step('home', $from_id);
    list($bt_home, $bt_kb) = keyboard_list_text($btm[1]);
    Editmessagetext($from_id, $message_id, $bt_home, $bt_kb, 'HTML');
    return;
}
if (preg_match('/^btact\|rsttext\|([a-z]{2})\|(.+)$/', $datain, $btm) && $adminrulecheck['rule'] == "administrator") {
    $bt_setting = select("setting", "*", null, null, "select");
    $bt_map = json_decode((string) ($bt_setting['text_edit'] ?? ''), true);
    if (!is_array($bt_map)) {
        $bt_map = [];
    }
    if (isset($bt_map[$btm[1]]) && is_array($bt_map[$btm[1]])) {
        bottext_dotted_unset($bt_map[$btm[1]], $btm[2]);
        if (empty($bt_map[$btm[1]])) {
            unset($bt_map[$btm[1]]);
        }
    }
    update("setting", "text_edit", empty($bt_map) ? null : json_encode($bt_map, JSON_UNESCAPED_UNICODE), null, null);
    step('home', $from_id);
    $textbotlang = panel_texts();
    // the screen below quotes the text: read the tab again, without the old one
    lang_tab_texts($btm[1], true);
    list($btm_text, $btm_kb) = bottext_item_menu_payload($btm[2], $btm[1], $textbotlang);
    Editmessagetext($from_id, $message_id, $textbotlang['bottext']['msg_reset_done'] . "\n\n" . $btm_text, $btm_kb, 'HTML');
    return;
}
if (preg_match('/^btact\|rstall\|([a-z]{2})\|(.+)$/', $datain, $btm) && $adminrulecheck['rule'] == "administrator") {
    // clears every store this item can live in - text, sticker, reaction,
    // per-button overrides and, for the usertest item, its config-column
    // settings - and only for the language tab the admin is on
    bottext_reset_keys([$btm[2]], $btm[1]);
    step('home', $from_id);
    $textbotlang = panel_texts();
    lang_tab_texts($btm[1], true);
    list($btm_text, $btm_kb) = bottext_item_menu_payload($btm[2], $btm[1], $textbotlang);
    Editmessagetext($from_id, $message_id, "🔁 همه تنظیمات این پیام به پیش‌فرض برگشت.\n\n" . $btm_text, $btm_kb, 'HTML');
    return;
}
if (preg_match('/^btact\|delst\|([a-z]{2})\|(.+)$/', $datain, $btm) && $adminrulecheck['rule'] == "administrator") {
    $bt_setting = select("setting", "*", null, null, "select");
    $bt_layout = json_decode((string) ($bt_setting['keyboardmain'] ?? ''), true);
    if (is_array($bt_layout) && isset($bt_layout['keyboard'])) {
        if (!isset($bt_layout['text_stickers']) || !is_array($bt_layout['text_stickers'])) {
            $bt_layout['text_stickers'] = [];
        }
        bt_media_unset($bt_layout['text_stickers'], $btm[2], $btm[1]);
        update("setting", "keyboardmain", json_encode($bt_layout, JSON_UNESCAPED_UNICODE), null, null);
    }
    step('home', $from_id);
    list($btm_text, $btm_kb) = bottext_item_menu_payload($btm[2], $btm[1], $textbotlang);
    $btm_def = function_exists('bt_default_sticker') && bt_default_sticker($btm[2]) !== '';
    Editmessagetext($from_id, $message_id, ($btm_def ? "🗑 استیکر خودت حذف شد و استیکر پیش‌فرض این پیام برگشت 🔹" : "🗑 استیکر حذف شد.") . "\n\n" . $btm_text, $btm_kb, 'HTML');
    return;
}
