}
if (preg_match('/^btact\|bbtntext\|([a-z]{2})$/', $datain, $btm) && $adminrulecheck['rule'] == "administrator") {
    savedata("clear", "bt_msgid", $message_id);
    step("btbbtntext-{$btm[1]}", $from_id);
