        $bb_be = [];
    }
    $bb_be[$bb_lang]['users.Balance.insufficientBalanceSimple'][0]['style'] = $bb_style;
    update("setting", "button_edit", json_encode($bb_be, JSON_UNESCAPED_UNICODE), null, null);
