}
if (preg_match('/^btact\|bbtnsimple\|([a-z]{2})$/', $datain, $btm) && $adminrulecheck['rule'] == "administrator") {
    $bb_lang = $btm[1];
    $bb_setting = select("setting", "*", null, null, "select");
