        $bb_be[$bb_lang]['users.Balance.insufficientBalanceSimple'][0]['icon_emoji'] = $bb_icon_id;
        unset($bb_be[$bb_lang]['users.Balance.insufficientBalanceSimple'][0]['emoji']);
