    $pg_done = payg_locked($pg_m[1], function () use ($pg_m) {
        $svc = payg_row($pg_m[1]);
        if ($svc === null || !in_array($svc['status'], ['waiting', 'active', 'stopped', 'paused'], true)) {
            return null;
        }
        payg_settle($svc);
        return payg_delete(payg_row($pg_m[1]), 'admin');
    });
    if (!is_array($pg_done)) {
        telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => $pg_r['gone'], 'show_alert' => true]);
        return;
    }
    [$pg_text, $pg_kb] = payg_admin_list_screen($pg_done['lang'], 1);
    Editmessagetext($from_id, $message_id, strtr($pg_r['adminDeleted'], ['{service}' => htmlspecialchars($pg_done['username'])]) . "\n\n" . $pg_text, $pg_kb, 'HTML');
} elseif (preg_match('/^flsec:([a-z]{2}):(linkapp|wheel|aff|affrw|affc|affr|refvc|refvr|loc|phone|lottery)$/', $datain, $fs_m) && $adminrulecheck['rule'] == "administrator") {
    // ⚙️ تنظیمات - opens the section inline, in the same message, in the same
    // language, instead of the old reply-keyboard screen
    $fs_lang = $fs_m[1];
    // 🎁 کانفیگ رایگان is a page of 👥 طرح‌های زیرمجموعه‌گیری now
    $fs_sec = $fs_m[2] === 'affrw' ? 'affr' : $fs_m[2];
    Editmessagetext($from_id, $message_id, feature_section_caption($textbotlang, $fs_lang, $fs_sec), feature_section_payload($textbotlang, $fs_lang, $fs_sec));
} elseif (preg_match('/^flstog:([a-z]{2}):lottery_agent:([01])$/', $datain, $fs_m) && $adminrulecheck['rule'] == "administrator") {
    // agents in this language's nightly lottery
    feature_set('Lotteryagent', $fs_m[1], $fs_m[2] === '1' ? '0' : '1');
    Editmessagetext($from_id, $message_id, feature_section_caption($textbotlang, $fs_m[1], 'lottery'), feature_section_payload($textbotlang, $fs_m[1], 'lottery'));
} elseif (preg_match('/^flstog:([a-z]{2}):(aff_classic|aff_commission|aff_startgift|aff_firstbuy):([a-zA-Z0-9_]+)$/', $datain, $fs_m) && $adminrulecheck['rule'] == "administrator") {
    $fs_lang = $fs_m[1];
    $fs_key = $fs_m[2];
    $fs_val = $fs_m[3];
    if ($fs_key === 'aff_classic') {
        $fs_new = ($fs_val === '1') ? '0' : '1';
    } elseif ($fs_key === 'aff_commission') {
        $fs_new = ($fs_val === 'oncommission') ? 'offcommission' : 'oncommission';
    } elseif ($fs_key === 'aff_startgift') {
        $fs_new = ($fs_val === 'onDiscountaffiliates') ? 'offDiscountaffiliates' : 'onDiscountaffiliates';
    } else {
        $fs_new = ($fs_val === 'on_buy_porsant') ? 'off_buy_porsant' : 'on_buy_porsant';
    }
    feature_setting_set($fs_key, $fs_lang, $fs_new);
    Editmessagetext($from_id, $message_id, feature_section_caption($textbotlang, $fs_lang, 'affc'), feature_section_payload($textbotlang, $fs_lang, 'affc'));
} elseif (preg_match('/^flsask:([a-z]{2}):([a-z_]+)$/', $datain, $fs_m) && $adminrulecheck['rule'] == "administrator") {
    $fs_lang = $fs_m[1];
    $fs_key = $fs_m[2];
    $fs_sec = feature_section_of_key($fs_key);
    if ($fs_sec === null) {
        return;
    }
    $fs_tx = lang_tab_texts('fa');
    savedata("clear", "fls_key", $fs_key);
    savedata("save", "fls_lang", $fs_lang);
    step("flsval", $from_id);
    // the prompt replaces the section screen in place and carries its own
    // cancel button, so the admin is never stranded in a step with no way out
    $fs_cancel = json_encode(['inline_keyboard' => [[
        ['text' => $fs_tx['Admin']['FeatureSection']['cancel'], 'callback_data' => "flscan:{$fs_lang}:{$fs_sec}", 'style' => 'danger'],
    ]]]);
    Editmessagetext($from_id, $message_id, strtr($fs_tx['Admin']['FeatureSection']['ask_' . $fs_key], [
        '{lang}' => $fs_tx['bottext']['langs'][$fs_lang] ?? $fs_lang,
        // amounts are entered in THIS language's currency, so the prompt has
        // to name it - otherwise every market gets typed in toman
        '{currency}' => currency_get(currency_for_lang($fs_lang))['title'],
    ]), $fs_cancel);
} elseif (preg_match('/^flsph:([a-z]{2}):(all|def|aud|t:(\d{1,4}))$/', $datain, $ph_m) && $adminrulecheck['rule'] == "administrator") {
    // 📞 کد کشور of one tab
    $ph_lang = $ph_m[1];
    $ph_cur = phone_prefixes_for_lang($ph_lang);
    if ($ph_m[2] === 'aud') {
        // everyone -> newcomers (from now on) -> invited customers -> everyone
        $ph_next = ['all' => 'new', 'new' => 'invited', 'invited' => 'all'][(string) feature_setting_value('phone_audience', $ph_lang, 'all')] ?? 'all';
        feature_setting_set('phone_audience', $ph_lang, $ph_next);
        feature_setting_set('phone_audience_since', $ph_lang, $ph_next === 'new' ? (string) time() : '0');
    } elseif ($ph_m[2] === 'all') {
        if (empty($ph_cur)) {
            // already open to everyone - narrowing it is picking countries below
            telegram('answerCallbackQuery', [
                'callback_query_id' => $callback_query_id,
                'text' => lang_tab_texts('fa')['Admin']['FeatureSection']['phoneAllOnAlert'],
                'show_alert' => true,
            ]);
            return;
        }
        phone_prefixes_set($ph_lang, []);
    } elseif ($ph_m[2] === 'def') {
        // "" is "never set": this language's built-in default again
        feature_setting_set('phone_prefix', $ph_lang, '');
    } else {
        $ph_code = (string) $ph_m[3];
        phone_prefixes_set($ph_lang, in_array($ph_code, $ph_cur, true) ? array_diff($ph_cur, [$ph_code]) : array_merge($ph_cur, [$ph_code]));
    }
    Editmessagetext($from_id, $message_id, feature_section_caption($textbotlang, $ph_lang, 'phone'), feature_section_payload($textbotlang, $ph_lang, 'phone'));
} elseif (preg_match('/^flscan:([a-z]{2}):(linkapp|wheel|aff|affrw|affc|affr|refvc|refvr|loc|phone|lottery)$/', $datain, $fs_m) && $adminrulecheck['rule'] == "administrator") {
    $fs_lang = $fs_m[1];
    $fs_sec = $fs_m[2] === 'affrw' ? 'affr' : $fs_m[2];
    step("home", $from_id);
    Editmessagetext($from_id, $message_id, feature_section_caption($textbotlang, $fs_lang, $fs_sec), feature_section_payload($textbotlang, $fs_lang, $fs_sec));
} elseif ($user['step'] == "flsval" && $adminrulecheck['rule'] == "administrator") {
    $fs_data = json_decode((string) $user['Processing_value'], true);
    $fs_key = $fs_data['fls_key'] ?? '';
    $fs_lang = $fs_data['fls_lang'] ?? 'fa';
    $fs_sec = feature_section_of_key($fs_key);
    if ($fs_sec === null) {
        step("home", $from_id);
        return;
    }
    $fs_tx = lang_tab_texts('fa');
    if ($fs_key === 'aff_banner') {
        if (!$photo) {
            sendmessage($from_id, $fs_tx['Admin']['affiliates']['invalidBanner'], null, 'HTML');
            return;
        }
        feature_setting_set('aff_banner_media', $fs_lang, $photoid);
        feature_setting_set('aff_banner_text', $fs_lang, (string) $caption);
    } elseif ($fs_key === 'app_name') {
        if (trim((string) $text) === '' || mb_strlen((string) $text) > 200) {
            sendmessage($from_id, $fs_tx['Admin']['apps']['nameTooLong'], null, 'HTML');
            return;
        }
        savedata("save", "fls_appname", $text);
        step("flsapplink", $from_id);
        sendmessage($from_id, $fs_tx['Admin']['apps']['askLink'], null, 'HTML');
        return;
    } elseif ($fs_key === 'app_link') {
        if (!filter_var($text, FILTER_VALIDATE_URL)) {
            sendmessage($from_id, $fs_tx['Admin']['managepanel']['invalidDomain'], null, 'HTML');
            return;
        }
        $fs_appid = (int) ($fs_data['fls_appid'] ?? 0);
        // a row other tabs show too gets a copy of its own for this tab; the
        // original keeps its link for the rest
        $fs_app = select("app", "*", "id", $fs_appid, "select");
        $fs_rest = is_array($fs_app) ? array_values(array_diff(app_row_langs($fs_app), [$fs_lang])) : [];
        if (is_array($fs_app) && !empty($fs_rest)) {
            update("app", "lang", implode(',', $fs_rest), "id", $fs_appid);
            $fs_stmt = $pdo->prepare("INSERT INTO app (name, link, lang) VALUES (:name, :link, :lang)");
            $fs_stmt->bindValue(':name', (string) $fs_app['name']);
            $fs_stmt->bindValue(':link', (string) $text);
            $fs_stmt->bindValue(':lang', $fs_lang);
            $fs_stmt->execute();
        } else {
            update("app", "link", $text, "id", $fs_appid);
        }
    } elseif ($fs_key === 'phone_prefix') {
        // one or more country dial codes, e.g. "98" or "1,44"; a lone 0 clears
        // the restriction so the language accepts every country again
        $fs_clean = [];
        foreach (preg_split('/[,\s]+/', (string) $text) as $fs_p) {
            $fs_p = preg_replace('/\D+/', '', (string) $fs_p);
            if ($fs_p !== '' && $fs_p !== '0') {
                $fs_clean[] = $fs_p;
            }
        }
        if (!$fs_clean && trim((string) $text) !== '0') {
            sendmessage($from_id, $fs_tx['common']['invalidInput'], null, 'HTML');
            return;
        }
        // added to what this tab already allows; "0" opens it to every country
        phone_prefixes_set($fs_lang, $fs_clean ? array_merge(phone_prefixes_for_lang($fs_lang), $fs_clean) : []);
    } elseif (in_array($fs_key, ['lottery_1', 'lottery_2', 'lottery_3'], true)) {
        // a prize in this language's currency
        $fs_cur = currency_for_lang($fs_lang);
        if (!money_valid($text, $fs_cur)) {
            sendmessage($from_id, $fs_tx['common']['invalidInput'], null, 'HTML');
            return;
        }
        lottery_prize_set($fs_lang, (int) substr($fs_key, -1), money_normalize($text));
    } elseif ($fs_key === 'affrw_gb') {
        // 🎁 کانفیگ رایگان's volume: under a gigabyte too (0.5, 200MB)
        $fs_gb = volume_parse($text, 'gb');
        if ($fs_gb === null) {
            sendmessage($from_id, $fs_tx['common']['invalidVolume'], null, 'HTML');
            return;
        }
        feature_setting_set($fs_key, $fs_lang, volume_store($fs_gb));
    } elseif ($fs_key === 'affrw_speed') {
        // 🚀 its speed in Mbps (2.5 works), 0 = none
        $fs_sp = speed_limit_parse($text);
        if ($fs_sp === null) {
            sendmessage($from_id, $fs_tx['Admin']['Product']['invalidSpeed'], null, 'HTML');
            return;
        }
        feature_setting_set($fs_key, $fs_lang, speed_limit_store($fs_sp));
    } elseif (in_array($fs_key, ['affrw_need', 'affrw_days', 'affrw_max'], true)) {
        // 🎁 کانفیگ رایگان: a count, gigabytes, days - none of them can be 0
        if (!ctype_digit((string) $text) || intval($text) < 1) {
            sendmessage($from_id, $fs_tx['common']['invalidInput'], null, 'HTML');
            return;
        }
        feature_setting_set($fs_key, $fs_lang, (string) intval($text));
    } elseif ($fs_key === 'affrw_reset') {
        // 🔄 one customer's free config from the start: count and 🔁 چند بار
        $fs_u = svcgive_find_user($text);
        if ($fs_u === null) {
            sendmessage($from_id, strtr($fs_tx['Admin']['UserMgmt']['assignNoUser'], ['{id}' => htmlspecialchars(trim((string) $text))]), null, 'HTML');
            return;
        }
        affrw_reset($fs_u['id']);
        sendmessage($from_id, strtr($fs_tx['Admin']['FeatureSection']['affrwResetUserDone'], [
            '{id}' => $fs_u['id'],
            '{name}' => (!empty($fs_u['username']) && $fs_u['username'] !== 'none') ? '@' . htmlspecialchars($fs_u['username']) : '',
        ]), null, 'HTML');
    } elseif ($fs_key === 'wheel_price' || $fs_key === 'aff_giftamount') {
        // an amount in this language's currency - USD carries
        // decimals, so "12.5" has to be accepted, not just whole numbers
        $fs_cur = currency_for_lang($fs_lang);
        if (!money_valid($text, $fs_cur)) {
            sendmessage($from_id, $fs_tx['common']['invalidInput'], null, 'HTML');
            return;
        }
        feature_setting_set($fs_key, $fs_lang, money_normalize($text));
    } else {
        // counts and percentages stay whole numbers
        if (!ctype_digit((string) $text)) {
            sendmessage($from_id, $fs_tx['common']['invalidInput'], null, 'HTML');
            return;
        }
        feature_setting_set($fs_key, $fs_lang, (string) intval($text));
    }
    step("home", $from_id);
    sendmessage($from_id, feature_section_caption($textbotlang, $fs_lang, $fs_sec), feature_section_payload($textbotlang, $fs_lang, $fs_sec), 'HTML');
} elseif ($user['step'] == "flsapplink" && $adminrulecheck['rule'] == "administrator") {
    $fs_data = json_decode((string) $user['Processing_value'], true);
    $fs_lang = $fs_data['fls_lang'] ?? 'fa';
    $fs_tx = lang_tab_texts('fa');
    if (!filter_var($text, FILTER_VALIDATE_URL)) {
        sendmessage($from_id, $fs_tx['Admin']['managepanel']['invalidDomain'], null, 'HTML');
        return;
    }
    // a row added from a language tab belongs to that language only
    $fs_stmt = $pdo->prepare("INSERT INTO app (name, link, lang) VALUES (:name, :link, :lang)");
    $fs_stmt->bindValue(':name', (string) ($fs_data['fls_appname'] ?? ''));
    $fs_stmt->bindValue(':link', (string) $text);
    $fs_stmt->bindValue(':lang', $fs_lang);
    $fs_stmt->execute();
    step("home", $from_id);
    sendmessage($from_id, feature_section_caption($textbotlang, $fs_lang, 'linkapp'), feature_section_payload($textbotlang, $fs_lang, 'linkapp'), 'HTML');
} elseif (preg_match('/^flsappd:([a-z]{2}):(\d+)$/', $datain, $fs_m) && $adminrulecheck['rule'] == "administrator") {
    $fs_lang = $fs_m[1];
    // gone from this tab only: a row other tabs show too stays theirs
    $fs_app = select("app", "*", "id", (int) $fs_m[2], "select");
    $fs_rest = is_array($fs_app) ? array_values(array_diff(app_row_langs($fs_app), [$fs_lang])) : [];
    if (!empty($fs_rest)) {
        update("app", "lang", implode(',', $fs_rest), "id", (int) $fs_m[2]);
    } else {
        $fs_stmt = $pdo->prepare("DELETE FROM app WHERE id = :id");
        $fs_stmt->bindValue(':id', (int) $fs_m[2], PDO::PARAM_INT);
        $fs_stmt->execute();
    }
    Editmessagetext($from_id, $message_id, feature_section_caption($textbotlang, $fs_lang, 'linkapp'), feature_section_payload($textbotlang, $fs_lang, 'linkapp'));
} elseif (preg_match('/^flsappe:([a-z]{2}):(\d+)$/', $datain, $fs_m) && $adminrulecheck['rule'] == "administrator") {
    $fs_lang = $fs_m[1];
    $fs_tx = lang_tab_texts('fa');
    savedata("clear", "fls_key", 'app_link');
    savedata("save", "fls_lang", $fs_lang);
    savedata("save", "fls_appid", (int) $fs_m[2]);
    step("flsval", $from_id);
    $fs_cancel = json_encode(['inline_keyboard' => [[
        ['text' => $fs_tx['Admin']['FeatureSection']['cancel'], 'callback_data' => "flscan:{$fs_lang}:linkapp", 'style' => 'danger'],
    ]]]);
    Editmessagetext($from_id, $message_id, $fs_tx['Admin']['apps']['askNewLink'], $fs_cancel);
} elseif (preg_match('/^flsloc:([a-z]{2}):(ask|do)$/', $datain, $fs_m) && $adminrulecheck['rule'] == "administrator") {
    $fs_lang = $fs_m[1];
    $fs_tx = lang_tab_texts('fa');
    if ($fs_m[2] === 'ask') {
        $fs_kb = json_encode(['inline_keyboard' => [
            [['text' => $fs_tx['keyboard']['confirmAndZero'], 'callback_data' => "flsloc:{$fs_lang}:do", 'style' => 'danger']],
            [['text' => $fs_tx['Admin']['FeatureSection']['cancel'], 'callback_data' => "flscan:{$fs_lang}:loc"]],
        ]]);
        Editmessagetext($from_id, $message_id, strtr($fs_tx['Admin']['FeatureSection']['locResetConfirm'], ['{lang}' => $fs_tx['bottext']['langs'][$fs_lang] ?? $fs_lang]), $fs_kb);
        return;
    }
    // scoped to this language's own users - the whole screen is per-language,
    // so a reset triggered from the English tab must not touch Persian users
    $fs_stmt = $pdo->prepare("UPDATE user SET limitchangeloc = '0' WHERE lang = :lang");
    $fs_stmt->bindValue(':lang', $fs_lang);
    $fs_stmt->execute();
    Editmessagetext($from_id, $message_id, feature_section_caption($textbotlang, $fs_lang, 'loc'), feature_section_payload($textbotlang, $fs_lang, 'loc'));
} elseif ($text == $textbotlang['keyboard']['botReports'] && $adminrulecheck['rule'] == "administrator") {
    $textreports = sprintf($textbotlang['Admin']['Channel']['askReportGroupId'], $setting['Channel_Report']);
    sendmessage($from_id, $textreports, $backadmin, 'HTML');
    step('addchannelid', $from_id);
} elseif ($user['step'] == "addchannelid") {
    $outputcheck = sendmessage($text, $textbotlang['Admin']['Channel']['testChannel'], null, 'HTML');
    if (!$outputcheck['ok']) {
        $texterror = sprintf($textbotlang['Admin']['Channel']['connectionFailed'], $outputcheck['description']);
        sendmessage($from_id, $texterror, null, 'HTML');
        return;
    }
    if ($outputcheck['result']['chat']['is_forum'] == false) {
        $texterror = $textbotlang['Admin']['Channel']['notForumGroup'];
        sendmessage($from_id, $texterror, null, 'HTML');
        return;
    }
    // the topics there are used; only the missing ones are made, and the
    // bot's own extra copies (from setting the group up before) are deleted
    $rt_res = report_topics_setup($text, $textbotlang);
    if ($rt_res['error'] !== null) {
        $rt_why = stripos($rt_res['error'], 'rights') !== false || stripos($rt_res['error'], 'admin') !== false
            ? $textbotlang['Admin']['Channel']['botNotGroupAdmin']
            : "⚠️ تلگرام اجازه نداد همه‌ی تاپیک‌ها ساخته بشن: <code>" . htmlspecialchars($rt_res['error']) . "</code>\nچند لحظه بعد دوباره آیدی گروه رو بفرست - تاپیک‌هایی که ساخته شدن دوباره ساخته نمی‌شن.";
        sendmessage($from_id, $rt_why, null, 'HTML');
        return;
    }
    update("setting", "Channel_Report", $text);
    $rt_note = "\n\n🗂 تاپیک‌ها: {$rt_res['kept']} تا از قبل بود و همون موند، {$rt_res['made']} تا ساخته شد"
        . ($rt_res['removed'] > 0 ? "، {$rt_res['removed']} تاپیک تکراری حذف شد." : ".");
    sendmessage($from_id, $textbotlang['Admin']['Channel']['setChannelReport'] . $rt_note, $setting_panel, 'HTML');
    step('home', $from_id);
} elseif (($text == $textbotlang['keyboard']['shopSettings'] || $text == "/shop") && $adminrulecheck['rule'] == "administrator") {
    sendmessage($from_id, $textbotlang['Admin']['shopSettingsCaption'], $shopkeyboard, 'HTML');
} elseif ($datain == "gwlang_hub" && $adminrulecheck['rule'] == "administrator") {
    gateway_lang_map(true);
    gw_lang_settings_map(true);
    Editmessagetext($from_id, $message_id, gateway_hub_caption('fa', $textbotlang), gateway_hub_payload('fa', $textbotlang), 'HTML');
} elseif ($datain == "gwlang_close" && $adminrulecheck['rule'] == "administrator") {
    deletemessage($from_id, $message_id);
} elseif (preg_match('/^gwlang:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    gw_lang_settings_map(true);
    Editmessagetext($from_id, $message_id, gateway_hub_caption($gw_m[1], $textbotlang), gateway_hub_payload($gw_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^gwtoggle:([a-z]{2}):([a-z0-9]+)(:1)?$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    $gw_lang = $gw_m[1];
    $gw_key = $gw_m[2];
    $gw_fromSettings = isset($gw_m[3]) && $gw_m[3] !== '';
    if (!in_array($gw_key, gateway_all_keys(), true)) {
        return;
    }
    $gw_keys = gateway_current_keys($gw_lang);
    // flip what the row SHOWS (allowed here AND switched on globally). Testing
    // only the per-language list made the first tap on a ❌ gateway that was
    // merely switched off globally (every new gateway on a shop that never
    // restricted a language) take it off the list instead - still ❌, and
    // only a second tap turned it on.
    if (in_array($gw_key, $gw_keys, true) && gateway_globally_on($gw_key)) {
        // off for this language only - other languages may still be selling it
        $gw_keys = array_values(array_diff($gw_keys, [$gw_key]));
        gateway_set_for_lang($gw_lang, $gw_keys);
    } else {
        if (!in_array($gw_key, $gw_keys, true)) {
            $gw_keys[] = $gw_key;
        }
        gateway_set_for_lang($gw_lang, $gw_keys);
        // turning it on here has to turn on the separate global switch too,
        // otherwise the row shows ✅ while real users still see nothing and
        // there is no longer any second toggle on screen to discover
        gateway_globally_set($gw_key, true);
    }
    if ($gw_fromSettings) {
        Editmessagetext($from_id, $message_id, gateway_settings_caption($gw_lang, $gw_key, $textbotlang), gateway_settings_payload($gw_lang, $gw_key, $textbotlang), 'HTML');
    } else {
        // stay on the screen the row was tapped on: a grouped gateway is only
        // listed inside its own group, so re-rendering the hub threw the admin
        // out of the family they were working in after every single toggle
        $gw_grp = gateway_group_of($gw_key);
        if ($gw_grp !== null) {
            Editmessagetext($from_id, $message_id, gateway_group_caption($gw_lang, $gw_grp, $textbotlang), gateway_group_payload($gw_lang, $gw_grp, $textbotlang), 'HTML');
        } else {
            Editmessagetext($from_id, $message_id, gateway_hub_caption($gw_lang, $textbotlang), gateway_hub_payload($gw_lang, $textbotlang), 'HTML');
        }
    }
} elseif (preg_match('/^gwall:([a-z]{2}):([01])$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    if ($gw_m[2] === '1') {
        // "turn everything on" must mean what it says: allow every gateway that
        // applies to this language AND switch each one on globally, or the rows
        // stay ❌ and the button looks broken
        $gw_on = array_values(array_filter(gateway_all_keys(), fn($k) => gateway_applicable_for_lang($k, $gw_m[1])));
        gateway_set_for_lang($gw_m[1], $gw_on);
        foreach ($gw_on as $gw_k) {
            gateway_globally_set($gw_k, true);
        }
    } else {
        // off for this language only; the global switches stay as they are so
        // the other languages keep working
        gateway_set_for_lang($gw_m[1], []);
    }
    telegram('answerCallbackQuery', [
        'callback_query_id' => $callback_query_id,
        'text' => $textbotlang['Admin']['GatewayLang']['saved'],
        'show_alert' => false,
        'cache_time' => 1,
    ]);
    Editmessagetext($from_id, $message_id, gateway_hub_caption($gw_m[1], $textbotlang), gateway_hub_payload($gw_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^gwglobal:([a-z]{2}):([a-z0-9]+)$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    if (!in_array($gw_m[2], gateway_all_keys(), true)) {
        return;
    }
    gateway_globally_set($gw_m[2], !gateway_globally_on($gw_m[2]));
    telegram('answerCallbackQuery', [
        'callback_query_id' => $callback_query_id,
        'text' => $textbotlang['Admin']['GatewayLang']['saved'],
        'show_alert' => false,
        'cache_time' => 1,
    ]);
    Editmessagetext($from_id, $message_id, gateway_settings_caption($gw_m[1], $gw_m[2], $textbotlang), gateway_settings_payload($gw_m[1], $gw_m[2], $textbotlang), 'HTML');
} elseif (preg_match('/^gwset:([a-z]{2}):([a-z0-9]+)$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    if (!in_array($gw_m[2], gateway_all_keys(), true)) {
        return;
    }
    gw_lang_settings_map(true);
    Editmessagetext($from_id, $message_id, gateway_settings_caption($gw_m[1], $gw_m[2], $textbotlang), gateway_settings_payload($gw_m[1], $gw_m[2], $textbotlang), 'HTML');
} elseif (preg_match('/^tonmemo:([a-z]{2})$/', $datain, $tm_m) && $adminrulecheck['rule'] == "administrator") {
    Editmessagetext($from_id, $message_id, ton_memo_settings_caption($tm_m[1]), ton_memo_settings_payload($tm_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^tonmemolocked:([a-z]{2})$/', $datain, $tm_m) && $adminrulecheck['rule'] == "administrator") {
    // never becomes available - the reason is a property of a public chain,
    // not a setting, so this row explains rather than unlocks
    telegram('answerCallbackQuery', [
        'callback_query_id' => $callback_query_id,
        'text' => topup_memo_locked_reason(),
        'show_alert' => true,
        'cache_time' => 1,
    ]);
} elseif (preg_match('/^tonmemoreset:([a-z]{2})$/', $datain, $tm_m) && $adminrulecheck['rule'] == "administrator") {
    topup_memo_reset($tm_m[1], 'ton');
    Editmessagetext($from_id, $message_id, ton_memo_settings_caption($tm_m[1]), ton_memo_settings_payload($tm_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^tonmemo(prefix|len):([a-z]{2})$/', $datain, $tm_m) && $adminrulecheck['rule'] == "administrator") {
    $tm_lim = topup_memo_limits();
    $tm_cfg = topup_memo_config($tm_m[2], 'ton');
    if ($tm_m[1] === 'prefix') {
        $tm_ask = "🔤 <b>پیشوند ممو را بفرستید</b>\n\n"
            . "فقط حروف انگلیسی و عدد، حداکثر {$tm_lim['prefixMax']} کاراکتر. مثال: <code>CiroVPN</code>\n\n"
            . "مقدار فعلی: " . ($tm_cfg['prefix'] === '' ? '<i>ندارد</i>' : "<code>{$tm_cfg['prefix']}</code>") . "\n"
            . "برای برداشتن پیشوند، عدد <b>0</b> را بفرستید.";
    } else {
        $tm_ask = "🎲 <b>طول بخش تصادفی را بفرستید</b>\n\n"
            . "عددی بین {$tm_lim['lenMin']} تا {$tm_lim['lenMax']}.\n\n"
            . "مقدار فعلی: <b>{$tm_cfg['len']}</b>";
    }
    $tm_prompt = sendmessage($from_id, $tm_ask, null, 'HTML');
    step("tonmemo:{$tm_m[1]}:{$tm_m[2]}:{$message_id}:" . (int) ($tm_prompt['result']['message_id'] ?? 0), $from_id);
} elseif (preg_match('/^tonmemo:(prefix|len):([a-z]{2}):([0-9]+):([0-9]+)$/', (string) $user['step'], $tm_m) && $datain == '') {
    $tm_lim = topup_memo_limits();
    $tm_val = trim((string) $text);
    deletemessage($from_id, $message_id);
    step("home", $from_id);
    if ($tm_m[1] === 'prefix') {
        // '0' is the agreed "clear this" shortcut across every gateway field,
        // and a bare digit makes a poor shop prefix anyway
        $tm_clean = $tm_val === '0' ? '' : topup_memo_clean_prefix($tm_val);
        if ($tm_val !== '0' && $tm_clean === '') {
            Editmessagetext($from_id, (int) $tm_m[4], "❌ پیشوند باید فقط از حروف انگلیسی و عدد باشد.", null, 'HTML');
            step("tonmemo:{$tm_m[1]}:{$tm_m[2]}:{$tm_m[3]}:{$tm_m[4]}", $from_id);
            return;
        }
        topup_memo_set($tm_m[2], 'ton', 'prefix', $tm_clean);
    } else {
        if (!ctype_digit($tm_val) || (int) $tm_val < $tm_lim['lenMin'] || (int) $tm_val > $tm_lim['lenMax']) {
            Editmessagetext($from_id, (int) $tm_m[4], "❌ عددی بین {$tm_lim['lenMin']} تا {$tm_lim['lenMax']} بفرستید.", null, 'HTML');
            step("tonmemo:{$tm_m[1]}:{$tm_m[2]}:{$tm_m[3]}:{$tm_m[4]}", $from_id);
            return;
        }
        topup_memo_set($tm_m[2], 'ton', 'len', (int) $tm_val);
    }
    deletemessage($from_id, (int) $tm_m[4]);
    Editmessagetext($from_id, (int) $tm_m[3], ton_memo_settings_caption($tm_m[2]), ton_memo_settings_payload($tm_m[2], $textbotlang), 'HTML');
} elseif (preg_match('/^gwname:([a-z]{2}):([a-z0-9_]+)$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    // display-only label - explains the row instead of navigating anywhere
    telegram('answerCallbackQuery', [
        'callback_query_id' => $callback_query_id,
        'text' => gateway_name_alert($gw_m[1], $gw_m[2], $textbotlang),
        'show_alert' => true,
        'cache_time' => 1,
    ]);
    return;
} elseif (preg_match('/^gwgroup:([a-z]{2}):([a-z0-9_]+)$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    if (!isset(gateway_groups()[$gw_m[2]])) {
        return;
    }
    Editmessagetext($from_id, $message_id, gateway_group_caption($gw_m[1], $gw_m[2], $textbotlang), gateway_group_payload($gw_m[1], $gw_m[2], $textbotlang), 'HTML');
} elseif (preg_match('/^gwgrouptoggle:([a-z]{2}):([a-z0-9_]+)$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    if (!isset(gateway_groups()[$gw_m[2]])) {
        return;
    }
    // all off -> switch the whole family on; anything else -> switch it all off.
    // Mirrors the single-gateway toggle above, including the rule that turning
    // one ON must also flip its global switch or the row lies about being live.
    $gw_turnOn = gateway_group_state($gw_m[2], $gw_m[1]) === 'none';
    $gw_members = gateway_group_members($gw_m[2], $gw_m[1]);
    $gw_keys = gateway_current_keys($gw_m[1]);
    if ($gw_turnOn) {
        foreach ($gw_members as $gw_key) {
            if (!in_array($gw_key, $gw_keys, true)) {
                $gw_keys[] = $gw_key;
            }
            gateway_globally_set($gw_key, true);
        }
    } else {
        $gw_keys = array_values(array_diff($gw_keys, $gw_members));
    }
    gateway_set_for_lang($gw_m[1], $gw_keys);
    Editmessagetext($from_id, $message_id, gateway_hub_caption($gw_m[1], $textbotlang), gateway_hub_payload($gw_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^cardrandtoggle:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    // global switch (not per-language) - see the comment on this button's
    // row in gateway_settings_payload()
    $crt_setting = select("setting", "cardRandomAmount, smsForwardEnabled", null, null, "select");
    if (($crt_setting['smsForwardEnabled'] ?? '0') === '1') {
        // defensive: the keyboard already hides this behind cardrandlocked:
        // while SMS Forward is on, but a stale/older render of this screen
        // could still send this callback - never silently toggle in that case
        telegram('answerCallbackQuery', [
            'callback_query_id' => $callback_query_id,
            'text' => '🔒 چون SMS Forward روشنه، این قابلیت قفله. اول SMS Forward رو خاموش کنید.',
            'show_alert' => true,
        ]);
        Editmessagetext($from_id, $message_id, gateway_settings_caption($gw_m[1], 'card', $textbotlang), gateway_settings_payload($gw_m[1], 'card', $textbotlang), 'HTML');
        return;
    }
    $crt_on = (($crt_setting['cardRandomAmount'] ?? '0') === '1');
    update("setting", "cardRandomAmount", $crt_on ? '0' : '1', null, null);
    Editmessagetext($from_id, $message_id, gateway_settings_caption($gw_m[1], 'card', $textbotlang), gateway_settings_payload($gw_m[1], 'card', $textbotlang), 'HTML');
} elseif (preg_match('/^cardrandlocked:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    telegram('answerCallbackQuery', [
        'callback_query_id' => $callback_query_id,
        'text' => '🔒 چون SMS Forward روشنه، مبلغ رندوم قابل خاموش کردن نیست. اول SMS Forward رو خاموش کنید.',
        'show_alert' => true,
    ]);
} elseif (preg_match('/^smsfwdset:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    Editmessagetext($from_id, $message_id, "📲 <b>تنظیمات SMS Forward</b>", sms_forward_settings_payload($gw_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^smsfwdguide:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    list($sfw_info, $sfw_kb) = sms_forward_guide_payload($gw_m[1]);
    Editmessagetext($from_id, $message_id, $sfw_info, $sfw_kb, 'HTML');
} elseif (preg_match('/^smsfwdtoggle:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    // always lands back on this same settings screen now, whichever direction
    // it flipped - the setup guide has its own always-available "📖 راهنمای
