        $valuenew = ($value == "onshowprice") ? "offshowprice" : "onshowprice";
    } elseif ($type == "showconfig") {
        $valuenew = ($value == "onconfig") ? "offconfig" : "onconfig";
    } elseif ($type == "removeservicebackbtn") {
        $valuenew = ($value == "on") ? "off" : "on";
