} elseif (preg_match('/^bgh:(wk|wa|wps|wn|wh|wm:(fixed|total|left)|wp:(all|\d+))$/', $datain, $bg_m) && $adminrulecheck['rule'] == "administrator") {
    // The steps: wk 2 (how it is counted), wm picks it and wa asks 3 (how
    // much) again, wps 4 (which panels, wp ticks one) and wn goes on from it -
    // to a campaign's 5 (wh, how long) or to the summary. Every step's 🔙 is
    // the one before it.
    $bg_t = $textbotlang['Admin']['BulkGift'];
    $bg_p = bulkgift_draft($from_id);
    $bg_go = explode(':', $bg_m[1])[0];
    step('home', $from_id);
    if ($bg_go === 'wm' || $bg_go === 'wa') {
        if ($bg_go === 'wm') {
            $bg_p['mode'] = $bg_m[2];
            $bg_p['value'] = null;
            bulkgift_draft_save($from_id, $bg_p);
            $bg_p = bulkgift_draft($from_id);
        }
        // the answer leads on to step 4
        savedata("clear", "bg_wiz", 1);
        step('bgh_value', $from_id);
        bulkgift_draft_ask($from_id, $message_id);
        [$bg_text, $bg_kb] = bulkgift_value_payload($bg_p);
    } elseif ($bg_go === 'wp') {
        $bg_v = $bg_m[3];
        if ($bg_v === 'all') {
            $bg_p['panels'] = [];
        } else {
            $bg_row = select("marzban_panel", "*", "id", $bg_v, "select");
            if (is_array($bg_row)) {
                $bg_code = (string) $bg_row['code_panel'];
                $bg_p['panels'] = in_array($bg_code, $bg_p['panels'], true)
                    ? array_values(array_diff($bg_p['panels'], [$bg_code]))
                    : array_merge($bg_p['panels'], [$bg_code]);
            }
        }
        bulkgift_draft_save($from_id, $bg_p);
        [$bg_text, $bg_kb] = bulkgift_wpanels_payload(bulkgift_draft($from_id));
    } elseif ($bg_go === 'wh' || ($bg_go === 'wn' && bulkgift_is_live($bg_p))) {
        savedata("clear", "bg_buy", 'next');
        step('bgh_buyn', $from_id);
        bulkgift_draft_ask($from_id, $message_id);
        [$bg_text, $bg_kb] = bulkgift_whours_payload($bg_p);
    } elseif ($bg_go === 'wn' && $bg_p['value'] !== null) {
        [$bg_text, $bg_kb] = bulkgift_summary_payload($bg_p);
    } elseif ($bg_go === 'wps' && $bg_p['value'] !== null) {
        [$bg_text, $bg_kb] = bulkgift_wpanels_payload($bg_p);
    } elseif ($bg_go === 'wk' || $bg_go === 'wps' || $bg_go === 'wn') {
        [$bg_text, $bg_kb] = bulkgift_mode_payload($bg_p);
    }
    Editmessagetext($from_id, $message_id, $bg_text, $bg_kb, 'HTML');
} elseif (preg_match('/^bgh:(m|l|p|b|t):([a-z0-9_]+)$/', $datain, $bg_m) && $adminrulecheck['rule'] == "administrator") {
    // one of 🎯's settings changed: a single choice goes back to the summary,
    // a tick redraws its own screen, and a choice that needs a number asks
    // for it - its 🔙 leaves things as they were
    $bg_t = $textbotlang['Admin']['BulkGift'];
    $bg_p = bulkgift_draft($from_id);
    [$bg_key, $bg_val] = [$bg_m[1], $bg_m[2]];
    $bg_back = 'sum';
    if ($bg_key === 'm' && in_array($bg_val, ['fixed', 'total', 'left'], true)) {
        if ($bg_val !== $bg_p['mode']) {
            // gigabytes, days and percents are not the same number: the new
            // way is kept once its amount is typed
            savedata("clear", "bg_mode", $bg_val);
            step('bgh_value', $from_id);
            bulkgift_draft_ask($from_id, $message_id);
            [$bg_text, $bg_kb] = bulkgift_ask_payload(bulkgift_value_ask($bg_p, $bg_val), 'bgh:sum');
            Editmessagetext($from_id, $message_id, $bg_text, $bg_kb, 'HTML');
            return;
        }
    } elseif ($bg_key === 'l' && ($bg_val === 'all' || in_array($bg_val, panel_langs(), true))) {
        $bg_p['lang'] = $bg_val;
    } elseif ($bg_key === 'p') {
        $bg_back = 'panels';
        if ($bg_val === 'all') {
            $bg_p['panels'] = [];
        } else {
            $bg_row = select("marzban_panel", "*", "id", $bg_val, "select");
            if (is_array($bg_row)) {
                $bg_code = (string) $bg_row['code_panel'];
                $bg_p['panels'] = in_array($bg_code, $bg_p['panels'], true)
                    ? array_values(array_diff($bg_p['panels'], [$bg_code]))
                    : array_merge($bg_p['panels'], [$bg_code]);
            }
        }
    } elseif ($bg_key === 'b') {
        if ($bg_val === 'all') {
            $bg_p['buy'] = 'all';
            $bg_p['buyn'] = 0;
        } elseif (in_array($bg_val, ['lasth', 'days', 'months', 'hours'], true)) {
            // how many first - it is set once that is known
            savedata("clear", "bg_buy", $bg_val);
            step('bgh_buyn', $from_id);
            bulkgift_draft_ask($from_id, $message_id);
            [$bg_text, $bg_kb] = bulkgift_ask_payload($bg_t['askBuy' . ucfirst($bg_val)], 'bgh:sum');
            Editmessagetext($from_id, $message_id, $bg_text, $bg_kb, 'HTML');
            return;
        }
    } elseif ($bg_key === 't' && in_array($bg_val, bulkgift_statuses(), true)) {
        // one state on or off - at least one has to stay
        $bg_back = 'st';
        $bg_on = array_values(array_diff($bg_p['statuses'], [$bg_val]));
        if (in_array($bg_val, $bg_p['statuses'], true) && !$bg_on) {
            telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => strip_tags($bg_t['noStatus']), 'show_alert' => true]);
            return;
        }
        $bg_p['statuses'] = in_array($bg_val, $bg_p['statuses'], true) ? $bg_on : array_merge($bg_p['statuses'], [$bg_val]);
    }
    step('home', $from_id);
    bulkgift_draft_save($from_id, $bg_p);
    $bg_p = bulkgift_draft($from_id);
    if ($bg_back !== 'sum') {
        [$bg_text, $bg_kb] = bulkgift_sub_payload($bg_p, $bg_back);
    } else {
        [$bg_text, $bg_kb] = $bg_p['value'] !== null ? bulkgift_summary_payload($bg_p) : bulkgift_start_payload();
    }
    Editmessagetext($from_id, $message_id, $bg_text, $bg_kb, 'HTML');
} elseif (($user['step'] == 'bgh_value' || $user['step'] == 'bgh_buyn') && $datain === '' && $adminrulecheck['rule'] == "administrator") {
    // the typed answer - a button tapped meanwhile (🚫 لغو of a run, say) is
    // that button's, not an answer
    $bg_t = $textbotlang['Admin']['BulkGift'];
    $bg_p = bulkgift_draft($from_id);
    $bg_pv = json_decode((string) $user['Processing_value'], true) ?: [];
    if ($user['step'] == 'bgh_value') {
        // a way of counting picked in 🎯 is kept with its amount
        $bg_mode = in_array($bg_pv['bg_mode'] ?? '', ['fixed', 'total', 'left'], true) ? $bg_pv['bg_mode'] : $bg_p['mode'];
        [$bg_v, $bg_err] = bulkgift_parse_value($bg_p['kind'], $bg_mode, (string) $text);
        if ($bg_err !== null) {
            sendmessage($from_id, $bg_err, null, 'HTML');
            return;
        }
        $bg_p['mode'] = $bg_mode;
