        $help_color_order = ['', 'primary', 'success', 'danger'];
        $help_cur_color = $help_section['color'][$help_key] ?? '';
        $help_cur_idx = array_search($help_cur_color, $help_color_order, true);
        if ($help_cur_idx === false) {
            $help_cur_idx = 0;
        }
        $help_next_color = $help_color_order[($help_cur_idx + 1) % count($help_color_order)];
        if ($help_next_color === '') {
            unset($help_section['color'][$help_key]);
        } else {
            $help_section['color'][$help_key] = $help_next_color;
        }
        help_layout_set_section($help_lang, $help_kind, $help_section);
    }
    $help_kb = help_color_editor_payload($help_lang, $help_kind, $textbotlang);
    Editmessagetext($from_id, $message_id, $textbotlang['Admin']['Help']['colorCaption'], $help_kb, 'HTML');
