    $help_section = help_layout_section($help_lang, $help_kind);
    $help_ordered = help_layout_apply_order(array_keys($help_items), $help_section['order']);
    if (isset($help_ordered[$help_idx1], $help_ordered[$help_idx2])) {
        $help_tmp = $help_ordered[$help_idx1];
        $help_ordered[$help_idx1] = $help_ordered[$help_idx2];
        $help_ordered[$help_idx2] = $help_tmp;
        $help_section['order'] = array_values($help_ordered);
        help_layout_set_section($help_lang, $help_kind, $help_section);
        telegram('answerCallbackQuery', [
            'callback_query_id' => $callback_query_id,
            'text' => $textbotlang['Admin']['Help']['layoutSwapDone'],
            'show_alert' => false,
            'cache_time' => 1,
        ]);
    }
    $help_kb = help_layout_editor_payload($help_lang, $help_kind, $textbotlang, null, $help_from);
    Editmessagetext($from_id, $message_id, $textbotlang['Admin']['Help']['layoutCaption'], $help_kb, 'HTML');
} elseif (preg_match('/^help_lay_width:(categories|tutorials|panel|product|category|gateway|langpick):(fa|en):(\d+)(?::(pe))?$/', $datain, $help_m) && $adminrulecheck['rule'] == "administrator") {
    $help_kind = $help_m[1];
    $help_lang = $help_m[2];
    $help_idx = (int) $help_m[3];
    $help_from = $help_m[4] ?? '';
    $help_items = help_layout_items($help_lang, $help_kind);
    $help_section = help_layout_section($help_lang, $help_kind);
    $help_ordered = help_layout_apply_order(array_keys($help_items), $help_section['order']);
    if (isset($help_ordered[$help_idx])) {
        $help_key = $help_ordered[$help_idx];
        $help_cur = $help_section['width'][$help_key] ?? 'full';
        if ($help_cur === 'half') {
            // un-pair: find the actual current row partner (whichever side
            // of the pair it is) and revert BOTH to full, so the row splits
            // back into two single-button rows exactly like it looked before pairing
            $help_sim = help_layout_chunk_rows($help_ordered, array_combine($help_ordered, $help_ordered), $help_section['width']);
            $help_partner = null;
            foreach ($help_sim as $help_r) {
                if (in_array($help_key, $help_r, true) && count($help_r) === 2) {
                    $help_partner = ($help_r[0] === $help_key) ? $help_r[1] : $help_r[0];
                    break;
                }
            }
            $help_section['width'][$help_key] = 'full';
            if ($help_partner !== null) {
                $help_section['width'][$help_partner] = 'full';
            }
        } else {
            // pair: try the next item then the previous item in the current
            // order, picking whichever is itself still full-width (not
            // already paired with someone else) — single tap, visible result
            $help_pos = array_search($help_key, $help_ordered, true);
            $help_partner = null;
            if ($help_pos !== false) {
                if (isset($help_ordered[$help_pos + 1]) && ($help_section['width'][$help_ordered[$help_pos + 1]] ?? 'full') === 'full') {
                    $help_partner = $help_ordered[$help_pos + 1];
                } elseif (isset($help_ordered[$help_pos - 1]) && ($help_section['width'][$help_ordered[$help_pos - 1]] ?? 'full') === 'full') {
                    $help_partner = $help_ordered[$help_pos - 1];
                }
            }
            $help_section['width'][$help_key] = 'half';
            if ($help_partner !== null) {
                $help_section['width'][$help_partner] = 'half';
            }
        }
        $help_section['order'] = array_values($help_ordered);
        help_layout_set_section($help_lang, $help_kind, $help_section);
    }
    $help_kb = help_layout_editor_payload($help_lang, $help_kind, $textbotlang, null, $help_from);
    Editmessagetext($from_id, $message_id, $textbotlang['Admin']['Help']['layoutCaption'], $help_kb, 'HTML');
} elseif (preg_match('/^help_lay_hide:(categories|tutorials|panel|product|category|gateway|langpick):(fa|en):(\d+)(?::(pe))?$/', $datain, $help_m) && $adminrulecheck['rule'] == "administrator") {
    // 🚫 مخفی / 👁 نمایش for one button. Display only: the item itself, its
    // database row and its own on/off switch are never touched.
    $help_kind = $help_m[1];
    $help_lang = $help_m[2];
    $help_idx = (int) $help_m[3];
    $help_from = $help_m[4] ?? '';
    $help_items = help_layout_items($help_lang, $help_kind);
    $help_section = help_layout_section($help_lang, $help_kind);
    $help_ordered = help_layout_apply_order(array_keys($help_items), $help_section['order']);
    $help_key = $help_ordered[$help_idx] ?? null;
    if ($help_key !== null) {
        $help_hidden = $help_section['hidden'];
        if (!empty($help_hidden[(string) $help_key])) {
            unset($help_hidden[(string) $help_key]);
        } else {
            // refuse the last visible one: a keyboard with nothing on it is a
            // dead screen for the customer, and there is no undo from there
            $help_visible = 0;
            foreach ($help_ordered as $help_k) {
                // 🧩 حجم دلخواه is not a plan: only some panels offer it, so it
                // never counts as the button that has to stay
                if ($help_kind === 'product' && (string) $help_k === 'cvol') {
                    continue;
                }
                if (empty($help_hidden[(string) $help_k])) {
                    $help_visible++;
                }
            }
            if ($help_visible <= 1 && !($help_kind === 'product' && (string) $help_key === 'cvol')) {
                telegram('answerCallbackQuery', [
                    'callback_query_id' => $callback_query_id,
                    'text' => $textbotlang['Admin']['Help']['hideLastAlert'],
                    'show_alert' => true,
                ]);
                return;
            }
            $help_hidden[(string) $help_key] = true;
        }
        $help_section['hidden'] = $help_hidden;
        help_layout_set_section($help_lang, $help_kind, $help_section);
    }
    $help_kb = help_layout_editor_payload($help_lang, $help_kind, $textbotlang, $help_idx, $help_from);
    Editmessagetext($from_id, $message_id, $textbotlang['Admin']['Help']['layoutCaption'], $help_kb, 'HTML');
} elseif (preg_match('/^help_lay_reset:(categories|tutorials|panel|product|category|gateway|langpick):(fa|en)(?::(pe))?$/', $datain, $help_m) && $adminrulecheck['rule'] == "administrator") {
    $help_kind = $help_m[1];
