    $bt_rp_done = bt_reset_apply_mask($bt_lang, $bt_mask, $textbotlang);
    $textbotlang = panel_texts();
    list($bt_home, $bt_kb) = keyboard_list_text($bt_lang);
    $bt_rp_msg = empty($bt_rp_done)
        ? "ℹ️ چیزی برای ریست نبود - بخش‌های انتخابی از قبل روی پیش‌فرض بودن."
        : ("✅ <b>ریست شد:</b>\n" . implode("\n", $bt_rp_done));
    Editmessagetext($from_id, $message_id, $bt_rp_msg . "\n\n" . $bt_home, $bt_kb, 'HTML');
} elseif (preg_match('/^bt_group_resetall\|([^|]+)\|(.+)$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    $bt_lang = $dataget[1];
    $bt_group = $dataget[2];
    if (!in_array($bt_lang, panel_langs(), true)) {
        $bt_lang = 'fa';
    }
    // ⏱'s index owns no items itself: «reset all» there means all of its sub-screens'
    $bt_reset_groups = $bt_group === 'payg' ? array_keys($textbotlang['bottext']['paygSubs'] ?? []) : ($bt_group === 'cvol' ? ['cvol', 'cvolpieces'] : [$bt_group]);
    $bt_group_keys = array_column(array_filter($textbotlang['bottext']['items'], function ($it) use ($bt_reset_groups) {
        return in_array($it['group'] ?? '', $bt_reset_groups, true);
    }), 'key');
    bottext_reset_keys($bt_group_keys, $bt_lang);
    // 📲's group also holds the look of its page
    if ($bt_group === 'subapps') {
        feature_setting_set('subapp_look', $bt_lang, 'glass');
        feature_setting_set('subapp_theme', $bt_lang, 'auto');
        subapp_layout_set($bt_lang, subapp_layout_defaults());
        feature_setting_set('subapp_links', $bt_lang, '');
    }
    $textbotlang = panel_texts();
    list($bt_group_text, $bt_group_kb) = keyboard_list_text($bt_lang, $bt_group);
    Editmessagetext($from_id, $message_id, $textbotlang['bottext']['resetAllDone'] . "\n\n" . $bt_group_text, $bt_group_kb, 'HTML');
} elseif (preg_match('/^salay\|([a-z]{2})(?:\|(\w+))?$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    // 🧩 the layout of the page an app opens through: move, show or remove its parts
    $sa_lang = in_array($dataget[1], panel_langs(), true) ? $dataget[1] : 'fa';
    $sa_do = $dataget[2] ?? '';
    $sa_lay = subapp_layout($sa_lang);
    $sa_changed = false;
    if (strpos($sa_do, 'tg_') === 0 && in_array(substr($sa_do, 3), subapp_layout_elements(), true)) {
        $el = substr($sa_do, 3);
        $sa_lay['hide'] = in_array($el, $sa_lay['hide'], true) ? array_values(array_diff($sa_lay['hide'], [$el])) : array_merge($sa_lay['hide'], [$el]);
        $sa_changed = true;
    } elseif (preg_match('/^mv_(\w+)_([ud])$/', $sa_do, $mv) && in_array($mv[1], $sa_lay['order'], true)) {
        $i = array_search($mv[1], $sa_lay['order'], true);
        $j = $mv[2] === 'u' ? $i - 1 : $i + 1;
        if (isset($sa_lay['order'][$j])) {
            [$sa_lay['order'][$i], $sa_lay['order'][$j]] = [$sa_lay['order'][$j], $sa_lay['order'][$i]];
            $sa_changed = true;
        }
    } elseif (strpos($sa_do, 'cy_') === 0 && isset(subapp_layout_choices()[substr($sa_do, 3)])) {
        // the next choice of that field, round and round
        $field = substr($sa_do, 3);
        $opts = subapp_layout_choices()[$field];
        $sa_lay[$field] = $opts[(array_search($sa_lay[$field], $opts, true) + 1) % count($opts)];
        $sa_changed = true;
    } elseif ($sa_do === 'reset') {
        $sa_lay = subapp_layout_defaults();
        $sa_changed = true;
    }
    if ($sa_changed) {
        subapp_layout_set($sa_lang, $sa_lay);
    }
    list($sa_text, $sa_kb) = subapp_layout_screen($sa_lang);
    Editmessagetext($from_id, $message_id, $sa_text, $sa_kb, 'HTML');
} elseif (preg_match('/^salinks\|([a-z]{2})(?:\|(\w+))?$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    // 🔗 the apps' download links: the list of apps, and one app's links
    $sa_lang = in_array($dataget[1], panel_langs(), true) ? $dataget[1] : 'fa';
    $sa_app = $dataget[2] ?? '';
    if ($sa_app === 'reset') {
        feature_setting_set('subapp_links', $sa_lang, '');
        $sa_app = '';
    }
    step('home', $from_id);
    list($sa_text, $sa_kb) = subapp_links_screen($sa_lang, $sa_app);
    Editmessagetext($from_id, $message_id, $sa_text, $sa_kb, 'HTML');
} elseif (preg_match('/^salinkset\|([a-z]{2})\|(\w+)\|(play|github|ios|site)\|([dn])$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    // ↩️ the default link back, or 🚫 none
    $sa_lang = in_array($dataget[1], panel_langs(), true) ? $dataget[1] : 'fa';
    if (in_array($dataget[2], array_column(subapp_apps(), 'id'), true)) {
        subapp_link_set($sa_lang, $dataget[2], $dataget[3], $dataget[4] === 'n' ? '-' : '');
    }
    list($sa_text, $sa_kb) = subapp_links_screen($sa_lang, $dataget[2]);
    Editmessagetext($from_id, $message_id, $sa_text, $sa_kb, 'HTML');
} elseif (preg_match('/^salinkedit\|([a-z]{2})\|(\w+)\|(play|github|ios|site)$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    // ✏️ a link typed in: asked for here, taken in the step below
    $sa_lang = in_array($dataget[1], panel_langs(), true) ? $dataget[1] : 'fa';
    $sa_found = array_column(subapp_apps(), null, 'id')[$dataget[2]] ?? null;
    if ($sa_found !== null) {
        savedata("clear", "sa_lang", $sa_lang);
        savedata("save", "sa_app", $dataget[2]);
        savedata("save", "sa_kind", $dataget[3]);
        savedata("save", "sa_msgid", $message_id);
        step("sa_link_set", $from_id);
        $sa_kinds = ['play' => 'seLinkPlay', 'github' => 'seLinkGithub', 'ios' => 'seLinkIos', 'site' => 'seLinkSite'];
        Editmessagetext($from_id, $message_id, strtr($textbotlang['bottext']['saLinkPrompt'], ['{kind}' => $textbotlang['panel'][$sa_kinds[$dataget[3]]], '{app}' => $sa_found['name']]),
            json_encode(['inline_keyboard' => [[['text' => '❌ انصراف', 'callback_data' => "salinks|{$sa_lang}|{$dataget[2]}", 'style' => 'danger']]]]), 'HTML');
    }
} elseif (preg_match('/^salook\|([a-z]{2})(?:\|(\w+))?$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    // 🖼 the look of the page an app of 📲's list opens: the picker, and a tap on a look
    $sa_lang = in_array($dataget[1], panel_langs(), true) ? $dataget[1] : 'fa';
    $sa_looks = subapp_looks();
    $sa_pick = $dataget[2] ?? '';
    $sa_tb = $textbotlang['bottext'];
    $sa_themes = subapp_themes();
    if ($sa_pick !== '' && isset($sa_looks[$sa_pick])) {
        feature_setting_set('subapp_look', $sa_lang, $sa_pick);
        telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => strtr($sa_tb['saLookSaved'], ['{look}' => $sa_looks[$sa_pick], '{lang}' => $sa_tb['langs'][$sa_lang] ?? $sa_lang])]);
    } elseif (strpos($sa_pick, 'th_') === 0 && isset($sa_themes[substr($sa_pick, 3)])) {
        // dark / light / the device's
        feature_setting_set('subapp_theme', $sa_lang, substr($sa_pick, 3));
        telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => strtr($sa_tb['saThemeSaved'], ['{theme}' => $sa_themes[substr($sa_pick, 3)], '{lang}' => $sa_tb['langs'][$sa_lang] ?? $sa_lang])]);
    }
    $sa_cur = subapp_look($sa_lang);
    $sa_curTheme = subapp_theme($sa_lang);
    $sa_rows = [];
    foreach ($sa_looks as $sa_k => $sa_n) {
        // the look itself, then its preview: the page with made-up data
        $sa_rows[] = [
            ['text' => ($sa_k === $sa_cur ? '✅ ' : '') . $sa_n, 'callback_data' => "salook|{$sa_lang}|{$sa_k}", 'style' => $sa_k === $sa_cur ? 'success' : 'primary'],
            ['text' => $sa_tb['saLookPreview'], 'url' => subapp_preview_link($sa_k, $sa_lang)],
        ];
    }
    // then dark / light / the device's, in one row
    $sa_row = [];
    foreach ($sa_themes as $sa_k => $sa_n) {
        $sa_row[] = ['text' => ($sa_k === $sa_curTheme ? '✅ ' : '') . $sa_n, 'callback_data' => "salook|{$sa_lang}|th_{$sa_k}", 'style' => $sa_k === $sa_curTheme ? 'success' : 'primary'];
    }
    $sa_rows[] = $sa_row;
    $sa_rows[] = [['text' => '🔙 بازگشت به منوی قبل', 'callback_data' => "bt_group|{$sa_lang}|subapps", 'style' => 'danger']];
    $sa_rows[] = [['text' => $sa_tb['btn_close'], 'callback_data' => 'bt_close', 'style' => 'danger']];
    Editmessagetext($from_id, $message_id, strtr($sa_tb['saLookCaption'], ['{lang}' => $sa_tb['langs'][$sa_lang] ?? $sa_lang, '{current}' => $sa_looks[$sa_cur], '{theme}' => $sa_themes[$sa_curTheme]]), json_encode(['inline_keyboard' => $sa_rows]), 'HTML');
} elseif (preg_match('/^bt_group\|([^|]+)\|(.+)$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    $bt_lang = $dataget[1];
    $bt_group = $dataget[2];
    if (!in_array($bt_lang, panel_langs(), true)) {
        $bt_lang = 'fa';
    }
    list($bt_group_text, $bt_group_kb) = keyboard_list_text($bt_lang, $bt_group);
    $bt_group_res = Editmessagetext($from_id, $message_id, $bt_group_text, $bt_group_kb, 'HTML');
    // a screen Telegram refuses (too many buttons, a bad icon, ...) used to be a
    // silent dead button: say what it answered
    if (is_array($bt_group_res) && empty($bt_group_res['ok']) && stripos((string) ($bt_group_res['description'] ?? ''), 'not modified') === false) {
        telegram('answerCallbackQuery', ['callback_query_id' => $callback_query_id, 'text' => '❌ تلگرام این صفحه رو قبول نکرد: ' . mb_substr((string) ($bt_group_res['description'] ?? '?'), 0, 150), 'show_alert' => true]);
    }
} elseif (preg_match('/^btsw\|tog\|([a-z]{2})\|(.+)$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    $bt_lang = in_array($dataget[1], panel_langs(), true) ? $dataget[1] : 'fa';
    $bt_key = $dataget[2];
    // only an item that actually has a switch - anything else is always on and
    // must not be given an off state by a hand-made callback
    if (array_key_exists($bt_key, bt_item_switch_defaults())) {
        bt_item_set_enabled($bt_key, $bt_lang, !bt_item_enabled($bt_key, $bt_lang));
        list($btm_text, $btm_kb) = bottext_item_menu_payload($bt_key, $bt_lang, $textbotlang);
        Editmessagetext($from_id, $message_id, $btm_text, $btm_kb, 'HTML');
    }
} elseif (preg_match('/^bt_edit\|([^|]+)\|(.+)$/', $datain, $dataget)) {
    $bt_lang = $dataget[1];
    $bt_key = subapps_legacy_key($dataget[2]);
    if (!in_array($bt_lang, panel_langs(), true)) {
        $bt_lang = 'fa';
    }
    list($btm_text, $btm_kb) = bottext_item_menu_payload($bt_key, $bt_lang, $textbotlang);
    Editmessagetext($from_id, $message_id, $btm_text, $btm_kb, 'HTML');
} elseif ($user['step'] == "sa_link_set") {
    // ✏️ the link typed for an app's store (🔗 لینک دانلود برنامه‌ها)
    $sa_data = json_decode((string) ($user['Processing_value'] ?? ''), true);
    $sa_data = is_array($sa_data) ? $sa_data : [];
    $sa_lang = in_array($sa_data['sa_lang'] ?? '', panel_langs(), true) ? $sa_data['sa_lang'] : 'fa';
    $sa_app = (string) ($sa_data['sa_app'] ?? '');
    $sa_kind = (string) ($sa_data['sa_kind'] ?? '');
    $sa_msgid = intval($sa_data['sa_msgid'] ?? 0);
    $sa_in = trim((string) ($update['message']['text'] ?? $text));
    if (!in_array($sa_app, array_column(subapp_apps(), 'id'), true) || !in_array($sa_kind, subapp_link_kinds(), true)) {
        step('home', $from_id);
        sendmessage($from_id, $textbotlang['bottext']['msg_session'], $keyboardadmin, 'HTML');
        return;
    }
    if ($sa_in !== '0' && $sa_in !== '-' && !subapp_link_valid($sa_in)) {
        sendmessage($from_id, $textbotlang['bottext']['saLinkInvalid'], null, 'HTML');
        return;
    }
    subapp_link_set($sa_lang, $sa_app, $sa_kind, $sa_in === '0' ? '' : $sa_in);
    step('home', $from_id);
    if ($message_id) {
        deletemessage($from_id, $message_id);
    }
    list($sa_text, $sa_kb) = subapp_links_screen($sa_lang, $sa_app);
    $sa_text = $textbotlang['bottext']['saLinkSaved'] . "\n\n" . $sa_text;
    if ($sa_msgid > 0) {
        Editmessagetext($from_id, $sa_msgid, $sa_text, $sa_kb, 'HTML');
    } else {
        sendmessage($from_id, $sa_text, $sa_kb, 'HTML');
    }
} elseif ($user['step'] == "get_new_text") {
    $userdata = json_decode((string) ($user['Processing_value'] ?? ''), true);
    if (!is_array($userdata)) {
        $userdata = [];
    }
    $bt_lang = $userdata['bt_lang'] ?? 'fa';
    $bt_key = $userdata['bt_key'] ?? '';
    $bt_msgid = intval($userdata['bt_msgid'] ?? 0);
    if (!in_array($bt_lang, panel_langs(), true)) {
        $bt_lang = 'fa';
    }
    $bt_valid = false;
    foreach (($textbotlang['bottext']['items'] ?? []) as $bt_it) {
        if (($bt_it['key'] ?? '') === $bt_key) {
            $bt_valid = true;
            break;
        }
    }
    if ($bt_key === 'users.unknownMsg') {
        $bt_valid = true;
    }
    if (in_array($bt_key, ['textbot.afterText', 'users.status.getConfigHint'], true)) {
        $bt_valid = true;
    }
    if (!$bt_valid || $bt_key === '') {
        step('home', $from_id);
        sendmessage($from_id, $textbotlang['bottext']['msg_session'], $keyboardadmin, 'HTML');
        return;
    }
    $bt_new = (string) ($update['message']['text'] ?? $text);
    // Formatting made with Telegram's own tools (bold, italic, a quote, a
    // link...) arrives as entities, not as the tags the prompt lists - it was
    // dropped. A text with no typed tags of its own takes it all as HTML,
    // premium emoji included; one with typed tags keeps them, as before.
    $bt_ents_all = is_array($update['message']['entities'] ?? null) ? $update['message']['entities'] : [];
    $bt_has_format = false;
    foreach ($bt_ents_all as $bt_ent) {
        if (in_array($bt_ent['type'] ?? '', ['bold', 'italic', 'underline', 'strikethrough', 'spoiler', 'code', 'pre', 'text_link', 'text_mention', 'blockquote', 'expandable_blockquote'], true)) {
            $bt_has_format = true;
        }
    }
    if ($bt_has_format && strpos($bt_new, '<') === false) {
        [$bt_new] = entities_to_html($bt_new, $bt_ents_all);
    } elseif (!empty($update['message']['entities']) && is_array($update['message']['entities'])) {
        // bake premium (custom) emoji into <tg-emoji> HTML tags so the bot re-sends them rendered
        $bt_ents = [];
        foreach ($update['message']['entities'] as $bt_ent) {
            if (($bt_ent['type'] ?? '') === 'custom_emoji' && !empty($bt_ent['custom_emoji_id']) && isset($bt_ent['offset'], $bt_ent['length'])) {
                $bt_ents[] = $bt_ent;
            }
        }
        if (!empty($bt_ents)) {
            usort($bt_ents, function ($a, $b) {
                return intval($b['offset']) <=> intval($a['offset']);
            });
            $bt_utf16 = mb_convert_encoding($bt_new, 'UTF-16LE', 'UTF-8');
            foreach ($bt_ents as $bt_ent) {
                $bt_bo = intval($bt_ent['offset']) * 2;
                $bt_bl = intval($bt_ent['length']) * 2;
                $bt_char = substr($bt_utf16, $bt_bo, $bt_bl);
                if ($bt_char === '' || $bt_char === false) {
                    continue;
                }
                $bt_tag = '<tg-emoji emoji-id="' . $bt_ent['custom_emoji_id'] . '">' . mb_convert_encoding($bt_char, 'UTF-8', 'UTF-16LE') . '</tg-emoji>';
                $bt_utf16 = substr($bt_utf16, 0, $bt_bo) . mb_convert_encoding($bt_tag, 'UTF-16LE', 'UTF-8') . substr($bt_utf16, $bt_bo + $bt_bl);
            }
            $bt_new = mb_convert_encoding($bt_utf16, 'UTF-8', 'UTF-16LE');
        }
    }
    $bt_new = trim($bt_new);
    if ($bt_new === '') {
        sendmessage($from_id, $textbotlang['bottext']['msg_empty'], $btpromptcancel, 'HTML');
        return;
    }
    $bt_map = (isset($setting['text_edit']) && $setting['text_edit']) ? json_decode($setting['text_edit'], true) : [];
    if (!is_array($bt_map)) {
        $bt_map = [];
    }
    $bt_reset = $bt_new === '0';
    if ($bt_reset) {
        if (isset($bt_map[$bt_lang]) && is_array($bt_map[$bt_lang])) {
            bottext_dotted_unset($bt_map[$bt_lang], $bt_key);
            if (empty($bt_map[$bt_lang])) {
                unset($bt_map[$bt_lang]);
            }
        }
    } else {
        if (!isset($bt_map[$bt_lang]) || !is_array($bt_map[$bt_lang])) {
            $bt_map[$bt_lang] = [];
        }
        bottext_dotted_set($bt_map[$bt_lang], $bt_key, $bt_new);
    }
    update("setting", "text_edit", empty($bt_map) ? null : json_encode($bt_map, JSON_UNESCAPED_UNICODE), null, null);
    step('home', $from_id);
    $textbotlang = panel_texts();
    // back on the screen the text was edited from, its 🔙 to the menu before
    // it - not the top of 🎨, which made «back» look broken - quoting the new text
    lang_tab_texts($bt_lang, true);
    list($bt_home, $bt_kb) = bottext_item_menu_payload($bt_key, $bt_lang, $textbotlang);
    $bt_done_msg = ($bt_reset ? $textbotlang['bottext']['msg_reset_done'] : $textbotlang['bottext']['msg_saved']) . "\n\n" . $bt_home;
    if ($message_id) {
        deletemessage($from_id, $message_id);
    }
    if ($bt_msgid > 0) {
        Editmessagetext($from_id, $bt_msgid, $bt_done_msg, $bt_kb, 'HTML');
    } else {
        sendmessage($from_id, $bt_done_msg, $bt_kb, 'HTML');
    }
}
